const AI_COORD_CSS=".ai-head{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.ai-head h3{margin:0}.ai-tabs{display:flex;gap:6px;margin:10px 0}.ai-tabs a{padding:8px 14px;border:1px solid #e2e4e8;border-radius:8px;color:inherit;text-decoration:none}.ai-tabs a[aria-current]{background:#191919;color:white}.ai-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:10px 0}.ai-metrics>div{background:#f7f8fa;border:1px solid #e2e4e8;padding:10px;border-radius:8px;min-width:0}.ai-metrics small,.ai-card>small,.ai-line small{display:block;font-size:13px;color:#656b74;overflow-wrap:anywhere}.ai-metrics strong{display:block;font-size:25px;font-variant-numeric:tabular-nums}.ai-total>div{background:#202124;color:#fff}.ai-total small{color:#d5d7da}.ai-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.ai-filter{display:flex;align-items:end;gap:10px;margin:16px 0}.ai-filter label{flex:1;max-width:300px}.ai-detail{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:12px 0}.ai-line{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #e2e4e8;color:inherit;text-decoration:none}.ai-line>span{min-width:0;overflow-wrap:anywhere}.ai-line>span:last-child{text-align:right;flex:0 1 35%}.ai-line strong{display:block;line-height:1.35}.ai-line b{font-size:13px}@media(max-width:760px){.ai-grid,.ai-detail{grid-template-columns:1fr}.ai-metrics>div{padding:8px}.ai-metrics strong{font-size:23px}.ai-metrics small,.ai-card>small,.ai-line small,.ai-line b{font-size:14px}.ai-line strong{font-size:16px}.ai-head a,.ai-tabs a{font-size:15px}.ai-filter label{max-width:none}}";
function aiSummary(assignments,activity){
const owners=new Set(["ChatGPT","Claude","Unassigned"]);for(const r of assignments||[])owners.add(r.owner);for(const r of activity||[])owners.add(r.actor);
return [...owners].map(owner=>{const assigned=assignments?.filter(r=>r.owner===owner),active=assigned?.reduce((s,r)=>s+r.n,0);const count=states=>assigned===undefined?null:assigned.filter(r=>states.includes(r.status)).reduce((s,r)=>s+r.n,0);const report=activity?.find(r=>r.actor===owner);return {owner,active,working:count(["In progress"]),blocked:count(["Blocked"]),verify:count(["Ready to verify","Needs verification"]),unstarted:count(["Not started"]),updates:activity===null?null:report?.updates??0,touched:activity===null?null:report?.touched??0,completed:activity===null?null:report?.completed??0,last:report?.latest||null}});
}
async function aiPage(env,u){
const now=new Date(),days=u.searchParams.get("days")==="7"?7:1,cutoff=new Date(now.getTime()-days*86400000).toISOString(),owner=(u.searchParams.get("owner")||"").slice(0,80);
const [assignments,activity,work,changes,schedules,done]=await Promise.all([
safeRows(env.TRACKER,"SELECT owner,status,COUNT(*) n FROM tracker_active_tasks WHERE status NOT IN ('Done','Deferred') GROUP BY owner,status ORDER BY owner,status"),
safeRows(env.TRACKER,"SELECT h.actor,COUNT(*) updates,COUNT(DISTINCT h.task_id) touched,COUNT(DISTINCT CASE WHEN json_extract(h.before_json,'$.status')<>'Done' AND json_extract(h.after_json,'$.status')='Done' AND t.status='Done' THEN h.task_id END) completed,MAX(h.changed_at) latest FROM tracker_history h JOIN tracker_active_tasks t ON t.task_id=h.task_id WHERE julianday(h.changed_at)>=julianday(?) GROUP BY h.actor ORDER BY h.actor",cutoff),
safeRows(env.TRACKER,"SELECT task_id,project,task,priority,status,owner,updated_at FROM tracker_active_tasks WHERE status NOT IN ('Done','Deferred') AND (?='' OR owner=?) ORDER BY CASE WHEN status='Blocked' THEN 0 WHEN status IN ('Ready to verify','Needs verification') THEN 1 WHEN status='In progress' THEN 2 ELSE 3 END,CASE priority WHEN 'P0' THEN 0 WHEN 'P1' THEN 1 ELSE 2 END,project,task_id LIMIT 101",owner,owner),
safeRows(env.TRACKER,"SELECT t.task_id,t.project,t.task,h.actor,h.changed_at,json_extract(h.before_json,'$.status') previous_status,json_extract(h.after_json,'$.status') new_status FROM tracker_history h JOIN tracker_active_tasks t ON t.task_id=h.task_id WHERE julianday(h.changed_at)>=julianday(?) AND (?='' OR h.actor=?) ORDER BY h.id DESC LIMIT 40",cutoff,owner,owner),
safeRows(env.TRACKER,"SELECT title,cadence,enabled,scope,observed_at FROM lifecycle_schedule_observations ORDER BY title LIMIT 100"),
safeFirst(env.TRACKER,"SELECT COUNT(DISTINCT h.task_id) n FROM tracker_history h JOIN tracker_active_tasks t ON t.task_id=h.task_id WHERE julianday(h.changed_at)>=julianday(?) AND json_extract(h.before_json,'$.status')<>'Done' AND json_extract(h.after_json,'$.status')='Done' AND t.status='Done'",cutoff)]);
const summary=aiSummary(assignments,activity),selected=summary.find(r=>r.owner===owner);
const n=v=>v==null?"—":fmt(v),linkTo=(o,d=days)=>"/assistants?days="+d+(o?"&amp;owner="+encodeURIComponent(o):""),metric=(l,v)=>'<div><small>'+esc(l)+'</small><strong>'+esc(n(v))+'</strong></div>';
const cards=summary.filter(r=>["ChatGPT","Claude","Unassigned"].includes(r.owner)||(r.active||r.updates)).map(r=>'<article class="ai-card"><div class="ai-head"><h3>'+esc(r.owner)+'</h3><a href="'+linkTo(r.owner)+'">Filter ↗</a></div><div class="ai-metrics">'+metric("Open assignments",r.active)+metric("In progress",r.working)+metric("Blocked",r.blocked)+metric("Verification",r.verify)+metric("Reported updates",r.updates)+metric("Reported Done",r.completed)+'</div><small>Last recorded edit: '+esc(r.last||"None in window")+'</small></article>').join("");
const rows=(work||[]).slice(0,100).map(r=>'<a class="ai-line" href="/development?q='+encodeURIComponent(r.task_id)+'"><span><small>'+esc(r.project+' · '+r.task_id+' · '+r.priority)+'</small><strong>'+esc(r.task)+'</strong></span><span><b>'+esc(r.status)+'</b><small>'+esc(r.owner)+'</small></span></a>').join("");
const events=(changes||[]).map(r=>'<a class="ai-line" href="/development?q='+encodeURIComponent(r.task_id)+'"><span><small>'+esc(r.project+' · '+r.task_id)+'</small><strong>'+esc(r.task)+'</strong><small>'+esc(r.previous_status===r.new_status?'Recorded edit':(r.previous_status||"—")+" → "+(r.new_status||"—"))+'</small></span><span><b>'+esc(r.actor)+'</b><small>'+esc(r.changed_at)+' UTC</small></span></a>').join("");
const body='<div class="ai-head"><small class="muted">Assignments and reported activity · '+esc(now.toISOString().slice(0,16).replace("T"," "))+' UTC</small><a href="/development/integration">Assistant integration ↗</a></div><div class="ai-tabs"><a href="'+linkTo(owner,1)+'"'+(days===1?' aria-current="page"':'')+'>24 hours</a><a href="'+linkTo(owner,7)+'"'+(days===7?' aria-current="page"':'')+'>7 days</a></div><div class="ai-metrics ai-total">'+metric("Open assignments",assignments===null?null:assignments.reduce((s,r)=>s+r.n,0))+metric("Recorded edits",activity===null?null:activity.reduce((s,r)=>s+r.updates,0))+metric("Distinct tasks moved to Done",done?.n)+'</div><div class="ai-grid">'+cards+'</div><form class="ai-filter" method="get" action="/assistants"><input type="hidden" name="days" value="'+days+'"><label>Assistant / owner '+trSelect("owner",summary.map(r=>r.owner),owner,"All")+'</label><button class="button">Filter</button></form><div class="ai-detail"><article><div class="ai-head"><h3>Open assignments'+(selected?' · '+esc(owner):'')+'</h3><a href="/development'+(selected?'?owner='+encodeURIComponent(owner):'')+'">Task tracker ↗</a></div>'+(work===null?'<p class="warn">Assignments unavailable.</p>':rows||'<p class="muted">No open assignments.</p>')+(work?.length>100?'<p class="muted">First 100 assignments shown. Filter by owner for more.</p>':'')+'</article><article><div class="ai-head"><h3>Recent reported activity</h3><a href="/development/history">History ↗</a></div>'+(changes===null?'<p class="warn">History unavailable.</p>':events||'<p class="muted">No recorded edits in this window.</p>')+'</article></div><article><h3>Last observed schedules</h3>'+(schedules===null?'<p class="warn">Schedule observations unavailable.</p>':schedules.length?schedules.map(r=>'<div class="ai-line"><span><strong>'+esc(r.title)+'</strong><small>'+esc(r.scope||"")+' · '+esc(r.cadence)+'</small></span><span><b>'+esc(r.enabled?'Enabled when observed':'Disabled when observed')+'</b><small>'+esc(r.observed_at)+' UTC</small></span></div>').join(""):'<p class="muted">No observations saved.</p>')+'</article><p class="muted">An assignment is not proof of an active run. Reported edits and Done transitions are tracker history, not verified deployments. Per-actor Done counts may overlap; the overall count is distinct. No assignments, schedules or credentials are modified here.</p>';
return response(trackerPage("Assistant coordination",trackerTabs()+body),200,"text/html;charset=utf-8");
}
const AC_CSS=".ac-head{display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px}.ac-head h3,.ac-head h2{margin:0}.ac-head small{color:#656b74}.ac-tabs{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:4px;padding:4px;background:#e9ebee;border-radius:10px;margin-bottom:12px;max-width:none}.ac-tabs a{display:flex;align-items:center;justify-content:center;gap:5px;text-align:center;min-height:44px;padding:6px 8px;border-radius:7px;color:#505762;text-decoration:none;font-size:13px;font-weight:600}.ac-tabs a[aria-current=page]{background:#191919;color:white}.ac-filter{display:flex;align-items:end;gap:10px;flex-wrap:wrap;margin:0 0 14px}.ac-filter label{display:block;flex:1;max-width:360px}.ac-list{display:grid;gap:8px}.ac-row{display:flex;gap:12px;align-items:center;justify-content:space-between;padding:12px;min-width:0}.ac-row-main{min-width:0;flex:1;overflow-wrap:anywhere}.ac-row h3{font-size:16px;line-height:1.3;margin:5px 0}.ac-row small{font-size:13px;color:#656b74}.ac-meta{display:flex;align-items:center;flex-wrap:wrap;gap:5px 8px;font-size:13px}.ac-tag{background:#f1f2f4;border:1px solid #e2e4e8;border-radius:5px;padding:2px 5px;font-size:12px;color:#505762}.ac-instruction{white-space:pre-wrap;font-size:14px;margin:6px 0 0;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.ac-go{flex:none;font-size:14px;white-space:nowrap}.ac-preview{margin:0 0 14px}.ac-preview .ac-row{border:0;border-top:1px solid #e2e4e8;border-radius:0;padding:10px 0}.ac-preview .ac-instruction{display:none}@media(max-width:760px){.ac-tabs{grid-template-columns:repeat(3,minmax(0,1fr))}.ac-tabs a{font-size:14px;line-height:1.2;min-height:44px;flex-wrap:wrap}.ac-row{align-items:flex-start;flex-direction:column;gap:8px}.ac-row h3{font-size:17px}.ac-row small,.ac-meta,.ac-instruction{font-size:14px}.ac-go{align-self:flex-end;font-size:15px}.ac-preview .ac-row{gap:5px}.ac-filter label{max-width:none}.ac-head a{font-size:15px}}";
function acBuild(tasks,reviews,renewals,today){
const items=[];
for(const t of tasks||[]){const owner=t.action_status==="Needed",blocked=t.status==="Blocked",critical=t.priority==="P0",verify=["Ready to verify","Needs verification"].includes(t.status);if(!owner&&!blocked&&!critical&&!verify)continue;
items.push({id:"task:"+t.task_id,project:t.project,title:t.task,kind:"task",tags:[owner?"Owner action":null,blocked?"Blocked":null,critical?"P0":null,verify?"Verification":null].filter(Boolean),rank:owner&&critical?0:owner?2:blocked&&critical?3:blocked?5:verify?6:7,detail:[t.task_id,t.status,t.owner||"Unassigned"].join(" · "),instruction:owner?t.instructions||"":"",href:owner?"/development/notes#owner-"+encodeURIComponent(t.task_id):"/development?q="+encodeURIComponent(t.task_id),action:owner?"Respond":verify?"Verify":"Open task"})}
for(const r of reviews||[])items.push({id:"review:"+r.id,project:r.name,title:"Business review",kind:"review",tags:[r.review_due<today?"Overdue":r.review_due===today?"Due today":"Upcoming"],rank:r.review_due<=today?1:8,due:r.review_due,detail:r.decision||"Not reviewed",href:"/investments?edit="+encodeURIComponent(r.id)+"#iv-editor",action:"Review"});
for(const r of renewals||[])items.push({id:"renewal:"+r.id,project:r.project,title:r.vendor+" · "+r.service,kind:"renewal",tags:[r.next_due<today?"Overdue":r.next_due===today?"Due today":"Upcoming"],rank:r.next_due<=today?1:8,due:r.next_due,detail:r.amount_cents==null?"Amount unknown":pxMoney(r.amount_cents)+" · "+r.cadence,href:"/finance/expenses?edit="+encodeURIComponent(r.id)+"#px-form",action:"Review expense"});
return items.sort((a,b)=>a.rank-b.rank||(a.due||"9999").localeCompare(b.due||"9999")||a.project.localeCompare(b.project)||a.id.localeCompare(b.id))}
async function acRead(env){
const now=new Date(),today=now.toISOString().slice(0,10),reviewEnd=new Date(now.getTime()+7*86400000).toISOString().slice(0,10),renewalEnd=new Date(now.getTime()+30*86400000).toISOString().slice(0,10);
const [tasks,reviews,renewals]=await Promise.all([
safeRows(env.TRACKER,"SELECT t.task_id,t.project,t.task,t.priority,t.status,t.owner,a.action_status,a.instructions FROM tracker_active_tasks t LEFT JOIN tracker_owner_actions a ON a.task_id=t.task_id WHERE t.status NOT IN ('Done','Deferred') AND (a.action_status='Needed' OR t.status IN ('Blocked','Ready to verify','Needs verification') OR t.priority='P0') ORDER BY t.task_id LIMIT 1001"),
safeRows(env.TRACKER,"SELECT p.id,p.name,g.decision,g.review_due FROM lifecycle_business_goals g JOIN lifecycle_projects p ON p.id=g.lifecycle_id WHERE g.review_due<>'' AND g.review_due<=? AND (p.tracker_project IS NULL OR p.tracker_project IN (SELECT project FROM tracker_active_projects)) ORDER BY g.review_due,p.name LIMIT 1001",reviewEnd),
safeRows(env.PORTFOLIO,"SELECT id,project,vendor,service,amount_cents,next_due,cadence FROM portfolio_expenses WHERE state<>'Ended' AND next_due<>'' AND next_due<=? ORDER BY next_due,id LIMIT 1001",renewalEnd)]);
return {today,reviewEnd,renewalEnd,items:acBuild(tasks?.slice(0,1000),reviews?.slice(0,1000),renewals?.slice(0,1000),today),unavailable:[tasks===null?"Development and owner actions":null,reviews===null?"Business reviews":null,renewals===null?"Expenses and renewals":null].filter(Boolean),truncated:[tasks,reviews,renewals].some(r=>r?.length>1000)}}
function acMatch(r,view){return view==="all"||view==="owner"&&r.tags.includes("Owner action")||view==="critical"&&(r.tags.includes("P0")||r.tags.includes("Blocked"))||view==="verify"&&r.tags.includes("Verification")||view==="review"&&r.kind==="review"||view==="renewal"&&r.kind==="renewal"}
function acRow(r){return '<article class="ac-row"><div class="ac-row-main"><div class="ac-meta"><strong>'+esc(r.project)+'</strong>'+r.tags.map(t=>'<span class="ac-tag">'+esc(t)+'</span>').join('')+'</div><h3>'+esc(r.title)+'</h3><small>'+esc(r.detail)+(r.due?' · '+esc(r.due)+' UTC':'')+'</small>'+(r.instruction?'<p class="ac-instruction">'+esc(r.instruction)+'</p>':'')+'</div><a class="button ac-go" href="'+esc(r.href)+'">'+esc(r.action)+' ↗</a></article>'}
function acPanel(x){if(!x)return '';return '<article class="ac-preview"><div class="ac-head"><h3>Action center</h3><a href="/actions">All actions ↗</a></div><p class="muted">'+esc(x.unavailable.length||x.truncated?"Partial coverage · ":"")+fmt(x.items.length)+' recorded actions · '+fmt(x.items.filter(r=>acMatch(r,"owner")).length)+' owner decisions · '+fmt(x.items.filter(r=>r.rank<=2).length)+' immediate review flags</p>'+(x.items.length?x.items.slice(0,3).map(acRow).join(''):'<p class="muted">No actions recorded in available sources.</p>')+'</article>'}
async function acPage(env,u){const x=await acRead(env),views=[["all","All"],["owner","Owner actions"],["critical","Critical & blocked"],["verify","Verification"],["review","Business reviews"],["renewal","Renewals"]],view=views.some(([k])=>k===u.searchParams.get("view"))?u.searchParams.get("view"):"all",projects=[...new Set(x.items.map(r=>r.project))].sort(),project=projects.includes(u.searchParams.get("project"))?u.searchParams.get("project"):"",filtered=x.items.filter(r=>!project||r.project===project),rows=filtered.filter(r=>acMatch(r,view)),href=k=>"/actions?view="+k+(project?"&amp;project="+encodeURIComponent(project):"");
const body='<div class="ac-head"><span class="muted">UTC · '+esc(x.today)+'</span><a href="/briefing">Daily briefing ↗</a></div><nav class="ac-tabs" aria-label="Action filters" data-no-swipe>'+views.map(([k,l])=>'<a href="'+href(k)+'"'+(view===k?' aria-current="page"':'')+'>'+esc(l)+' <b>'+filtered.filter(r=>acMatch(r,k)).length+'</b></a>').join('')+'</nav><form class="ac-filter" method="get" action="/actions"><input type="hidden" name="view" value="'+esc(view)+'"><label>Business '+trSelect("project",projects,project,"All businesses")+'</label><button type="submit" class="button">Filter</button></form>'+(x.unavailable.length?'<p class="warn">Unavailable sources: '+esc(x.unavailable.join(", "))+'. Counts are partial.</p>':'')+(x.truncated?'<p class="warn">Source limit reached. Counts are partial.</p>':'')+'<div class="ac-head"><h2>'+fmt(rows.length)+' recorded actions</h2><small>Highest attention first</small></div><div class="ac-list">'+(rows.length?rows.map(acRow).join(''):'<article>No matching actions recorded.</article>')+'</div><p class="muted">One entry per task, review or expense. Categories can overlap. Reviews through '+esc(x.reviewEnd)+'; renewals through '+esc(x.renewalEnd)+', including overdue dates. Unknown deadlines are not treated as due. No automated assignments, notifications or spending. Customer response deadlines are not included because the inbox has no verified response SLA.</p>';
return response(page("Executive action center",body),200,"text/html;charset=utf-8")}
const IV_REVIEW_CSS=".iv-month{display:flex;align-items:end;gap:10px;flex-wrap:wrap;margin:12px 0}.iv-month label{display:flex;align-items:center;gap:8px}.iv-month input{font:inherit;padding:9px;border:1px solid #d9dde2;border-radius:8px}.iv-queue,#iv-editor{margin:12px 0}.iv-queue-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,2fr);gap:12px;padding:10px 0;border-top:1px solid #edf0f2;text-decoration:none;color:inherit}.iv-queue-row span{font-weight:600}.iv-queue-row small{display:block;font-size:13px;color:#656b74;font-weight:400}#iv-editor{scroll-margin-top:12px}#iv-editor .mailform{margin-top:10px}@media(max-width:760px){.iv-queue-row{font-size:15px;gap:8px}.iv-queue-row small,.iv-metrics small,.iv-meta,.iv-links a,.iv-head a{font-size:14px}.iv-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.iv-metrics strong{font-size:20px}.iv-month label{font-size:15px}.iv-month input{max-width:100%}}";
function ivReviewPriority(r,today){
const p=r.p;
if(p.decision==="Pause")return {rank:0,label:"Review paused business",reason:"Owner recorded Pause"};
if(p.budget_cents!=null&&((r.commit?.known>0&&r.commit.cents>p.budget_cents)||(r.plan?.known>0&&r.plan.cents>p.budget_cents)))return {rank:1,label:"Review spending ceiling",reason:"Known commitments or estimates exceed ceiling"};
if(p.review_due&&p.review_due<=today)return {rank:2,label:p.review_due<today?"Review overdue":"Review due today",reason:"Owner review date "+p.review_due};
if(!p.tracker_project)return {rank:5,label:"Validate concept",reason:"Draft business; verify demand before investment"};
if(r.progress?.p0>0)return {rank:3,label:"Critical work remains",reason:r.progress.p0+" open P0 tasks"};
if(p.profit_cents==null||p.revenue_cents==null||!r.actual||!p.review_due||!p.decision||p.decision==="Not reviewed"||!r.progress||!r.commit||!r.plan||r.commit.unknown>0||r.plan.selected>r.plan.known)return {rank:4,label:"Complete business review",reason:"Goals, actuals, review date, decision or source coverage incomplete"};
if(r.actual.profit<p.profit_cents||r.actual.revenue<p.revenue_cents)return {rank:4,label:"Review target gap",reason:"Reconciled result below an owner target"};
return {rank:6,label:"Review on schedule",reason:"Targets met in selected reporting month; no investment approval implied"};
}
function ivQueue(rows,today){return rows.map(r=>({r,q:ivReviewPriority(r,today)})).sort((a,b)=>a.q.rank-b.q.rank||a.r.p.name.localeCompare(b.r.p.name))}
