function pfModel(catalog,reports,commitments,month,previous){
const m=new Map(reports.map(r=>[r.project+"|"+r.month,r])),c=new Map(commitments.map(r=>[r.project,r]));
const actual=r=>r?{revenue:r.revenue_cents-r.refund_cents,cost:r.fees_cents+r.hosting_cents+r.other_cents,profit:r.revenue_cents-r.refund_cents-r.fees_cents-r.hosting_cents-r.other_cents}:null;
const rows=catalog.map(([key,name])=>{let now=actual(m.get(key+"|"+month)),prior=actual(m.get(key+"|"+previous)),forecast=c.get(name);return {key,name,now,prior,delta:now&&prior?now.profit-prior.profit:null,margin:now&&now.revenue>0?now.profit/now.revenue*100:null,forecast:forecast?.known?forecast.monthly:null,unknown:forecast?.unknown??null,records:forecast?.records??0}});
const ready=rows.filter(r=>r.now);const total=ready.length?ready.reduce((a,r)=>({revenue:a.revenue+r.now.revenue,cost:a.cost+r.now.cost,profit:a.profit+r.now.profit}),{revenue:0,cost:0,profit:0}):null;
const shared=c.get("Shared systems");return {rows,ready:ready.length,total,shared:shared?.known?shared.monthly:null,sharedUnknown:shared?.unknown??null,sharedRecords:shared?.records??0};
}
