const html='<div class="pf-toolbar"><form method="get" action="/finance/profitability"><label>Reporting month <input type="month" name="month" min="2000-01" max="'+esc(current)+'" value="'+esc(month)+'"></label><button class="button" type="submit">View month</button></form></div><div class="pf-summary"><div class="pf-head"><h2>Portfolio actuals · '+esc(month)+'</h2><span>'+esc(status)+'</span></div><div class="pf-metrics">'+metric("Net revenue",money(m.total?.revenue))+metric("Actual costs",money(m.total?.cost))+metric("Operating profit",money(m.total?.profit))+'</div></div><article class="pf-shared"><h3>Shared recurring commitments</h3><strong>'+esc(money(m.shared))+' / mo</strong><p class="muted">'+esc(m.sharedRecords?(m.sharedUnknown||0)+' recurring amounts unknown':'No shared expense records entered')+'. Current forecast, kept separate; never allocated or added to reconciled actuals automatically.</p><a href="/finance/expenses?project=Shared%20systems">Review shared expenses ↗</a></article><div class="pf-cards">'+cards+'</div><p class="muted">Actuals use owner-entered monthly reconciliation in USD. Profit change compares '+esc(month)+' with '+esc(previous)+' only where both records exist. Commitments reflect the current expense register, not historical invoices. A dash is unavailable or not entered; zero is a recorded value. Owner labor and taxes depend on the entered records.</p>';
