function sameOriginPost(req){const target=new URL(req.url).origin,origin=req.headers.get('Origin'),site=req.headers.get('Sec-Fetch-Site'),referer=req.headers.get('Referer');if(site&&site!=='same-origin')return false;if(origin&&origin!=='null')return origin===target;if(site==='same-origin')return true;if(!origin&&referer){try{return new URL(referer).origin===target}catch{return false}}return false}
