async function pzGoogleSession(req,env){
 const raw=pzDashCookie(req);if(!pzTokenOk(raw)||!env.ACCOUNT_AUTH_DB||!env.OWNER_EMAIL)return null;
 try{return await env.ACCOUNT_AUTH_DB.prepare("SELECT d.account_session_hash FROM owner_dashboard_sessions d JOIN sessions s ON s.token_hash=d.account_session_hash JOIN users u ON u.id=s.user_id WHERE d.token_hash=? AND d.expires_at>? AND d.revoked_at IS NULL AND s.expires_at>? AND s.revoked_at IS NULL AND u.disabled_at IS NULL AND lower(u.email)=?").bind(await pzTokenHash(raw),Math.floor(Date.now()/1000),Math.floor(Date.now()/1000),env.OWNER_EMAIL.trim().toLowerCase()).first()}catch{return null}
}
async function pzDashboardBridge(req,env){
 if(req.method!=='POST'||req.headers.get('origin')!==PZ_ACCOUNT||!req.headers.get('content-type')?.startsWith('application/x-www-form-urlencoded')||!env.ACCOUNT_AUTH_DB)return response('Forbidden',403);
 if(Number(req.headers.get('content-length')||0)>256)return response('Invalid request',400);
 try{
  const body=await req.text();if(body.length>256)return response('Invalid request',400);
  const params=new URLSearchParams(body),code=params.get('code');if(params.getAll('code').length!==1||!pzTokenOk(code))return response('Invalid request',400);
  const db=env.ACCOUNT_AUTH_DB,now=Math.floor(Date.now()/1000);
  const row=await db.prepare("UPDATE owner_dashboard_codes SET used_at=? WHERE token_hash=? AND expires_at>? AND used_at IS NULL AND EXISTS(SELECT 1 FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=owner_dashboard_codes.account_session_hash AND s.expires_at>? AND s.revoked_at IS NULL AND u.disabled_at IS NULL AND lower(u.email)=?) RETURNING account_session_hash").bind(now,await pzTokenHash(code),now,now,env.OWNER_EMAIL.trim().toLowerCase()).first();
  if(!row)return response('Sign-in expired. Return to the account page.',403);
  const token=pzToken();
  await db.prepare("DELETE FROM owner_dashboard_sessions WHERE expires_at<=? OR revoked_at IS NOT NULL").bind(now).run();
  await db.prepare('INSERT INTO owner_dashboard_sessions(token_hash,account_session_hash,expires_at) VALUES(?,?,?)').bind(await pzTokenHash(token),row.account_session_hash,now+43200).run();
  const r=pzDashRedirect(mcpOAuthCookie(req)?'/oauth/authorize/resume':'/',{'Set-Cookie':pzDashCookieValue(token,43200)});r.headers.append('Set-Cookie','pz_workspace_hint=1; Domain=projectzero.work; Path=/; Max-Age=43200; Secure; SameSite=Lax');return r;
 }catch{return response('Sign-in unavailable',503)}
}
