const LC_EXPERIENCE=['Undecided','Beginner','Some experience','Developer'];
function lcIcon(name){return '<svg class="lc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(LC_ICONS[name]||LC_ICONS.folder)+'</svg>'}
function lcWUrl(id,step){return lcLink(id)+'&step='+encodeURIComponent(step)}
function lcReturnStep(f,id){const step=f.get('return_step');return LC_WIZARD_STEPS.some(s=>s[0]===step)||step==='advanced'?lcWUrl(id,step):lcLink(id)}
function lcWForms(html,step){return html.replace(/<form\b[^>]*>/g,tag=>/method="post"/i.test(tag)?tag+'<input type="hidden" name="return_step" value="'+esc(step)+'">':tag)}
function lcWBlock(icon,title,body){return '<section class="lc-w-block"><h3>'+lcIcon(icon)+esc(title)+'</h3>'+body+'</section>'}
function lcProfileForm(p,profile,kind){const form='<form class="mailform lc-form" method="post" action="/lifecycle/profile"><input type="hidden" name="id" value="'+esc(p.id)+'"><input type="hidden" name="revision" value="'+esc(profile?.revision||0)+'"><input type="hidden" name="part" value="'+kind+'">';return form+(kind==='analysis'?'<label>Analysis / chosen approach<textarea name="analysis" maxlength="5000" rows="6" placeholder="Record market validation, proposed stack, cost estimates, risks and what you decided.">'+esc(profile?.analysis||'')+'</textarea></label>':'<label>What are you building?'+trSelect('product_type',LC_PRODUCT_TYPES,profile?.product_type||'Undecided')+'</label><label>How will it make money?'+trSelect('revenue_type',LC_REVENUE_TYPES,profile?.revenue_type||'Undecided')+'</label><label>Technical experience'+trSelect('experience',LC_EXPERIENCE,profile?.experience||'Undecided')+'</label>')+'<button type="submit">'+lcIcon('check')+' Save '+(kind==='analysis'?'analysis':'project type')+'</button></form>'}

function lcStackHint(p,profile,key){if(!profile||profile.product_type==='Undecided')return '';const type=profile.product_type;const zero=p.budget_cents===0;const suggestions={hosting:type==='Website / content'?'For a static site, compare Cloudflare, Netlify and Vercel. For a traditional server, compare Render and DigitalOcean.':type==='Web app / SaaS'?'For a small web app, compare Cloudflare Workers with Vercel or Render based on runtime and database requirements.':'Compare hosting by your runtime, region, operational needs and budget.',domains:'Use your existing registrar where possible. Verify renewal pricing and DNS before moving anything.',database:'Compare D1 for SQLite-compatible edge workloads, or managed PostgreSQL providers such as Supabase and Neon for PostgreSQL needs.',identity:'Reuse your existing authentication; compare managed providers and custom auth only when accounts are required.',payments:'Compare Stripe with merchant-of-record services if sales tax handling is important. Do not activate live payments until testing passes.',analytics:'Compare SiteAPT, Cloudflare Web Analytics and other privacy-conscious options. Choose only the tracking you need.',email:'For transactional email, compare Resend or Postmark; keep existing business email if it works.',distribution:'Select the stores or direct-download channels you actually need; verify signing and publication requirements.',monitoring:'Start with basic uptime and error alerts; expand only when justified.',commerce:'Compare hosted and self-managed storefronts based on fulfillment, fees and integration requirements.',ci:'Reuse the source provider’s build tools where appropriate.',marketing:'Validate audience, eligibility, consent and budget before choosing paid advertising.'};return (suggestions[key]||'Reuse an existing service if it meets the requirements.')+(zero?' Your budget is $0/month: verify current free limits and reject any chargeable setup unless the owner changes the budget.':' Check current prices and limits; these are candidates, not guaranteed costs.')}

function lcRecommended(profile){const type=profile?.product_type||'Undecided',revenue=profile?.revenue_type||'Undecided';const types={'Website / content':['hosting','domains','analytics','monitoring'],'Web app / SaaS':['hosting','domains','database','identity','email','analytics','monitoring','ci'],'Online store':['hosting','domains','commerce','email','analytics','monitoring'],'Mobile app':['distribution','monitoring','analytics','ci'],'Desktop app':['distribution','ci','support'],'API / backend':['hosting','database','identity','monitoring','ci'],'Self-hosted / other':['monitoring','ci'],'Undecided':[]};const keys=new Set(types[type]||[]);if(['Subscriptions','One-time sales'].includes(revenue))keys.add('payments');if(revenue==='Advertising')keys.add('marketing');if(revenue==='Services / leads')keys.add('email');return [...keys]}
function lcAnalysisStep(p,e,profile){const info=['Project: '+p.name,'Concept: '+(p.concept||'Not yet defined'),'Project type: '+(profile?.product_type||'Undecided'),'Revenue: '+(profile?.revenue_type||'Undecided'),'Customer: '+p.audience,'Business model: '+p.business_model,'Technical experience: '+(profile?.experience||'Undecided'),'Repository: '+(e?.repository||'Not linked'),'Monthly budget: '+(p.budget_cents==null?'Not specified; no new spend without approval':'USD '+(p.budget_cents/100).toFixed(2)),'Constraints: '+p.notes,'Existing platform choices: '+(lcPlatformSummary(p.platforms)||'None recorded')].join('\n');const prompt=info+'\n\nAnalyze feasibility as a product and software lead. Use the existing source only if authorized; for new ideas validate assumptions, demand and competitors. Recommend an MVP, realistic revenue and cost assumptions, a minimal platform stack with reasons, free/low-cost alternatives, dependencies, privacy/security/legal considerations and launch criteria. Distinguish confirmed facts from assumptions. Reuse existing infrastructure, avoid unnecessary services and flag budget conflicts. Explain in plain language suited to my technical experience. Do not create accounts, buy anything, change code, deploy, or schedule jobs. Return a concise review I can paste into Project Zero. The roadmap is generated separately after I review the stack.';return lcWBlock('search','Business & technology review','<p>Decide what to build before choosing hosting, payments or other services. Do this yourself or copy the project-specific prompt to your preferred assistant.</p>'+lcAssistantLinks('lc-analysis-review','analysis',prompt)+lcProfileForm(p,profile,'analysis'))}
function lcGateView(p,gs,key){const spec=LC_STAGES.find(s=>s[0]===key),g=gs.find(x=>x.stage===key);if(!spec||!g)return '';return '<details class="lc-brief lc-gate-review"><summary>'+lcIcon('shield')+' Review checkpoint <span class="lc-stage-status '+lcClass(g.status)+'">'+esc(g.status)+'</span></summary><div class="lc-stage-body"><p>'+esc(spec[2])+'</p><p class="lc-note">Navigation does not approve a checkpoint. Review earlier checkpoints in order, and enter actual evidence before approval.</p><form class="mailform lc-form" method="post" action="/lifecycle/gate"><input type="hidden" name="id" value="'+esc(p.id)+'"><input type="hidden" name="stage" value="'+esc(key)+'"><input type="hidden" name="revision" value="'+esc(g.revision)+'"><label>Review status'+trSelect('status',LC_STATES,g.status)+'</label><label>Evidence / decision<textarea name="evidence" maxlength="8000" placeholder="What was verified? What remains?">'+esc(g.evidence)+'</textarea></label><button type="submit">'+lcIcon('check')+' Save checkpoint</button></form></div></details>'}

function lcActivation(p,intake,gs,backlog,summary){if(p.tracker_project)return lcWBlock('list','Development workspace','<p>This project is active in the private development tracker.</p><div class="lc-actions"><a class="lc-button" href="/development?project='+encodeURIComponent(p.tracker_project)+'">'+lcIcon('arrow')+' Open development</a></div>'+lcTrackerStatus(summary));const ready=backlog!==null&&backlog.length>0&&['idea','viability','identity','architecture'].every(k=>gs.find(g=>g.stage===k)?.status==='Approved');return lcWBlock('list','Activate your development project','<p>Move your reviewed roadmap into the shared private development queue. The project retains its brief, platforms, repository link and approval history. This does not provision hosting, create a GitHub repository, schedule work, purchase services or publish the project.</p><div class="lc-w-checks">'+[['idea','Business brief'],['viability','Execution method'],['identity','Repository & setup'],['architecture','Roadmap review']].map(([k,l])=>'<div>'+lcIcon(gs.find(g=>g.stage===k)?.status==='Approved'?'check':'shield')+'<span>'+esc(l)+' · '+esc(gs.find(g=>g.stage===k)?.status||'Unknown')+'</span></div>').join('')+'<div>'+lcIcon('list')+'<span>'+esc(backlog===null?'Backlog unavailable':backlog.length+' reviewed tasks')+'</span></div></div>'+(ready?'<form method="post" action="/lifecycle/activate" class="mailform lc-form"><input type="hidden" name="id" value="'+esc(p.id)+'"><input type="hidden" name="revision" value="'+esc(p.revision)+'"><input type="hidden" name="expected_tasks" value="'+backlog.length+'"><label class="check"><input type="checkbox" name="confirm" value="yes" required> I approve adding this project and its '+backlog.length+' tasks to my private development queue.</label><button type="submit">'+lcIcon('check')+' Activate project</button></form>':'<p class="lc-note">Approve the four planning checkpoints and add at least one reviewed task before activation.</p>'))}
function lcTrackerStatus(summary){if(!summary||typeof summary.total!=='number')return '<p class="lc-note">Development status unavailable or not yet connected.</p>';return '<div class="lc-actual-stats">'+[['Tasks',summary.total],['Completed',summary.done||0],['P0 unfinished',summary.p0||0],['Blocked',summary.blocked||0]].map(([l,n])=>'<div><small>'+esc(l)+'</small><strong>'+esc(n)+'</strong></div>').join('')+'</div>'}
function lcHistory(rows){return '<details class="lc-brief"><summary>'+lcIcon('clock')+' Review history</summary><div class="lc-stage-body">'+(rows===null?'<p>History unavailable.</p>':rows.length?rows.map(r=>'<div class="lc-plan-row"><strong>'+esc(r.stage?r.stage+' · '+r.action:r.action)+'</strong><small>'+esc(r.changed_at)+' UTC · revision '+esc(r.revision)+'</small></div>').join(''):'<p>No saved review changes yet.</p>')+'</div></details>'}
async function lcActivate(req,env){if(!sameOriginPost(req)||!req.headers.get('content-type')?.startsWith('application/x-www-form-urlencoded'))return response('Forbidden',403);if(Number(req.headers.get('Content-Length')||0)>4096)return response('Too large',413);const raw=await req.text();if(raw.length>4096)return response('Too large',413);const f=new URLSearchParams(raw),id=(f.get('id')||'').trim(),rev=Number(f.get('revision')),expected=Number(f.get('expected_tasks'));if(!lcId(id)||!Number.isSafeInteger(rev)||rev<1||!Number.isSafeInteger(expected)||expected<1||expected>10000||f.get('confirm')!=='yes')return response('Invalid activation request',400);const db=env.TRACKER,back=msg=>response(lcPage('Project lifecycle','<p class="warn">'+esc(msg)+'</p><a href="'+lcWUrl(id,'roadmap')+'">Review roadmap</a>'),409,'text/html;charset=utf-8');const redirect=()=>new Response(null,{status:303,headers:{...headers,Location:lcWUrl(id,'execute')+'&notice=review-saved'}});try{const p=await db.prepare('SELECT p.tracker_project,a.brief_revision,a.expected_tasks FROM lifecycle_projects p LEFT JOIN lifecycle_activation a ON a.lifecycle_id=p.id WHERE p.id=?').bind(id).first();if(!p)return response('Not found',404);if(p.tracker_project)return p.brief_revision===rev&&p.expected_tasks===expected?redirect():back('Project is already linked. Reload before making changes.');await db.prepare('INSERT INTO lifecycle_activation(lifecycle_id,brief_revision,expected_tasks) VALUES(?,?,?)').bind(id,rev,expected).run();return redirect()}catch{return back('Activation was not saved. Review the four planning checkpoints, roadmap, project name and repository; reload before retrying.')}}


const LB_DECISIONS=['Not reviewed','Validate','Continue','Maintain','Expand','Pivot','Pause'];
function lbPlanned(rows){if(!Array.isArray(rows))return null;const selected=rows.filter(r=>!['Not decided','Not needed'].includes(r.status));return {count:selected.length,known:selected.filter(r=>r.monthly_cents!==null).length,cents:selected.reduce((n,r)=>n+(r.monthly_cents??0),0)}}
function lbActual(row){return row?.month?{revenue:row.revenue_cents-row.refund_cents,expenses:row.fees_cents+row.hosting_cents+row.other_cents,profit:row.revenue_cents-row.refund_cents-row.fees_cents-row.hosting_cents-row.other_cents}:null}
async function lbRead(env,p){const month=new Date().toISOString().slice(0,7),project=p.tracker_project,financeKey=lbFinanceKey(p);const [goals,history,actual,expenses,actions]=await Promise.all([safeFirst(env.TRACKER,'SELECT * FROM lifecycle_business_goals WHERE lifecycle_id=?',p.id),safeRows(env.TRACKER,'SELECT revision,decision,evidence,revenue_cents,profit_cents,review_due,recorded_at FROM lifecycle_business_decisions WHERE lifecycle_id=? ORDER BY revision DESC LIMIT 30',p.id),financeKey?safeFirst(env.PORTFOLIO,'SELECT * FROM monthly_finance WHERE project=? AND month=?',financeKey,month):null,project?pxSummary(env,project):null,project?safeFirst(env.TRACKER,"SELECT COUNT(*) n FROM tracker_owner_actions a JOIN tracker_active_tasks t ON t.task_id=a.task_id WHERE t.project=? AND a.action_status='Needed' AND t.status NOT IN ('Done','Deferred')",project):null]);const automatic=financeKey&&FINANCE_PROJECTS.some(([k])=>k===financeKey)?await afRead(env,month,expenses):null;return {goals,history,actual,expenses,actions,month,financeKey,automatic}}
function lbMetric(label,value,note=''){return '<div><small>'+esc(label)+'</small><strong>'+esc(value)+'</strong>'+(note?'<small>'+esc(note)+'</small>':'')+'</div>'}
function lbGoalForm(p,b){const g=b.goals;if(g===null)return '<p class="warn">Business goals unavailable. Reload before editing.</p>';const amount=(k,l)=>'<label>'+esc(l)+' (USD / month)<input type="number" name="'+k+'" min="0" max="99999999.99" step="0.01" inputmode="decimal" placeholder="Not set" value="'+esc(g[k+'_cents']==null?'':(g[k+'_cents']/100).toFixed(2))+'"></label>';return '<form method="post" action="/lifecycle/business-review" class="mailform lc-form"><input type="hidden" name="id" value="'+esc(p.id)+'"><input type="hidden" name="revision" value="'+esc(g.revision||0)+'"><div class="lb-fields">'+amount('revenue','Net revenue target')+amount('profit','Operating profit target')+'<label>Next business review<input type="date" name="review_due" value="'+esc(g.review_due||'')+'"></label><label>Business decision'+trSelect('decision',LB_DECISIONS,g.decision||'Not reviewed')+'</label></div><label>Decision evidence / milestone<textarea name="evidence" rows="4" maxlength="4000" placeholder="Demand evidence, actual results, next milestone, and why this decision makes sense.">'+esc(g.evidence||'')+'</textarea></label><p class="lc-note">Goals are optional. A decision other than Not reviewed requires evidence. Recording a decision does not approve a launch, pause a schedule, spend money or change any development tasks.</p><button type="submit">Save goals &amp; decision</button></form>'}
function lbDecisionHistory(b){return '<details class="lc-brief"><summary>Business decision history</summary><div class="lc-stage-body">'+(b.history===null?'<p class="warn">History unavailable.</p>':b.history.length?b.history.map(r=>'<div class="lc-plan-row"><strong>'+esc(r.decision)+'</strong><small>'+esc(r.recorded_at)+' UTC · revision '+fmt(r.revision)+'</small><p>'+esc(r.evidence||'No decision evidence recorded')+'</p><small>Revenue goal '+esc(pxMoney(r.revenue_cents))+' · Profit goal '+esc(pxMoney(r.profit_cents))+' · Next review '+esc(r.review_due||'Not set')+'</small></div>').join(''):'<p>No business decisions recorded yet.</p>')+'</div></details>'}
function lbCostView(p,b){const plan=lbPlanned(p.platforms),t=b.expenses?.totals,known=t?.known_recurring?t.recurring_cents:null;const link=p.tracker_project?'/finance/expenses?project='+encodeURIComponent(p.tracker_project):'';return lcWBlock('wallet','Project cost plan &amp; commitments','<div class="lb-metrics">'+lbMetric('Monthly spending ceiling',pxMoney(p.budget_cents),p.budget_cents===null?'Not set':'Owner-defined')+lbMetric('Known platform estimate',plan&&plan.known?pxMoney(plan.cents):'—',plan?plan.count+' selected · '+(plan.count-plan.known)+' unknown':'Unavailable')+lbMetric('Known recurring commitments',pxMoney(known),!p.tracker_project?'Activate the project first':t?fmt(t.active||0)+' active · '+fmt(t.unknown_recurring||0)+' recurring amounts unknown':'Unavailable')+'</div>'+(plan&&p.budget_cents!==null&&plan.cents>p.budget_cents?'<p class="warn">Known platform estimates exceed your spending ceiling.</p>':'')+(known!==null&&p.budget_cents!==null&&known>p.budget_cents?'<p class="warn">Known recurring commitments exceed your spending ceiling.</p>':'')+'<p class="lc-note">Estimates and confirmed commitments may describe the same services. They are shown side by side, never added together. Shared costs, variable costs and one-time bills are separate. No payment or subscription is created here.</p>'+(link?'<div class="lc-actions"><a href="'+esc(link)+'">Manage project expenses ↗</a><a href="/operations/inventory">Infrastructure inventory ↗</a></div>':'<p class="lc-note">Activate the draft to record confirmed project commitments in the expense register.</p>'))}
function lbHandoff(p,b){if(!p.tracker_project||!Array.isArray(p.platforms))return '';const rows=p.platforms.filter(r=>r.provider&&['Existing account','Configured (owner reported)'].includes(r.status));if(!rows.length)return '';return lcWBlock('cloud','Record confirmed platform commitments','<p>Use these links only for services you actually use. Review your existing expense entries first; the form leaves the charge and renewal date blank until you verify them.</p>'+rows.map(r=>'<div class="lb-line"><span><strong>'+esc(r.provider)+'</strong><small>'+esc(r.category)+' · '+esc(r.status)+'</small></span><a class="button" href="/finance/expenses?project='+encodeURIComponent(p.tracker_project)+'&from_lifecycle='+encodeURIComponent(p.id)+'&category='+encodeURIComponent(r.category)+'#px-form">Record expense</a></div>').join(''))}
function lbOperate(p,b,summary){const g=b.goals,actual=lbActual(b.actual),t=b.expenses?.totals,goalNote=(target,actualValue)=>target==null?'Target not set':actualValue==null?'Target '+pxMoney(target)+' · actual not reconciled':'Target '+pxMoney(target)+' · '+pxMoney(actualValue-target)+' vs target';const month=b.month;return lcWBlock('chart','Business performance · '+month,'<div class="lb-metrics">'+lbMetric('Net revenue',pxMoney(actual?.revenue),goalNote(g?.revenue_cents,actual?.revenue))+lbMetric('Operating costs',pxMoney(actual?.expenses),'Reconciled actuals only')+lbMetric('Operating profit',pxMoney(actual?.profit),goalNote(g?.profit_cents,actual?.profit))+'</div>'+(!actual?'<p class="lc-note">'+(b.financeKey?(b.actual===null?'Reconciliation unavailable.':'No actual report recorded for this month. Missing data is not zero.'):'Actual reporting is not connected for this project yet.')+'</p>':'<p class="lc-note">Owner-entered reconciliation · '+esc(b.actual.updated_at)+' · owner labor and tax treatment depend on the entered records.</p>')+(b.financeKey?'<div class="lc-actions"><a href="/finance/reconcile?project='+encodeURIComponent(b.financeKey)+'&month='+encodeURIComponent(month)+'">Open monthly reconciliation ↗</a></div>':'')+lcTrackerStatus(summary)+(p.tracker_project?'<div class="lc-actions"><a href="/development?project='+encodeURIComponent(p.tracker_project)+'">Open project development ↗</a><a href="/development/notes">Owner actions: '+fmt(b.actions?.n)+' ↗</a></div>':'')+'<div class="lb-metrics">'+lbMetric('Due within 30 days',t&&t.active?fmt(t.upcoming||0):'—')+lbMetric('Overdue commitments',t&&t.active?fmt(t.overdue||0):'—')+lbMetric('Next business review',g?.review_due||'Not set',g?.review_due&&g.review_due<new Date().toISOString().slice(0,10)?'Review overdue':'Owner-selected date')+'</div>')+afLifecycle(b.automatic,b.financeKey)+lbCostView(p,b)+'<div id="lb-goals">'+lcWBlock('list','Goals &amp; business decision',lbGoalForm(p,b)+lbDecisionHistory(b))+'</div>' }
function lbAnalyze(p,b){const g=b.goals;return lcWBlock('search','Commercial viability decision','<div class="lb-metrics">'+lbMetric('Decision',g?.decision||'Not reviewed')+lbMetric('Revenue goal',pxMoney(g?.revenue_cents))+lbMetric('Profit goal',pxMoney(g?.profit_cents))+'</div><p class="lc-note">Review evidence of willingness to pay, competition, acquisition, realistic costs and the smallest viable release. Do not treat assistant estimates as confirmed demand.</p><a class="button" href="'+lcWUrl(p.id,'operate')+'#lb-goals">Set goals and record a decision ↗</a>')}
async function lbSave(req,env){if(!sameOriginPost(req)||!req.headers.get('content-type')?.startsWith('application/x-www-form-urlencoded'))return response('Forbidden',403);if(Number(req.headers.get('Content-Length')||0)>32000)return response('Too large',413);const raw=await req.text();if(raw.length>32000)return response('Too large',413);const f=new URLSearchParams(raw),str=k=>(f.get(k)||'').trim(),id=str('id'),rev=Number(str('revision')),revenue=str('revenue'),profit=str('profit'),due=str('review_due'),decision=str('decision'),evidence=str('evidence'),revenueC=revenue?centsFrom(revenue):null,profitC=profit?centsFrom(profit):null;const back=(msg,status=400)=>response(lcPage('Project lifecycle','<p class="warn">'+esc(msg)+'</p><a href="'+lcWUrl(id,'operate')+'">Return to business review</a>'),status,'text/html;charset=utf-8');if(!lcId(id)||!Number.isSafeInteger(rev)||rev<0||(revenue&&revenueC===null)||(profit&&profitC===null)||!LB_DECISIONS.includes(decision)||evidence.length>4000||(decision!=='Not reviewed'&&!evidence)||(due&&(!/^\d{4}-\d{2}-\d{2}$/.test(due)||!Number.isFinite(Date.parse(due+'T00:00:00Z'))||new Date(due+'T00:00:00Z').toISOString().slice(0,10)!==due)))return back('Enter valid goals, date and decision evidence.');try{const db=env.TRACKER;const p=await db.prepare("SELECT id FROM lifecycle_projects WHERE id=? AND (tracker_project IS NULL OR tracker_project IN (SELECT project FROM tracker_active_projects))").bind(id).first();if(!p)return back('Project not found',404);let r;if(rev===0)r=await db.prepare('INSERT INTO lifecycle_business_goals(lifecycle_id,revenue_cents,profit_cents,review_due,decision,evidence) VALUES(?,?,?,?,?,?) ON CONFLICT(lifecycle_id) DO NOTHING RETURNING lifecycle_id').bind(id,revenueC,profitC,due,decision,evidence).first();else r=await db.prepare('UPDATE lifecycle_business_goals SET revenue_cents=?,profit_cents=?,review_due=?,decision=?,evidence=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE lifecycle_id=? AND revision=? RETURNING lifecycle_id').bind(revenueC,profitC,due,decision,evidence,id,rev).first();if(!r)return back('Business review changed. Reload before saving.',409);return new Response(null,{status:303,headers:{...headers,Location:str('return_to')==='investments'?'/investments?view='+(['all','active','draft'].includes(str('return_view'))?str('return_view'):'all')+'&month='+(isMonth(str('return_month'))?str('return_month'):new Date().toISOString().slice(0,7))+'&edit='+encodeURIComponent(id)+'&notice=review-saved#iv-editor':lcWUrl(id,'operate')+'&notice=review-saved#lb-goals'}})}catch{return back('Save could not be confirmed. Reload before retrying.',503)}}

const LB_CSS=".lb-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:10px 0}.lb-metrics>div{background:#f7f8fa;border:1px solid #e2e4e8;border-radius:8px;padding:10px;min-width:0}.lb-metrics small{display:block;font-size:11px;color:#555b64}.lb-metrics strong{display:block;font-size:22px;line-height:1.4;letter-spacing:-.035em;overflow-wrap:anywhere}.lb-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.lb-line{display:flex;justify-content:space-between;align-items:center;gap:10px;border-top:1px solid #e2e4e8;padding:10px 0}.lb-line>span{min-width:0;overflow-wrap:anywhere}.lb-line small{display:block;color:#656b74}.lb-line a{flex:none;font-size:12px}.lb-link-row{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}@media(max-width:760px){.lb-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.lb-metrics>div:last-child{grid-column:1/-1}.lb-metrics strong{font-size:19px}.lb-fields{grid-template-columns:minmax(0,1fr)}.lb-line{flex-wrap:wrap}}";
function lcWizardPage(p,e,intake,catalog,observations,backlog,trackerTasks,gs,profile,u,summary,history,business){const wanted=u.searchParams.get('step');const nextGate=LC_STAGES.find(([k])=>gs.find(g=>g.stage===k)?.status!=='Approved')?.[0];const fallback=LC_WIZARD_STEPS.find(x=>x[4]===nextGate)?.[0]||'operate';const step=wanted==='advanced'?'advanced':LC_WIZARD_STEPS.some(x=>x[0]===wanted)?wanted:fallback;const advanced=step==='advanced',index=LC_WIZARD_STEPS.findIndex(x=>x[0]===step),current=LC_WIZARD_STEPS[index];const approved=gs.filter(x=>x.status==='Approved').length;const repo=e?.repository||'';const rows=p.platforms;const setup=()=>lcGitPanel(p,e,catalog)+lcPlatforms(p,e,rows,profile,advanced||u.searchParams.get('all')==='1')+lbCostView(p,business)+lbHandoff(p,business);const brief=()=>lcWBlock('bulb','Project brief & budget',lcBriefForm(p))+lcWBlock('layers','Tailor your setup',lcProfileForm(p,profile,'type'))+lcWBlock('chart','Financial goals','<div class="lb-metrics">'+lbMetric('Revenue target',pxMoney(business.goals?.revenue_cents))+lbMetric('Profit target',pxMoney(business.goals?.profit_cents))+lbMetric('Decision',business.goals?.decision||'Not reviewed')+'</div><a href="'+lcWUrl(p.id,'operate')+'#lb-goals">Set goals &amp; business review ↗</a>');const body={brief,work:()=>lcExecution(p,e,catalog,intake),analyze:()=>lcAnalysisStep(p,e,profile)+lbAnalyze(p,business),setup,roadmap:()=>lcPlanning(p,e,backlog,trackerTasks)+lcActivation(p,intake,gs,backlog,summary),execute:()=>lcActivation(p,intake,gs,backlog,summary)+lcSchedulePanel(p,e,observations),launch:()=>lcWBlock('shield','Ready to launch?','<div class="lc-w-checks">'+['Core P0 tasks and end-to-end tests','Security, privacy and permissions','Billing, delivery and cancellation (if applicable)','Mobile accessibility and support','Budget, monitoring, backup and rollback','Explicit owner launch decision'].map(v=>'<div>'+lcIcon('shield')+'<span>'+esc(v)+'</span></div>').join('')+'</div><p>These are review criteria, not claims of completion. Launch approval requires an active project, a nonempty tracker and all P0 tasks Done with evidence.</p>'+lcTrackerStatus(summary)+''+(p.tracker_project?'<div class="lc-actions"><a href="/development?project='+encodeURIComponent(p.tracker_project)+'">'+lcIcon('list')+' Review development tasks</a></div>':'')),operate:()=>lbOperate(p,business,summary)+lcWBlock('chart','Business review','<p>Monitor revenue, costs, customer needs, outages and development progress. Revisit analysis when the business or technology changes.</p>'+lcTrackerStatus(summary)+'<div class="lc-w-quick">'+[['chart','Finance','/finance'],['activity','Operations','/operations'],['mail','Inbox','/inbox'],['list','Development',p.tracker_project?'/development?project='+encodeURIComponent(p.tracker_project):'/development']].map(([i,l,url])=>'<a href="'+esc(url)+'">'+lcIcon(i)+esc(l)+'</a>').join('')+'</div>')};const content=advanced?LC_WIZARD_STEPS.map(x=>'<section class="lc-w-advanced"><h2>'+lcIcon(x[2])+esc(x[1])+'</h2>'+body[x[0]]()+(x[4]?lcGateView(p,gs,x[4]):'')+'</section>').join(''):body[step]()+ (current[4]?lcGateView(p,gs,current[4]):'');const rail='<nav class="lc-w-rail" data-no-swipe aria-label="Project setup steps">'+LC_WIZARD_STEPS.map(([k,label,icon,_,gate],i)=>{const done=gate&&gs.find(g=>g.stage===gate)?.status==='Approved';return '<a href="'+lcWUrl(p.id,k)+'"'+(k===step?' aria-current="step"':'')+' class="'+(done?'lc-w-reviewed':'')+'">'+lcIcon(done?'check':icon)+'<span>'+esc(label)+'</span><small>'+ (done?'Reviewed':(i+1))+'</small></a>'}).join('')+'</nav>';const nav=advanced?'<div class="lc-w-next"><a class="lc-button" href="'+lcWUrl(p.id,fallback)+'">'+lcIcon('arrow')+' Resume guided setup</a></div>':'<div class="lc-w-next">'+(index>0?'<a class="lc-w-back" href="'+lcWUrl(p.id,LC_WIZARD_STEPS[index-1][0])+'">'+lcIcon('back')+' Back</a>':'<a class="lc-w-back" href="/lifecycle">'+lcIcon('back')+' Projects</a>')+(index<LC_WIZARD_STEPS.length-1?'<a class="lc-button" href="'+lcWUrl(p.id,LC_WIZARD_STEPS[index+1][0])+'">Next: '+esc(LC_WIZARD_STEPS[index+1][1])+lcIcon('arrow')+'</a>':'<a class="lc-button" href="/lifecycle">All projects'+lcIcon('arrow')+'</a>')+'</div><p class="lc-note">Save any changes before moving to another step. You can revisit any step; moving on does not approve a checkpoint.</p>';
return response(lcPage('Project lifecycle','<div class="lc-w-top"><a href="/lifecycle">'+lcIcon('back')+' Projects</a><a href="'+lcWUrl(p.id,advanced?fallback:'advanced')+'">'+lcIcon('settings')+(advanced?'Guided setup':'Advanced view')+'</a></div><div class="lc-w-project"><div class="lc-card-top">'+lcLogo(p)+'<div><h2>'+esc(p.name)+'</h2><small>'+esc(p.tracker_project?'Active project · linked to tracker':intake?.origin==='existing'?'Imported project · tracker activation pending':'New project draft')+'</small></div></div><div class="lc-w-progress">'+lcBar(gs)+'<small>'+approved+' of '+LC_STAGES.length+' checkpoints approved</small></div></div>'+rail+'<article class="lc-w-stage"><div class="lc-w-heading">'+lcIcon(advanced?'settings':current[2])+'<div><small>'+ (advanced?'ALL SETTINGS':'STEP '+(index+1)+' OF '+LC_WIZARD_STEPS.length)+'</small><h2>'+esc(advanced?'Advanced setup':current[1])+'</h2><p>'+esc(advanced?'Review and edit every section.':current[3])+'</p></div></div>'+lcWForms(content,step)+nav+lcHistory(history)+'</article>'),200,'text/html;charset=utf-8')}


const LC_HELP_SETUPS=[
['globe','Website / content','Start with a repository, a static host, a domain and basic analytics. Add a CMS, email or monetization only if needed.','Often possible within free hosting allowances; domain renewal and commercial-plan eligibility still matter.',[['GitHub','github'],['Cloudflare','cloudflare'],['Netlify','netlify'],['SiteAPT','siteapt']]],
['layers','Web app / SaaS','Choose a host, a database, customer authentication and monitoring. Add checkout and transactional email when the product needs them.','Estimate usage, database operations, identity, email and payment fees together; test isolation before launch.',[['Cloudflare','cloudflare'],['D1','cloudflare-d1'],['Supabase','supabase'],['Stripe','stripe'],['Resend','resend']]],
['shopping','Online store','Choose a storefront, payment setup and product delivery or fulfillment. Test the full checkout, shipping, tax, refund and return flow.','Budget for the storefront, payment fees, apps, product cost, shipping and returns.',[['Shopify','shopify'],['WooCommerce','woocommerce'],['Printify','printify'],['Stripe','stripe']]],
['package','Desktop app','Keep source and builds in version control. Plan signed releases, licensing, downloads, updates and a support channel.','Signing certificates, store memberships, download traffic and payment processing may cost money.',[['GitHub Releases','github-releases'],['Apple Developer','apple-developer'],['Microsoft Partner Center','microsoft-partner-center'],['Lemon Squeezy','lemon-squeezy']]],
['box','Mobile app','Choose Android, iOS or both. Set up store accounts, testing, signing, privacy disclosures and a backend only if required.','Check current registration fees, store policies, commissions and backend usage.',[['Google Play Console','google-play-console'],['Apple Developer','apple-developer'],['Firebase','firebase'],['Sentry','sentry']]],
['cloud','API / self-hosted service','Match the runtime to your workload. Use scoped API access, monitoring, backups and a reliable release process.','Compare request-based hosting with a VM or existing server; include storage, transfer, maintenance and recovery.',[['Cloudflare','cloudflare'],['DigitalOcean','digitalocean'],['Render','render'],['Backblaze B2','backblaze-b2']]]
];
function lcHelpContent(){const steps=[['bulb','Business','Define the idea, audience, revenue model and monthly spending ceiling.'],['users','Work method','Choose manual work, ChatGPT, Claude or a combination. No paid AI account is required.'],['search','Analyze','Validate the idea, review existing source when authorized, and decide on the smallest viable product.'],['layers','Set up','Record or link your repository and choose only the platforms you need. Reuse existing accounts.'],['list','Roadmap','Copy the analysis prompt or add tasks manually. Review P0 launch blockers, P1 improvements, P2 optimization and Exposure before importing.'],['clock','Execute','Assign tasks, agree on responsibilities and optionally create schedules in the assistant. Avoid duplicate work.'],['shield','Launch','Verify security, end-to-end tests, billing if applicable, mobile UX, cost controls and delivery. Record evidence and approval.'],['chart','Operate','Track revenue, expenses, customer support, reliability and the next development priorities.']];return '<p class="lc-help-intro">Start with an idea or an existing project. Follow the steps in order or jump to the ones you need. Save changes at each step; navigation never approves a checkpoint.</p><h3 class="lc-help-section-title">'+lcIcon('list')+' How the lifecycle works</h3><ol class="lc-help-steps">'+steps.map(([icon,title,desc],i)=>'<li><span class="lc-help-icon">'+lcIcon(icon)+'</span><div><strong>'+ (i+1)+'. '+esc(title)+'</strong><p>'+esc(desc)+'</p></div></li>').join('')+'</ol><h3 class="lc-help-section-title">'+lcIcon('bot')+' Choose your way of working</h3><div class="lc-help-methods"><div><strong>Manual</strong><p>Use the roadmap yourself. Add tasks, record evidence and approve checkpoints.</p></div><div><strong>AI-assisted</strong><p>Copy a project-specific prompt into ChatGPT or Claude. Review its response before importing tasks. Scheduling depends on your actual plan and available tools.</p></div><div><strong>Mixed</strong><p>Let assistants handle approved work while you own decisions, credentials, budgets and final verification.</p></div></div><p class="lc-help-note">A copied prompt is not a connected account or an active schedule. Confirm connections, permissions and schedule creation inside the appropriate service. Never paste passwords or API keys into project notes.</p><h3 class="lc-help-section-title">'+lcIcon('layers')+' Typical platform setups</h3><p class="lc-help-intro">Use these examples as starting points, not requirements. Open any provider guide to compare pricing and alternatives. Check current limits, renewals, commercial-use rules and total cost before paying.</p><div class="lc-help-stacks">'+LC_HELP_SETUPS.map(([icon,title,desc,cost,links])=>'<section class="lc-help-stack"><div class="lc-help-stack-title"><span class="lc-help-icon">'+lcIcon(icon)+'</span><strong>'+esc(title)+'</strong></div><p>'+esc(desc)+'</p><p class="lc-help-cost">'+lcIcon('credit-card')+esc(cost)+'</p><div class="lc-help-providers">'+links.map(([name,slug])=>'<a href="https://guides.projectzero.work/platforms/'+slug+'" target="_blank" rel="noopener noreferrer">'+esc(name)+' ↗</a>').join('')+'</div></section>').join('')+'</div><p class="lc-help-note">These are examples, not preconfigured stacks or cost guarantees. Selecting a provider does not buy or configure it. If your budget is zero, verify that every required service is free for your intended use.</p><a class="lc-help-directory" href="https://guides.projectzero.work/platforms" target="_blank" rel="noopener noreferrer">'+lcIcon('layers')+' Explore all provider pricing and comparisons ↗</a><h3 class="lc-help-section-title">'+lcIcon('shield')+' Before you launch</h3><p>Complete the applicable P0 tasks and verify real customer flows. Record review evidence and get explicit approval for production changes, spending and launch. P1 improvements can follow the initial release.</p>'}
function lcHelpTop(){return '<div class="lc-help-top" data-no-swipe><a href="/lifecycle?help=1" data-lc-help-open aria-haspopup="dialog" aria-controls="lc-help-modal"><span class="lc-help-icon">'+lcIcon('bulb')+'</span><span><strong>Getting started</strong><small>Instructions &amp; typical setups</small></span><span class="lc-help-open-arrow" aria-hidden="true">'+lcIcon('arrow')+'</span></a><a href="https://guides.projectzero.work/platforms" target="_blank" rel="noopener noreferrer"><span class="lc-help-icon">'+lcIcon('layers')+'</span><span><strong>Platform guides</strong><small>Pricing, benefits &amp; alternatives</small></span><span class="lc-help-open-arrow" aria-hidden="true">↗</span></a></div><dialog id="lc-help-modal" class="lc-help-modal" aria-labelledby="lc-help-title" data-no-swipe><div class="lc-help-head"><div><small>PROJECT ZERO</small><h2 id="lc-help-title">Getting started</h2></div><button type="button" class="lc-help-close" data-lc-help-close aria-label="Close instructions" autofocus>×</button></div><div class="lc-help-body">'+lcHelpContent()+'</div><div class="lc-help-footer"><button type="button" data-lc-help-close class="lc-button">'+lcIcon('check')+' Done</button></div></dialog>'}
function lcHelpPage(){return response(lcPage('Project lifecycle help','<div class="lc-w-top"><a href="/lifecycle">'+lcIcon('back')+' Return to projects</a></div><article class="lc-w-stage"><h2>Getting started</h2>'+lcHelpContent()+'</article>'),200,'text/html;charset=utf-8')}

function lcPage(title,body){return page(title,(title==='Project lifecycle'?lcHelpTop():'')+body).replace('</head>','<style>'+LC_CSS+LB_CSS+AF_CSS+AF_EXTRA_CSS+'</style></head>')}
function lcLogo(p){const k=LC_KEY_MAP[p.tracker_project];return k?brandMark({key:k,name:p.name}):'<span class="project-logo" aria-hidden="true">'+esc(p.name.slice(0,2).toUpperCase())+'</span>'}
function lcBar(gates){return '<div class="lc-track" aria-label="'+gates.filter(g=>g.status==='Approved').length+' of '+LC_STAGES.length+' gates approved">'+LC_STAGES.map(([id])=>'<i class="'+lcClass(gates.find(g=>g.stage===id)?.status)+'"></i>').join('')+'</div>'}



const LC_SCHEDULE_PLANS={manual:{label:'No assistant / manual',cadences:['Manual'],note:'Work through your backlog yourself. No AI account required.'},chatgpt_free:{label:'ChatGPT Free',cadences:['Manual','Daily','Weekly'],note:'Up to 3 active tasks; recurring runs no more than daily. Choose a flexible window, not an exact time.'},chatgpt_go:{label:'ChatGPT Go',cadences:['Manual','Daily','Weekly'],note:'Up to 3 active tasks. Confirm available timing options in your account; this wizard uses flexible daily or weekly schedules.'},chatgpt_paid:{label:'ChatGPT paid (eligible plan)',cadences:['Manual','Hourly','Daily','Weekly'],note:'Hourly and exact-time schedules require eligibility. Plus: 5 active tasks; Business/Edu: 10; Pro/Enterprise: 15.'},claude_free:{label:'Claude Free',cadences:['Manual'],note:'Scheduled tasks require a paid Claude plan. Copy a manual work prompt instead.'},claude_paid:{label:'Claude paid / Cowork',cadences:['Manual','Hourly','Daily','Weekly','Weekdays'],note:'Use Scheduled in Claude or /schedule in Cowork. Confirm plan access, permissions and whether your computer must stay on.'}};
function lcSchedulePanel(p,e,observations){const covered=(observations||[]).filter(x=>x.scope==='Shared portfolio development queue'&&p.tracker_project||x.scope==='SiteAPT only'&&p.tracker_project==='SiteAPT');const cards=covered.length?covered.map(x=>'<div class="lc-schedule-record"><strong>'+esc(x.title)+'</strong><span>'+esc(x.enabled?'Active at last check':'Paused at last check')+' · '+esc(x.cadence)+'</span><small>Verified '+esc(x.observed_at.replace('T',' ').slice(0,16))+' UTC · '+esc(x.scope)+'</small></div>').join(''):'<p>No ChatGPT schedule linked to this project in the last verified snapshot.</p>';
const note=p.tracker_project?'Prefer the existing shared schedule where it covers this project. Do not create duplicate tasks.':'This is a concept draft, not yet in the shared execution queue. Limit scheduled work to planning and reviewing readiness.';
const work=lcPrompt(p,e,'execute');const guard=' Confirm access and the actual available account limits before scheduling; if unsupported, explain and offer manual operation. Do not purchase services or change other schedules. Review the proposed task and ask for confirmation before creating it. Verify the task appears in the provider’s Scheduled list. ';
const prompt='Run the following project work manually. Do not create a recurring task.\n\n'+work;return '<details class="lc-brief" open><summary>'+lcIcon('clock')+' Schedule assistant work (optional)</summary><div class="lc-stage-body">'+cards+'<p>'+esc(note)+'</p><p>Choose the assistant plan you actually have. A paid AI account is not required. Your assistant must have the necessary tools and permissions; scheduling alone does not grant them.</p><div class="mailform lc-form" data-no-swipe><label>Assistant / subscription<select id="lc-schedule-plan">'+Object.entries(LC_SCHEDULE_PLANS).map(([k,v])=>'<option value="'+k+'">'+esc(v.label)+'</option>').join('')+'</select></label><p class="lc-note" id="lc-plan-guidance">'+esc(LC_SCHEDULE_PLANS.manual.note)+'</p><label>Frequency<select id="lc-schedule-frequency"><option value="Manual">Manual</option></select></label><label id="lc-window-label" hidden>Preferred time window<select id="lc-schedule-window"><option>Morning</option><option>Afternoon</option><option>Evening</option></select></label><textarea id="lc-schedule-request" class="lc-prompt" readonly rows="9" data-work="'+esc(work)+'" data-guard="'+esc(guard)+'" aria-label="Assistant work request">'+esc(prompt)+'</textarea><div class="lc-actions"><button class="lc-button" id="lc-copy-schedule" type="button">Copy work request</button><a href="https://chatgpt.com/" id="lc-open-assistant" target="_blank" rel="noopener noreferrer" hidden>Open assistant ↗</a><a href="https://chatgpt.com/schedules" id="lc-manage-schedules" target="_blank" rel="noopener noreferrer" hidden>Manage ChatGPT schedules ↗</a></div><p id="lc-schedule-feedback" role="status">Manual mode is always available.</p></div><p class="lc-note">Your selection generates a request only. It does not create or activate schedules and does not require a paid API key. Limits verified November 25, 2026: <a href="https://help.openai.com/en/articles/10291617-scheduled-tasks-in-chatgpt" target="_blank" rel="noopener noreferrer">ChatGPT</a> · <a href="https://support.claude.com/en/articles/13854387-schedule-recurring-tasks-in-claude-cowork" target="_blank" rel="noopener noreferrer">Claude</a>.</p></div></details>'}

const LC_PLATFORM_CATALOG=[["hosting","Hosting & deployment","cloud","Choose a host based on runtime, traffic, availability, region, deployment workflow and total cost. Verify a staging deployment, rollback and production health.",[["Cloudflare","https://dash.cloudflare.com/"],["Vercel","https://vercel.com/"],["Netlify","https://www.netlify.com/"],["DigitalOcean","https://www.digitalocean.com/"],["AWS","https://aws.amazon.com/"],["Render","https://render.com/"],["Railway","https://railway.com/"],["Hostinger","https://www.hostinger.com/"],["Self-hosted",""]]],["domains","Domains, DNS & TLS","globe","Check domain availability, ownership, renewal cost, DNS, HTTPS and redirects. Never change live DNS without an approved migration and rollback.",[["Cloudflare Registrar","https://www.cloudflare.com/products/registrar/"],["Namecheap","https://www.namecheap.com/"],["Porkbun","https://porkbun.com/"],["GoDaddy","https://www.godaddy.com/"],["Existing registrar",""]]],["database","Database","database","Select the right database for access patterns, isolation, migrations, retention, backups, recovery and budget.",[["Cloudflare D1","https://developers.cloudflare.com/d1/"],["Supabase","https://supabase.com/"],["Neon","https://neon.com/"],["Firebase","https://firebase.google.com/"],["Managed PostgreSQL",""],["Local SQLite",""]]],["storage","File storage, CDN & backups","hard-drive","Keep private assets private; configure scoped access, lifecycle retention, backup restores and storage/transfer limits.",[["Cloudflare R2","https://developers.cloudflare.com/r2/"],["Amazon S3","https://aws.amazon.com/s3/"],["Backblaze B2","https://www.backblaze.com/cloud-storage"],["Supabase Storage","https://supabase.com/storage"],["Local storage",""]]],["identity","Authentication & account access","lock","Configure sign-in, session security, least privilege, account recovery and tenant boundaries. Verify logout and authorization.",[["Cloudflare Access","https://www.cloudflare.com/zero-trust/products/access/"],["Clerk","https://clerk.com/"],["Auth0","https://auth0.com/"],["Supabase Auth","https://supabase.com/auth"],["Firebase Authentication","https://firebase.google.com/products/auth"],["Custom / existing authentication",""]]],["payments","Payments, subscriptions & taxes","credit-card","Select payment processor or merchant of record. Verify eligibility, pricing, taxes, refunds, webhooks, entitlement changes and test-mode delivery before charging.",[["Stripe","https://stripe.com/"],["Paddle","https://www.paddle.com/"],["Lemon Squeezy","https://www.lemonsqueezy.com/"],["PayPal","https://www.paypal.com/"]]],["email","Transactional & business email","mail","Set up sender/domain verification, SPF, DKIM, DMARC, inbound support mail, bounce handling and safe test delivery.",[["Resend","https://resend.com/"],["Postmark","https://postmarkapp.com/"],["SendGrid","https://sendgrid.com/"],["Amazon SES","https://aws.amazon.com/ses/"],["Google Workspace","https://workspace.google.com/"],["Cloudflare Email Routing","https://developers.cloudflare.com/email-routing/"],["Existing email service",""]]],["analytics","Analytics, SEO & performance","chart","Configure privacy-conscious analytics, search indexing, consent where required, conversion tracking and performance checks.",[["SiteAPT","https://siteapt.app/"],["Google Analytics","https://marketingplatform.google.com/about/analytics/"],["Plausible","https://plausible.io/"],["Cloudflare Web Analytics","https://www.cloudflare.com/web-analytics/"],["Google Search Console","https://search.google.com/search-console"],["Matomo","https://matomo.org/"]]],["monitoring","Monitoring, errors & uptime","activity","Set up health checks, alerts, error tracking, incident response and cost/usage thresholds; avoid leaking secrets in logs.",[["Sentry","https://sentry.io/"],["Better Stack","https://betterstack.com/"],["UptimeRobot","https://uptimerobot.com/"],["Cloudflare Observability","https://developers.cloudflare.com/workers/observability/"],["Existing monitoring",""]]],["ci","CI/CD & build pipelines","git","Establish reproducible builds, protected branches, testing, scoped deploy credentials and safe release/rollback steps.",[["GitHub Actions","https://github.com/features/actions"],["GitLab CI/CD","https://about.gitlab.com/"],["Cloudflare Workers Builds","https://developers.cloudflare.com/workers/ci-cd/builds/"],["Existing build pipeline",""]]],["commerce","Storefront & fulfillment","shopping","If selling physical or digital products, configure catalog, taxes, shipping, delivery, returns and order reconciliation.",[["Shopify","https://www.shopify.com/"],["WooCommerce","https://woocommerce.com/"],["Printify","https://printify.com/"],["Custom storefront",""]]],["distribution","App distribution & signing","package","For downloadable or mobile apps, plan signed builds, publishing accounts, license delivery, update security and refund handling.",[["GitHub Releases","https://docs.github.com/en/repositories/releasing-projects-on-github"],["Apple Developer","https://developer.apple.com/"],["Google Play Console","https://play.google.com/console/"],["Microsoft Partner Center","https://partner.microsoft.com/"],["Direct downloads",""]]],["marketing","Marketing & advertising","megaphone","Choose acquisition channels that suit the audience and budget; verify disclosures, consent, advertising eligibility and measurement.",[["Google Ads","https://ads.google.com/"],["Google AdSense","https://adsense.google.com/"],["Mailchimp","https://mailchimp.com/"],["Kit","https://kit.com/"],["Organic / manual marketing",""]]],["support","Customer support & documentation","headphones","Set up a customer contact path, help documentation, escalation, privacy requests and support ownership.",[["Help Scout","https://www.helpscout.com/"],["Freshdesk","https://www.freshworks.com/freshdesk/"],["Zendesk","https://www.zendesk.com/"],["Existing support inbox",""]]]];

const LC_PLATFORM_STATES=['Not decided','Needs setup','Existing account','Configured (owner reported)','Not needed'];

function pdSlug(name){return name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function pdEntries(){const items=[];for(const [key,label,icon,guide,providers] of LC_PLATFORM_CATALOG)for(const [name,url] of providers)if(url)items.push({key,label,icon,name,url,slug:pdSlug(name)});for(const [name,url,icon,label] of [['GitHub','https://github.com/','git','Source control'],['ChatGPT','https://chatgpt.com/','bot','AI assistants'],['Claude','https://claude.ai/','bot','AI assistants']])items.push({key:'assistants',label,icon,name,url,slug:pdSlug(name)});return items}
function pdHref(name,project=''){return '/platforms/'+pdSlug(name)+(project?'?project='+encodeURIComponent(project):'')}
function pdSafeUrl(v){try{const u=new URL(v);return u.protocol==='https:'&&!u.username&&!u.password?u.href:''}catch{return ''}}
function pdStatus(doc){const date=doc?.verified_at;if(!date||!/^\d{4}-\d{2}-\d{2}$/.test(date))return {label:'Price review pending',cls:'pd-pending'};const age=(Date.now()-Date.parse(date+'T00:00:00Z'))/86400000;return age>30||age<0?{label:'Price needs recheck',cls:'pd-pending'}:{label:'Pricing checked '+date,cls:'pd-verified'}}
async function pdLoad(env){try{const obj=await env.TASK_DOCUMENTS.get('platform-directory/v1.json');if(!obj)return null;const data=await obj.json();return data?.schema===1&&data.providers&&typeof data.providers==='object'?data:null}catch{return null}}
function pdBadge(doc){const status=pdStatus(doc);return '<span class="pd-badge '+status.cls+'">'+lcIcon(status.cls==='pd-verified'?'check':'clock')+esc(status.label)+'</span>'}
function pdReferral(item){if(item.name==='SiteAPT')return '<p class="pd-disclosure">Related business under common ownership. Compare alternatives by fit and total cost.</p>';if(item.name==='Shopify')return '<p class="pd-disclosure">Project Zero is a Shopify affiliate and may earn a commission on qualifying referrals through the public guide. The private dashboard uses ordinary links; confirm dashboard traffic-source permission before offering the referral flow commercially.</p>';const opportunities={'DigitalOcean':['Affiliate program','https://www.digitalocean.com/affiliates'],'Hostinger':['Affiliate program','https://www.hostinger.com/affiliates'],'Shopify':['Affiliate program','https://www.shopify.com/affiliates'],'Cloudflare':['Partner program','https://www.cloudflare.com/partners/power-up-program/'],'Netlify':['Partner program','https://www.netlify.com/partners/']};const r=opportunities[item.name];return '<p class="pd-disclosure">'+(r?'Potential '+esc(r[0].toLowerCase())+' · not enrolled or approved. <a href="'+esc(r[1])+'" target="_blank" rel="noopener noreferrer">Program information ↗</a>. ':'')+'Provider guides open on our public guides site. Any compensated signup link on a guide is clearly disclosed; dashboard links themselves are ordinary links.</p>'}
async function pdPage(env,u){const entries=pdEntries(),project=lcId(u.searchParams.get('project')||'')?u.searchParams.get('project'):'';const back=project?lcWUrl(project,'setup'):'/lifecycle';const data=await pdLoad(env),docs=data?.providers||{};const dir='/platforms'+(project?'?project='+encodeURIComponent(project):'');const intro='<div class="lc-w-top"><a href="'+esc(back)+'">'+lcIcon('back')+' Project setup</a><a href="'+esc(dir)+'">'+lcIcon('layers')+' All platforms</a></div>';const warn=data?'':'<p class="warn">Provider summaries are temporarily unavailable. Use the official sites for current terms.</p>';if(u.pathname==='/platforms'){const q=(u.searchParams.get('q')||'').trim().slice(0,100).toLowerCase(),category=u.searchParams.get('category')||'',cats=[...new Map(entries.map(x=>[x.key,x.label])).entries()];const chosen=entries.filter(x=>(!category||x.key===category)&&(!q||[x.name,x.label,docs[x.name]?.best_for||''].join(' ').toLowerCase().includes(q)));const verified=entries.filter(x=>pdStatus(docs[x.name]).cls==='pd-verified').length;return response(lcPage('Project lifecycle — platform directory',intro+'<div class="pd-hero"><div class="lc-w-heading">'+lcIcon('layers')+'<div><small>PLATFORM DIRECTORY</small><h2>Compare your options</h2><p>Understand pricing, benefits and tradeoffs before selecting services. No account or purchase is required.</p></div></div><div class="pd-metrics"><div><strong>'+entries.length+'</strong><small>Provider guides</small></div><div><strong>'+verified+'</strong><small>Pricing checked in past 30 days</small></div><div><strong>Monthly</strong><small>Review target</small></div></div></div>'+warn+'<form class="pd-filter" method="get" action="/platforms">'+(project?'<input type="hidden" name="project" value="'+esc(project)+'">':'')+'<label>Find a platform<input name="q" maxlength="100" value="'+esc(q)+'" placeholder="Search providers"></label><label>Category<select name="category"><option value="">All categories</option>'+cats.map(([k,l])=>'<option value="'+esc(k)+'"'+(k===category?' selected':'')+'>'+esc(l)+'</option>').join('')+'</select></label><button type="submit">'+lcIcon('search')+' Search</button></form><div class="pd-grid">'+chosen.map(x=>{const d=docs[x.name];return '<a class="pd-card" href="'+pdHref(x.name,project)+'"><div class="pd-card-top"><span class="pd-mark">'+lcIcon(x.icon)+'</span><div><h3>'+esc(x.name)+'</h3><small>'+esc(x.label)+'</small></div>'+lcIcon('arrow')+'</div>'+pdBadge(d)+'<p>'+esc(d?.pricing||'See official pricing; review pending.')+'</p><small>'+esc(d?.best_for||'Review provider requirements and terms.')+'</small></a>'}).join('')+'</div>'+(!chosen.length?'<p>No matching providers.</p>':'')+'<p class="lc-note">Prices are illustrative US prices unless stated otherwise. Taxes, usage, promotions, renewal terms, region and plan eligibility can change the total. Always confirm at the provider before buying. Review pending means exact current pricing has not been checked.</p>'),200,'text/html;charset=utf-8')}const slug=u.pathname.slice('/platforms/'.length);const item=entries.find(x=>x.slug===slug);if(!item)return response('Platform not found',404);const d=docs[item.name],source=pdSafeUrl(d?.pricing_url)||item.url;const related=entries.filter(x=>x.key===item.key&&x.name!==item.name);return response(lcPage('Project lifecycle — '+item.name,intro+'<article class="pd-detail"><div class="pd-heading"><span class="pd-mark pd-large">'+lcIcon(item.icon)+'</span><div><small>'+esc(item.label)+'</small><h2>'+esc(item.name)+'</h2>'+pdBadge(d)+'</div></div>'+warn+'<div class="pd-price"><h3>'+lcIcon('credit-card')+' Pricing</h3><p>'+esc(d?.pricing||'Check the provider’s current official pricing.')+'</p><a class="lc-button" href="'+esc(source)+'" target="_blank" rel="noopener noreferrer">'+lcIcon('arrow')+' Official pricing ↗</a><small>Verify the final price, usage limits, eligibility, renewal rates and tax at checkout. '+(d?.verified_at?'Pricing checked '+esc(d.verified_at)+'.':'Current pricing review is pending.')+'</small></div><div class="pd-benefits">'+lcWBlock('check','Why use it','<p>'+esc(d?.benefits||'Review provider documentation.')+'</p>')+lcWBlock('users','Best for','<p>'+esc(d?.best_for||'Depends on your project needs.')+'</p>')+lcWBlock('shield','What to watch for','<p>'+esc(d?.tradeoffs||'Check costs, security, limitations and terms.')+'</p>')+'</div><div class="lc-actions"><a class="lc-button" href="https://guides.projectzero.work/platforms/'+encodeURIComponent(item.slug)+'" target="_blank" rel="noopener noreferrer">'+lcIcon('arrow')+' View '+esc(item.name)+' guide ↗</a>'+(project?'<a href="'+esc(back)+'">'+lcIcon('back')+' Return to project setup</a>':'')+'</div>'+pdReferral(item)+'<p class="lc-note">This guide does not connect an account, grant permissions, register a domain or authorize spending.</p></article>'+(related.length?'<section class="pd-related"><h2>'+lcIcon('layers')+' Compare alternatives</h2><div class="pd-grid">'+related.map(x=>'<a class="pd-card" href="'+pdHref(x.name,project)+'"><div class="pd-card-top"><span class="pd-mark">'+lcIcon(x.icon)+'</span><h3>'+esc(x.name)+'</h3>'+lcIcon('arrow')+'</div><p>'+esc(docs[x.name]?.pricing||'Review current pricing.')+'</p>'+pdBadge(docs[x.name])+'</a>').join('')+'</div></section>':'')+''),200,'text/html;charset=utf-8')}

function lcPlatformSummary(rows){return (rows||[]).filter(x=>x.status!=='Not decided').map(x=>{const c=LC_PLATFORM_CATALOG.find(v=>v[0]===x.category);return (c?.[1]||x.category)+': '+(x.provider||'No provider')+' ['+x.status+']; planned monthly cost '+(x.monthly_cents==null?'unknown':'USD '+(x.monthly_cents/100).toFixed(2))}).join('\n')}
function lcPlatforms(p,e,rows,profile,advanced=false){if(rows===null)return '<article><p class="warn">Platform setup data unavailable. Reload before editing.</p></article>';const recommended=new Set(lcRecommended(profile));const selected=rows.filter(r=>!['Not decided','Not needed'].includes(r.status));for(const r of selected)recommended.add(r.category);const known=selected.filter(r=>r.monthly_cents!==null);const cents=known.reduce((sum,r)=>sum+r.monthly_cents,0);const budget=p.budget_cents;const flag=budget!==null&&cents>budget;const summary=lcPlatformSummary(rows);const prompt='Review the platform setup for '+p.name+'.\nProject record: https://dash.projectzero.work/lifecycle?id='+p.id+'\nConcept: '+p.concept+'\nRepository: '+(e?.repository||'Not linked')+'\nBudget: '+(budget==null?'Not specified; no new spending without approval':'USD '+(budget/100).toFixed(2)+' monthly')+'\nSaved platform choices:\n'+(summary||'None selected yet')+'\nRecommend the smallest suitable stack for this project, including optional services only when justified. Reuse existing accounts and free options when appropriate; compare alternatives, terms, estimated total costs and dependencies. Identify P0 setup requirements, security and rollback checks. If authorized, help configure existing services using supported scoped connectors or CLI tools. Otherwise provide precise setup steps. Do not buy services, enter payment information, register domains, create new accounts, change production DNS, deploy publicly or disclose credentials without explicit approval. Verify actual configuration and cost limits; return any missing permissions or owner actions. Do not claim a platform is connected merely because a URL was saved.';
return '<details class="lc-brief" open id="lc-platforms"><summary>'+lcIcon('cloud')+' Platform setup · '+selected.length+' selected</summary><div class="lc-stage-body"><div class="lc-actions"><a href="/platforms?project='+encodeURIComponent(p.id)+'">'+lcIcon('layers')+' Browse provider directory</a></div><p>Plan or record existing hosting and services before generating development tasks. Every category is optional until the project needs it. No credentials, API keys or passwords belong in this form.</p><div class="lc-platform-budget"><strong>USD '+(cents/100).toFixed(2)+' / month</strong><span>Known planned costs · '+(selected.length-known.length)+' unknown · '+(budget==null?'No budget set':'Budget $'+(budget/100).toFixed(2))+'</span></div>'+(flag?'<p class="warn">Known monthly estimates already exceed your project cost ceiling.</p>':'')+'<p class="lc-note">Estimates only; provider billing and usage caps must be configured and verified separately.</p>'+(recommended.size?'<p class="lc-w-recommended">'+lcIcon('layers')+' Suggested categories for your selected project type; review before choosing providers.</p>':'<p class="lc-note">Choose a product type in Business to get a focused list, or open all platforms below.</p>')+LC_PLATFORM_CATALOG.filter(x=>advanced||recommended.has(x[0])).map(([key,label,icon,guide,providers])=>{const r=rows.find(v=>v.category===key);const custom=!!r?.provider&&!providers.some(x=>x[0]===r.provider);const current=custom?'__custom__':r?.provider||'';const options=[['','Choose a provider'],...providers.map(x=>[x[0],x[0]]),['__custom__','Other / manual provider']];const links=providers.filter(x=>x[1]).map(([name,url])=>'<a class="pd-provider-option" href="'+pdHref(name,p.id)+'">'+lcIcon(icon)+esc(name)+' · details</a>').join('');return '<details class="lc-platform-row"><summary><span class="lc-platform-name">'+lcIcon(icon)+esc(label)+'</span><span class="lc-platform-meta">'+esc(r?.provider||r?.status||'Not decided')+'</span></summary><div class="lc-stage-body"><p>'+esc(guide)+'</p>'+(lcStackHint(p,profile,key)?'<p class="lc-note">'+lcIcon('bulb')+' '+esc(lcStackHint(p,profile,key))+'</p>':'')+'<form class="mailform lc-form" method="post" action="/lifecycle/platform"><input type="hidden" name="id" value="'+esc(p.id)+'"><input type="hidden" name="category" value="'+key+'"><input type="hidden" name="revision" value="'+esc(r?.revision||0)+'"><label>Provider<select name="provider">'+options.map(([value,name])=>'<option value="'+esc(value)+'"'+(value===current?' selected':'')+'>'+esc(name)+'</option>').join('')+'</select></label><label>Other provider name (if selected)<input name="custom_provider" maxlength="100" value="'+esc(custom?r.provider:'')+'"></label><label>Setup status'+trSelect('status',LC_PLATFORM_STATES,r?.status||'Not decided')+'</label><label>Estimated monthly cost (USD)<input name="monthly" type="number" min="0" max="99999999" step="0.01" inputmode="decimal" value="'+esc(r?.monthly_cents==null?'':(r.monthly_cents/100).toFixed(2))+'"></label><label>Non-secret setup notes<textarea name="notes" maxlength="1200" placeholder="Requirements, account ownership, outstanding steps. Never enter credentials.">'+esc(r?.notes||'')+'</textarea></label><button type="submit">'+lcIcon('check')+' Save '+esc(label.toLowerCase())+'</button></form><div class="lc-provider-links">'+links+'</div><p class="lc-note">Compare pricing and benefits before visiting the provider. Saved setup status is owner-reported, not a verified API connection.</p></div></details>'}).join('')+(!advanced?'<div class="lc-actions"><a href="'+lcWUrl(p.id,'setup')+'&all=1">'+lcIcon('settings')+' All platform options</a></div>':'')+'<details class="lc-brief"><summary>'+lcIcon('bot')+' Have AI recommend or configure the stack</summary><div class="lc-stage-body">'+lcAssistantLinks('lc-platform-prompt','platform setup',prompt)+'</div></details><details class="lc-brief"><summary>'+lcIcon('credit-card')+' Partner &amp; referral opportunities</summary><div class="lc-stage-body"><p>Project Zero may earn revenue from approved affiliate programs. The program-information links below are ordinary, non-affiliate links. Choose services by fit, cost and security; commission never determines ranking.</p><div class="lc-provider-links"><a href="https://www.digitalocean.com/affiliates" target="_blank" rel="noopener noreferrer">DigitalOcean affiliate program ↗</a><a href="https://www.hostinger.com/affiliates" target="_blank" rel="noopener noreferrer">Hostinger affiliate program ↗</a><a href="https://www.cloudflare.com/partners/power-up-program/" target="_blank" rel="noopener noreferrer">Cloudflare partner program ↗</a><a href="https://www.netlify.com/partners/" target="_blank" rel="noopener noreferrer">Netlify partner program ↗</a></div><p>Shopify is approved and its public provider guide includes a disclosed affiliate link. Other programs require approval before activation. Disclose dashboard traffic sources and confirm the permitted project-setup referral flow before commercial use.</p></div></details></div></details>'}

function lcGitPanel(p,e,catalog){const repo=e?.repository||'',match=(catalog||[]).find(x=>x.url.toLowerCase()===repo.toLowerCase());return '<details class="lc-brief" open><summary>'+lcIcon('git')+' Git repository · '+(repo?'Linked':'Not linked')+'</summary><div class="lc-stage-body">'+(repo?'<p><strong>Current repository:</strong> '+esc(repo)+'</p><p class="lc-note">'+(match?'Present in the last authorized GitHub catalog ('+esc(match.visibility)+').':'Repository URL saved; assistant access not verified.')+'</p>':'<p>Connect an existing repository or create a new one for this project. <a href="'+pdHref('GitHub',p.id)+'">GitHub pricing &amp; benefits</a>.</p>')+'<form class="mailform lc-form" method="post" action="/lifecycle/repository"><input type="hidden" name="id" value="'+esc(p.id)+'"><input type="hidden" name="revision" value="'+esc(e?.revision||0)+'">'+lcRepoPicker(catalog,repo)+'<label>Repository HTTPS URL<input name="repository" type="url" maxlength="300" required data-lc-repo-url placeholder="https://github.com/owner/repo" value="'+esc(repo)+'"></label><button type="submit">'+lcIcon('git')+' '+(repo?'Update repository':'Connect repository')+'</button></form>'+lcRepoActions(p,repo)+'</div></details>'}

function lcExecution(p,e,catalog,intake){const mode=e?.mode||'Manual',repo=e?.repository||'',manual=mode==='Manual';const field=(label,name,v,placeholder)=>'<label>'+label+'<textarea name="'+name+'" maxlength="3000" placeholder="'+esc(placeholder)+'">'+esc(v||'')+'</textarea></label>';return '<details class="lc-brief" open><summary>'+lcIcon('users')+' Execution method &amp; assistant responsibilities</summary><form method="post" action="/lifecycle/execution" class="mailform lc-form"><input type="hidden" name="id" value="'+esc(p.id)+'"><input type="hidden" name="revision" value="'+esc(e?.revision||0)+'"><label>How will you build this?'+trSelect('mode',['Manual','AI-assisted','Mixed'],mode)+'</label>'+field('Manual work / review cadence','manual_plan',e?.manual_plan,'e.g. review tasks every Friday; owner handles billing')+field('ChatGPT schedule & responsibilities (optional)','chatgpt_plan',e?.chatgpt_plan,'e.g. hourly :30; implement highest actionable P0')+field('Claude schedule & responsibilities (optional)','claude_plan',e?.claude_plan,'e.g. hourly :00; review PRs and test')+'<button type="submit">'+lcIcon('check')+' Save execution settings</button></form><div class="lc-stage-body"><p>'+ (manual?'Manual mode requires no assistant, external repository or automation.':'Assistant connections and schedules are optional; verify them in the assistant before recording them as active.')+'</p><div class="lc-actions"><a href="/development/integration">Assistant connections</a>'+(repo?'<a href="'+esc(repo)+'" rel="noopener noreferrer">Repository ↗</a>':'')+'</div><p>These are recorded plans, not active scheduled tasks. Configure and verify schedules in the chosen assistant. Compare <a href="'+pdHref('ChatGPT',p.id)+'">ChatGPT</a> and <a href="'+pdHref('Claude',p.id)+'">Claude</a> plans. Do not enter credentials here.</p></div></details>'}

function lcAssistantLinks(id,kind,prompt){return '<div class="lc-assistant-handoff"><textarea readonly rows="9" class="lc-prompt" id="'+id+'" aria-label="'+esc(kind)+' prompt">'+esc(prompt)+'</textarea><div class="lc-actions"><button type="button" class="lc-button" data-lc-copy="'+id+'">Copy '+esc(kind)+' prompt</button><a href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">ChatGPT ↗</a><a href="https://claude.ai/new" target="_blank" rel="noopener noreferrer">Claude ↗</a></div><p class="lc-note" id="'+id+'-status" role="status">Copy the prompt, open your chosen assistant and paste it into a chat. Review the information before sharing.</p></div>'}
function lcPrompt(p,e,kind,tasks=[]){const info=['Project: '+p.name,'Project Zero record: '+(p.tracker_project?'https://dash.projectzero.work/development?project='+encodeURIComponent(p.tracker_project):'https://dash.projectzero.work/lifecycle?id='+encodeURIComponent(p.id)),'Concept: '+(p.concept||'Not yet defined'),'Target customer: '+(p.audience||'Not yet defined'),'Business model: '+(p.business_model||'Not yet defined'),'Monthly cost ceiling: '+(p.budget_cents==null?'Not set — no new spending without approval':'USD '+(p.budget_cents/100).toFixed(2)),'Repository: '+(e?.repository||'Not linked; ask for source or analyze the concept only'),'Constraints: '+p.notes,'Execution mode: '+(e?.mode||'Manual'),'Platform setup: '+(lcPlatformSummary(p.platforms)||'No selections recorded; recommend only necessary services'),'Product type: '+(p.wizardProfile?.product_type||'Undecided'),'Revenue type: '+(p.wizardProfile?.revenue_type||'Undecided'),'Technical experience: '+(p.wizardProfile?.experience||'Undecided'),'Reviewed analysis: '+(p.wizardProfile?.analysis||'Not recorded'),'Existing tasks to avoid duplicating: '+(tasks.length?tasks.map(t=>t.priority+' '+(t.title||t.task)).join('; '):'None supplied; inspect the live tracker if authorized')].join('\n');
const plan='Analyze this project as a product lead and software architect. If repository access is authorized, inspect its current source, README, issues and tests; do not assume access or invent findings. Otherwise use the brief and label assumptions. Identify the smallest viable product, missing features, security/privacy, payment and delivery requirements if applicable, design/mobile UX, deployment, monitoring, cost ceilings and dependencies. For a new project, include foundation and validation tasks. Prioritize P0 (launch-blocking security, reliability, core functionality, legal or billing requirements) and P1 (customer experience, growth and revenue improvements after P0), P2 (optimization) and Exposure (marketing after launch prerequisites). Do not duplicate existing work. For each task specify a concrete deliverable, dependencies, acceptance criteria and how to verify it in the requirements field. Do not modify the repository, buy services, deploy, collect credentials or schedule anything during analysis. Return a single valid JSON array only, no Markdown or commentary. Each item must contain exactly priority, title and requirements. Maximum 30 items; title <=250 characters; requirements <=4000 characters; total JSON <=50000 characters. Example shape: [{"priority":"P0","title":"Implement core workflow","requirements":"Deliverable: ...; Dependencies: ...; Acceptance criteria: ...; Verification: ..."}]. I will paste the JSON into Project Zero, preview and select tasks, then import approved work.';
const execution='Read the live project brief, instructions, tasks and repository before acting. Work only on this project and within authorized access. Choose the highest actionable P0, then P1, P2 and Exposure after launch prerequisites, respecting dependencies and existing claims. Claim using the current revision when supported; implement, test, commit, deploy only approved safe changes, verify live functionality and record evidence. Never claim Done without verification. Stop for owner-only decisions, missing permissions, unsafe spending or conflicts. Never expose credentials. Do not create schedules unless asked. Report task IDs, evidence and blockers. If this is a concept draft without a connected tracker, perform planning only; do not claim that it is in the shared execution queue.';
return info+'\n\n'+(kind==='plan'?plan:execution)}
function lcPlanning(p,e,tasks,trackerTasks){const list=tasks||[],existing=list.map(t=>'<div class="lc-plan-row"><strong>'+esc(t.priority)+' · '+esc(t.title)+'</strong><p>'+esc(t.requirements)+'</p>'+(p.tracker_project?'<a href="/development?q='+encodeURIComponent(t.id)+'">Open tracker task ↗</a>':'')+'</div>').join('');const count=trackerTasks?.length||0;const all=[...list,...(trackerTasks||[])];return '<section class="lc-brief" id="lc-planning"><div class="lc-stage-body"><h2 class="lc-step-title">'+lcIcon('list')+' Generate &amp; review tasks</h2><p>Choose manual entry or let your assistant create the first development backlog. '+esc(p.tracker_project?count+' existing tracker tasks (up to 200 shown to the assistant).':'New project draft — tasks are saved here.')+'</p><details class="lc-brief" open><summary>'+lcIcon('bot')+' Generate task list with AI (optional)</summary><div class="lc-stage-body"><p><strong>A. Copy and run the analysis prompt</strong></p><p>ChatGPT or Claude analyzes your idea and connected repository if available, then returns a list of P0/P1/P2/Exposure tasks in JSON.</p>'+lcAssistantLinks('lc-plan-prompt','analysis',lcPrompt(p,e,'plan',all))+'<p><strong>B. Paste the assistant response and review</strong></p><form method="post" action="/lifecycle/backlog" class="mailform lc-form" id="lc-import-form"><input type="hidden" name="id" value="'+esc(p.id)+'"><input type="hidden" name="request_id" value="'+crypto.randomUUID()+'"><label>Assistant task list<textarea name="import" id="lc-import-text" required maxlength="55000" rows="7" placeholder=\'[{"priority":"P0","title":"...","requirements":"..."}]\'></textarea></label><div class="lc-actions"><button type="button" id="lc-preview-plan">Preview tasks</button></div><div id="lc-import-feedback" role="status" class="lc-note"></div><div id="lc-import-preview"></div><label class="check"><input type="checkbox" name="confirm" value="yes" required> I reviewed the tasks and approve adding them.</label><button type="submit" id="lc-import-submit">Add approved tasks</button></form></div></details><details class="lc-brief"><summary>'+lcIcon('plus')+' Add tasks manually</summary><form method="post" action="/lifecycle/backlog" class="mailform lc-form"><input type="hidden" name="id" value="'+esc(p.id)+'"><input type="hidden" name="request_id" value="'+crypto.randomUUID()+'"><label>Priority'+trSelect('priority',['P0','P1','P2','Exposure'],'P0')+'</label><label>Task title<input name="title" required maxlength="250"></label><label>Requirements &amp; acceptance criteria<textarea name="requirements" required maxlength="4000"></textarea></label><button type="submit">Add task</button></form></details><h3>Lifecycle backlog · '+list.length+' added</h3>'+(existing||'<p>No lifecycle tasks yet.</p>')+'<p>'+ (p.tracker_project?'Approved tasks enter the shared development queue as Unassigned / Not started.':'Approved tasks are stored in the draft backlog until you explicitly activate the project.')+'</p></div></section>'}

async function lcExtraPost(req,env,path){if(!sameOriginPost(req)||!req.headers.get('content-type')?.startsWith('application/x-www-form-urlencoded'))return response('Forbidden',403);if(Number(req.headers.get('Content-Length')||0)>180000)return response('Too large',413);const raw=await req.text();if(raw.length>180000)return response('Too large',413);const f=new URLSearchParams(raw),str=k=>(f.get(k)||'').trim(),id=str('id');if(!lcId(id))return response('Invalid project',400);const fail=(msg,status=400)=>response(lcPage('Project lifecycle','<p class="warn">'+esc(msg)+'</p><div class="lc-actions"><a href="'+lcLink(id)+'">Return to project</a></div>'),status,'text/html;charset=utf-8');const saved=()=>new Response(null,{status:303,headers:{...headers,Location:lcReturnStep(f,id)+'&notice=review-saved'}});const db=env.TRACKER,p=await safeFirst(db,"SELECT * FROM lifecycle_projects WHERE id=? AND (tracker_project IS NULL OR tracker_project IN (SELECT project FROM tracker_active_projects))",id);if(!p?.id)return fail('Project unavailable',404);try{if(path==='/lifecycle/profile'){const part=str('part'),revision=Number(str('revision')),type=str('product_type'),revenue=str('revenue_type'),experience=str('experience'),analysis=str('analysis');if(!['type','analysis'].includes(part)||!Number.isSafeInteger(revision)||revision<0||(part==='type'&&(!LC_PRODUCT_TYPES.includes(type)||!LC_REVENUE_TYPES.includes(revenue)||!LC_EXPERIENCE.includes(experience)))||(part==='analysis'&&analysis.length>5000))return fail('Invalid project profile.');let result;if(revision===0){result=await (part==='type'?db.prepare("INSERT INTO lifecycle_profile(lifecycle_id,product_type,revenue_type,experience) VALUES(?,?,?,?) ON CONFLICT(lifecycle_id) DO NOTHING RETURNING revision").bind(id,type,revenue,experience):db.prepare("INSERT INTO lifecycle_profile(lifecycle_id,analysis) VALUES(?,?) ON CONFLICT(lifecycle_id) DO NOTHING RETURNING revision").bind(id,analysis)).first()}else{result=await (part==='type'?db.prepare("UPDATE lifecycle_profile SET product_type=?,revenue_type=?,experience=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE lifecycle_id=? AND revision=? RETURNING revision").bind(type,revenue,experience,id,revision):db.prepare("UPDATE lifecycle_profile SET analysis=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE lifecycle_id=? AND revision=? RETURNING revision").bind(analysis,id,revision)).first()}if(!result)return fail('Project profile changed. Reload before saving.',409);return saved()}if(path==='/lifecycle/platform'){const category=str('category'),catalog=LC_PLATFORM_CATALOG.find(x=>x[0]===category),choice=str('provider'),status=str('status'),notes=str('notes'),revision=Number(str('revision')),monthly=str('monthly'),cents=monthly?centsFrom(monthly):null;let provider=choice==='__custom__'?str('custom_provider'):choice;if(!catalog||!LC_PLATFORM_STATES.includes(status)||!Number.isSafeInteger(revision)||revision<0||notes.length>1200||provider.length>100||(choice==='__custom__'&&!provider)||(choice&&choice!=='__custom__'&&!catalog[4].some(x=>x[0]===choice))||(monthly&&(cents===null||!Number.isSafeInteger(cents)||cents<0||cents>9999999900))||(!['Not decided','Not needed'].includes(status)&&!provider))return fail('Choose a valid provider, setup status and optional cost.');if(status==='Not needed'){provider=''}const result=await db.prepare("INSERT INTO lifecycle_platforms(lifecycle_id,category,provider,status,monthly_cents,notes,revision) SELECT ?,?,?,?,?,?,1 WHERE ?=0 ON CONFLICT(lifecycle_id,category) DO NOTHING RETURNING revision").bind(id,category,provider,status,status==='Not needed'?null:cents,notes,revision).first();if(result)return saved();if(revision===0)return fail('Platform setup changed. Reload before saving.',409);const updated=await db.prepare("UPDATE lifecycle_platforms SET provider=?,status=?,monthly_cents=?,notes=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE lifecycle_id=? AND category=? AND revision=? RETURNING revision").bind(provider,status,status==='Not needed'?null:cents,notes,id,category,revision).first();if(!updated)return fail('Platform setup changed. Reload before saving.',409);return saved()}if(path==='/lifecycle/repository'){const repository=lcRepoUrl(str('repository')||str('catalog_repository')),revision=Number(str('revision'));if(!repository||!Number.isSafeInteger(revision)||revision<0)return fail('Enter a valid repository URL.');const existing=await safeFirst(db,'SELECT revision FROM lifecycle_execution WHERE lifecycle_id=?',id);if(existing===null)return fail('Repository settings unavailable.',503);let result;if(!existing.revision&&revision===0)result=await db.prepare("INSERT INTO lifecycle_execution(lifecycle_id,repository) VALUES(?,?) ON CONFLICT(lifecycle_id) DO NOTHING RETURNING lifecycle_id").bind(id,repository).first();else result=await db.prepare("UPDATE lifecycle_execution SET repository=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE lifecycle_id=? AND revision=? RETURNING lifecycle_id").bind(repository,id,revision).first();if(!result)return fail('Repository settings changed. Reload before saving.',409);return saved()}if(path==='/lifecycle/execution'){const mode=str('mode'),chatgpt=str('chatgpt_plan'),claude=str('claude_plan'),manual=str('manual_plan'),revision=Number(str('revision'));if(!['Manual','AI-assisted','Mixed'].includes(mode)||[chatgpt,claude,manual].some(v=>v.length>3000)||!Number.isSafeInteger(revision)||revision<0)return fail('Invalid execution settings');const existing=await safeFirst(db,'SELECT revision FROM lifecycle_execution WHERE lifecycle_id=?',id);if(existing===null)return fail('Settings unavailable',503);let result;if(!existing.revision&&revision===0)result=await db.prepare('INSERT INTO lifecycle_execution(lifecycle_id,mode,chatgpt_plan,claude_plan,manual_plan) VALUES(?,?,?,?,?) ON CONFLICT(lifecycle_id) DO NOTHING RETURNING lifecycle_id').bind(id,mode,chatgpt,claude,manual).first();else result=await db.prepare('UPDATE lifecycle_execution SET mode=?,chatgpt_plan=?,claude_plan=?,manual_plan=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE lifecycle_id=? AND revision=? RETURNING lifecycle_id').bind(mode,chatgpt,claude,manual,id,revision).first();if(!result)return fail('Settings changed. Reload before saving.',409);return saved()}
const request=str('request_id');if(!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(request))return fail('Invalid request');let tasks;const imp=str('import');if(imp){if(f.get('confirm')!=='yes'||imp.length>50000)return fail('Review and approve the task list before importing.');try{tasks=JSON.parse(imp)}catch{return fail('Use a valid JSON array of tasks.')}}else tasks=[{priority:str('priority'),title:str('title'),requirements:str('requirements')}];if(!Array.isArray(tasks)||!tasks.length||tasks.length>30||tasks.some(t=>!t||!['P0','P1','P2','Exposure'].includes(t.priority)||typeof t.title!=='string'||!t.title.trim()||t.title.length>250||typeof t.requirements!=='string'||!t.requirements.trim()||t.requirements.length>4000))return fail('Enter 1–30 valid P0/P1/P2/Exposure tasks with title and acceptance criteria.');const seen=new Set();for(const t of tasks){const k=t.title.trim().toLowerCase();if(seen.has(k))return fail('Duplicate titles in this plan.');seen.add(k)}const old=await safeRows(db,'SELECT id,title FROM lifecycle_backlog WHERE lifecycle_id=?',id);if(old===null)return fail('Backlog unavailable',503);const existingTitles=new Set(old.map(t=>t.title.trim().toLowerCase()));if(p.tracker_project){const current=await safeRows(db,'SELECT task FROM tracker_active_tasks WHERE project=?',p.tracker_project);if(current===null)return fail('Tracker unavailable',503);for(const t of current)existingTitles.add(t.task.trim().toLowerCase())}const writes=[];for(let i=0;i<tasks.length;i++){const t=tasks[i],key='LC-'+request.toUpperCase()+'-'+(i+1);if(old.some(x=>x.id===key))continue;if(existingTitles.has(t.title.trim().toLowerCase()))return fail('A task with this title already exists: '+t.title,409);writes.push(db.prepare('INSERT INTO lifecycle_backlog(lifecycle_id,id,priority,title,requirements) VALUES(?,?,?,?,?) ON CONFLICT(lifecycle_id,id) DO NOTHING').bind(id,key,t.priority,t.title.trim(),t.requirements.trim()));}if(writes.length)await db.batch(writes);return saved()}catch{return fail('Save could not be confirmed. Reload before retrying.',503)}}


function lcRepoUrl(value){const v=String(value||'').trim();if(!v)return '';try{const u=new URL(v);if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash||v.length>300)return null;if(u.hostname.toLowerCase()==='github.com'){const a=u.pathname.replace(/^\/|\/$/g,'').split('/');if(a.length!==2||!a.every(x=>/^[A-Za-z0-9_.-]+$/.test(x)&&x!=='.'&&x!=='..'))return null;const repo=a[1].replace(/\.git$/i,'');return repo?'https://github.com/'+a[0]+'/'+repo:null}return u.href.replace(/\/$/,'')}catch{return null}}
function lcRepoPicker(catalog,current){const seen=(catalog||[])[0]?.observed_at;return '<label>Choose an authorized GitHub repository<select name="catalog_repository" data-lc-repo-picker><option value="">Select a repository (optional)</option>'+(catalog||[]).map(x=>'<option value="'+esc(x.url)+'" data-repo-name="'+esc(x.repository.split('/').pop())+'"'+(current===x.url?' selected':'')+'>'+esc(x.repository)+' · '+esc(x.visibility)+'</option>').join('')+'</select></label><p class="lc-note">'+(seen?'GitHub list last checked '+esc(seen.replace('T',' ').slice(0,16))+' UTC.':'No repository catalog available.')+' This is a saved list, not a live GitHub login. You can paste another URL.</p>'}
function lcRepoActions(p,repo){const prompt='Set up Git for '+(p?.name||'my new project')+'. Check for an existing repository first. If I authorize creation and you have permission, confirm the owner and name and create a PRIVATE GitHub repository, with README and .gitignore where appropriate. Never push credentials, customer data, backups or private configuration. If creation is unavailable, explain the manual steps. Return the verified HTTPS repository URL.';return '<div class="lc-actions"><a href="https://github.com/new" target="_blank" rel="noopener noreferrer">Create GitHub repository ↗</a>'+(repo?'<a href="'+esc(repo)+'" target="_blank" rel="noopener noreferrer">Open repository ↗</a>':'')+'</div><details class="lc-brief"><summary>'+lcIcon('git')+' Have an assistant set up Git</summary><div class="lc-stage-body">'+lcAssistantLinks('lc-git-prompt','Git setup',prompt)+'</div></details><p class="lc-note">Create privately by default, then return and save the repository URL. Linking a URL does not grant repository access; authorize the assistant separately.</p>'}

async function lcIntakePage(env,existing){const catalog=existing?await safeRows(env.TRACKER,'SELECT * FROM lifecycle_repo_catalog ORDER BY repository'):[];const heading=existing?'Bring in a project':'Start with an idea';const main='<label>Project name<input name="name" maxlength="120" placeholder="'+(existing?'Name or select a repository below':'Give your idea a working name')+'"'+(existing?'':' required')+'></label><label>'+(existing?'What does it do? (optional)':'What do you want to build?')+'<textarea name="concept" maxlength="4000" rows="4"'+(existing?'':' required')+' placeholder="'+(existing?'The assistant can review source later.':'Describe the problem and your idea.')+'"></textarea></label><label>Monthly spending limit (USD, optional)<input name="budget" type="number" min="0" max="99999999" step="0.01" inputmode="decimal" placeholder="0.00"></label>';const git='<label>Git setup<select name="repo_choice"><option value="none" selected>No repository / decide later</option><option value="link">Connect existing repository</option><option value="create">Create new repository later</option></select></label>'+lcRepoPicker(catalog,'')+'<label>Repository URL (optional)<input name="repository" type="url" maxlength="300" placeholder="https://github.com/owner/repo" data-lc-repo-url></label>';const optional='<label>Website (optional)<input name="website" type="url" maxlength="300"></label><label>Target customer<textarea name="audience" maxlength="4000"></textarea></label><label>Business model<textarea name="business_model" maxlength="4000"></textarea></label><label>Execution method'+trSelect('mode',['Manual','AI-assisted','Mixed'],'Manual')+'</label><label>Constraints / notes<textarea name="notes" maxlength="4000"></textarea></label>';return response(lcPage('Project lifecycle','<div class="lc-w-top"><a href="/lifecycle">'+lcIcon('back')+' All projects</a></div><article class="lc-w-stage"><div class="lc-w-heading">'+lcIcon(existing?'folder':'bulb')+'<div><small>GET STARTED</small><h2>'+heading+'</h2><p>'+(existing?'Link your existing project or enter its details. Nothing is changed in GitHub or production.':'You only need a name and an idea. We will guide the rest.')+'</p></div></div><form class="mailform lc-form" method="post" action="/lifecycle/intake"><input type="hidden" name="id" value="'+crypto.randomUUID()+'"><input type="hidden" name="origin" value="'+(existing?'existing':'new')+'">'+main+(existing?lcWBlock('git','Link source code (optional)',git):'<input type="hidden" name="repo_choice" value="none">')+'<details class="lc-brief"><summary>'+lcIcon('settings')+' More project details (optional)</summary><div class="lc-stage-body">'+optional+'</div></details><button type="submit">'+lcIcon('plus')+' '+(existing?'Add existing project':'Create project')+lcIcon('arrow')+'</button></form><p class="lc-note">No purchases or account setup will occur. You can add a repository and services later.</p></article>'),200,'text/html;charset=utf-8')}

async function lcIntakePost(req,env){if(!sameOriginPost(req)||!req.headers.get('content-type')?.startsWith('application/x-www-form-urlencoded'))return response('Forbidden',403);if(Number(req.headers.get('Content-Length')||0)>80000)return response('Too large',413);const raw=await req.text();if(raw.length>80000)return response('Too large',413);const f=new URLSearchParams(raw),str=k=>(f.get(k)||'').trim(),id=str('id'),origin=str('origin'),choice=str('repo_choice'),mode=str('mode'),concept=str('concept'),audience=str('audience'),model=str('business_model'),notes=str('notes'),website=lcRepoUrl(str('website')),repo=lcRepoUrl(str('repository')||str('catalog_repository')),budget=str('budget'),cents=budget?centsFrom(budget):null,name=str('name')||(repo?.startsWith('https://github.com/')?repo.split('/').pop():'');const fail=(msg,status=400)=>response(lcPage('Project lifecycle','<p class="warn">'+esc(msg)+'</p><div class="lc-actions"><a href="/lifecycle?'+(origin==='existing'?'import':'new')+'=1">Return to project setup</a><a href="/lifecycle">All projects</a></div>'),status,'text/html;charset=utf-8');if(!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)||!['new','existing'].includes(origin)||!['link','create','none'].includes(choice)||!['Manual','AI-assisted','Mixed'].includes(mode)||!name||name.length>120||[concept,audience,model,notes].some(v=>v.length>4000)||repo===null||website===null||(choice==='link'&&!repo)||(choice==='none'&&repo)||(origin==='new'&&!concept)||(budget&&cents===null))return fail('Enter valid project details. Choose a repository URL for Connect existing, or select No repository.');
const db=env.TRACKER;try{const existing=await safeFirst(db,'SELECT id FROM lifecycle_projects WHERE id=?',id);if(existing===null)return fail('Project lookup unavailable',503);if(existing.id)return new Response(null,{status:303,headers:{...headers,Location:lcLink(id)}});const dupe=await safeFirst(db,"SELECT p.id,p.name FROM lifecycle_projects p LEFT JOIN lifecycle_execution e ON e.lifecycle_id=p.id WHERE lower(trim(p.name))=lower(trim(?)) OR (?<>'' AND lower(rtrim(COALESCE(e.repository,''),'/'))=lower(?)) LIMIT 1",name,repo,repo);if(dupe===null)return fail('Project lookup unavailable',503);if(dupe.id)return response(lcPage('Project lifecycle','<p class="warn">A project with that name or repository already exists.</p><div class="lc-actions"><a href="'+lcLink(dupe.id)+'">Open '+esc(dupe.name)+'</a><a href="/lifecycle">All projects</a></div>'),409,'text/html;charset=utf-8');await db.batch([db.prepare('INSERT INTO lifecycle_projects(id,name,concept,audience,business_model,budget_cents,notes) VALUES(?,?,?,?,?,?,?)').bind(id,name,concept,audience,model,cents,notes),db.prepare('INSERT INTO lifecycle_intake(lifecycle_id,origin,website,repo_choice) VALUES(?,?,?,?)').bind(id,origin,website,choice),db.prepare('INSERT INTO lifecycle_execution(lifecycle_id,mode,repository) VALUES(?,?,?)').bind(id,mode,repo),...LC_STAGES.map(([stage])=>db.prepare('INSERT INTO lifecycle_gates(lifecycle_id,stage) VALUES(?,?)').bind(id,stage))]);return new Response(null,{status:303,headers:{...headers,Location:lcWUrl(id,origin==='existing'?'analyze':'brief')+'&notice=review-saved'}})}catch{return fail('Project creation could not be confirmed. Check the project list before retrying.',503)}}

function lcBriefForm(p){const create=!p;const field=(label,name,value,placeholder,required=false,max=4000)=>'<label>'+label+'<textarea name="'+name+'" maxlength="'+max+'" placeholder="'+esc(placeholder)+'"'+(required?' required':'')+'>'+esc(value||'')+'</textarea></label>';return '<form class="mailform lc-form" method="post" action="/lifecycle/'+(create?'create':'brief')+'"><input type="hidden" name="id" value="'+esc(p?.id||crypto.randomUUID())+'">'+(!create?'<input type="hidden" name="revision" value="'+esc(p.revision)+'">':'')+'<label>Project name<input name="name" maxlength="120" required value="'+esc(p?.name||'')+'"'+(p?.tracker_project?' readonly':'')+' placeholder="Working name"></label>'+field('Concept / problem','concept',p?.concept,'What problem does this business solve?',create)+field('Target customer','audience',p?.audience,'Who needs it and why?')+field('Business model &amp; pricing','business_model',p?.business_model,'Paid plans, demo or trial, costs and revenue assumptions')+'<label>Monthly cost ceiling (USD, optional)<input type="number" name="budget" min="0" max="99999999" step="0.01" inputmode="decimal" value="'+esc(p?.budget_cents==null?'':(p.budget_cents/100).toFixed(2))+'"></label>'+field('Decision notes','notes',p?.notes,'Constraints, risks, decisions and evidence')+'<button type="submit">'+(create?'Create project draft':'Save project brief')+'</button></form>'}
async function lifecyclePage(env,u){if(u.searchParams.get('help')==='1')return lcHelpPage();const id=u.searchParams.get('id');if(u.searchParams.get('new')==='1'||u.searchParams.get('import')==='1')return lcIntakePage(env,u.searchParams.get('import')==='1');
if(!id){const rows=await safeRows(env.TRACKER,"SELECT l.* FROM lifecycle_projects l WHERE l.tracker_project IS NULL OR l.tracker_project IN (SELECT project FROM tracker_active_projects) ORDER BY l.updated_at DESC,l.name LIMIT 200");const gates=await safeRows(env.TRACKER,"SELECT lifecycle_id,stage,status FROM lifecycle_gates");const cards=rows===null||gates===null?'<p class="warn">Lifecycle records unavailable.</p>':rows.length?rows.map(p=>{const gs=gates.filter(g=>g.lifecycle_id===p.id),next=LC_STAGES.find(([k])=>gs.find(g=>g.stage===k)?.status!=='Approved');return '<a class="lc-card" href="'+lcLink(p.id)+'"><div class="lc-card-top">'+lcLogo(p)+'<strong>'+esc(p.name)+'</strong></div>'+lcBar(gs)+'<small>'+gs.filter(g=>g.status==='Approved').length+'/'+LC_STAGES.length+' approved · '+esc(next?.[1]||'All gates reviewed')+'</small><small>'+esc(p.tracker_project?'Linked to development':'Concept draft')+'</small></a>'}).join(''):'<article>No project drafts.</article>';return response(lcPage('Project lifecycle','<div class="lc-top"><h2>Start or resume a project</h2><a href="/investments">Portfolio review</a><a href="/integrations">Integrations</a></div><div class="lc-w-start"><a href="/lifecycle?new=1">'+lcIcon('bulb')+'<strong>New idea</strong><small>Start with an idea and build your plan.</small></a><a href="/lifecycle?import=1">'+lcIcon('folder')+'<strong>Existing project</strong><small>Bring in your repository or business.</small></a></div><div class="lc-grid">'+cards+'</div><p class="lc-note">Existing projects start with unreviewed gates. Approvals record owner decisions, not automatic purchases or launches.</p>'),200,'text/html;charset=utf-8')}
if(!lcId(id))return response('Not found',404);const p=await safeFirst(env.TRACKER,"SELECT * FROM lifecycle_projects WHERE id=? AND (tracker_project IS NULL OR tracker_project IN (SELECT project FROM tracker_active_projects))",id);if(!p?.id)return response('Not found',404);const gs=await safeRows(env.TRACKER,"SELECT * FROM lifecycle_gates WHERE lifecycle_id=?",id);if(gs===null||gs.length!==LC_STAGES.length)return response('Lifecycle data unavailable',503);const intake=await safeFirst(env.TRACKER,'SELECT * FROM lifecycle_intake WHERE lifecycle_id=?',id);const catalog=await safeRows(env.TRACKER,'SELECT * FROM lifecycle_repo_catalog ORDER BY repository');const observations=await safeRows(env.TRACKER,'SELECT * FROM lifecycle_schedule_observations ORDER BY title');const execution=await safeFirst(env.TRACKER,'SELECT * FROM lifecycle_execution WHERE lifecycle_id=?',id);const platformRows=await safeRows(env.TRACKER,'SELECT * FROM lifecycle_platforms WHERE lifecycle_id=? ORDER BY category',id);p.platforms=platformRows;const profile=await safeFirst(env.TRACKER,'SELECT * FROM lifecycle_profile WHERE lifecycle_id=?',id);p.wizardProfile=profile;const backlog=await safeRows(env.TRACKER,'SELECT * FROM lifecycle_backlog WHERE lifecycle_id=? ORDER BY priority,created_at,id',id);const trackerTasks=p.tracker_project?await safeRows(env.TRACKER,'SELECT priority,task FROM tracker_active_tasks WHERE project=? ORDER BY priority,task_id LIMIT 200',p.tracker_project):[];const summary=p.tracker_project?await safeFirst(env.TRACKER,"SELECT COUNT(*) total,SUM(status='Done') done,SUM(priority='P0' AND (status<>'Done' OR trim(evidence)='')) p0,SUM(status='Blocked') blocked FROM tracker_active_tasks WHERE project=?",p.tracker_project):null;const history=await safeRows(env.TRACKER,'SELECT stage,action,revision,changed_at FROM lifecycle_history WHERE lifecycle_id=? ORDER BY id DESC LIMIT 30',id);const business=await lbRead(env,p);return lcWizardPage(p,execution,intake,catalog,observations,backlog,trackerTasks,gs,profile,u,summary,history,business)}
async function lifecyclePost(req,env,path){if(!sameOriginPost(req)||!req.headers.get('content-type')?.startsWith('application/x-www-form-urlencoded'))return response('Forbidden',403);if(Number(req.headers.get('Content-Length')||0)>80000)return response('Too large',413);const raw=await req.text();if(raw.length>80000)return response('Too large',413);const f=new URLSearchParams(raw),str=k=>(f.get(k)||'').trim(),id=str('id'),rev=Number(str('revision'));if(!lcId(id))return response('Invalid project',400);const back=(message,status=400)=>response(lcPage('Project lifecycle','<p class="warn">'+esc(message)+'</p><div class="lc-actions"><a href="'+lcLink(id)+'">Return to project</a><a href="/lifecycle">All projects</a></div>'),status,'text/html;charset=utf-8');const saved=()=>new Response(null,{status:303,headers:{...headers,Location:lcReturnStep(f,id)+'&notice=review-saved'}});
try{if(path==='/lifecycle/create'||path==='/lifecycle/brief'){const name=str('name'),concept=str('concept'),audience=str('audience'),model=str('business_model'),notes=str('notes'),budget=str('budget'),cents=budget?centsFrom(budget):null;if(!name||name.length>120||[concept,audience,model,notes].some(v=>v.length>4000)||(budget&&cents===null))return back('Enter a valid name, brief and optional budget.');if(path==='/lifecycle/create'){if(!/^[0-9a-f-]{36}$/.test(id)||!concept)return back('Enter a project name and concept.');const db=env.TRACKER;await db.batch([db.prepare("INSERT INTO lifecycle_projects(id,name,concept,audience,business_model,budget_cents,notes) VALUES(?,?,?,?,?,?,?) ON CONFLICT(id) DO NOTHING").bind(id,name,concept,audience,model,cents,notes),...LC_STAGES.map(([stage])=>db.prepare("INSERT INTO lifecycle_gates(lifecycle_id,stage) SELECT id,? FROM lifecycle_projects WHERE id=? ON CONFLICT(lifecycle_id,stage) DO NOTHING").bind(stage,id))]);return saved()}if(!Number.isSafeInteger(rev)||rev<1)return back('Invalid revision');const r=await env.TRACKER.prepare("UPDATE lifecycle_projects SET name=CASE WHEN tracker_project IS NULL THEN ? ELSE name END,concept=?,audience=?,business_model=?,budget_cents=?,notes=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id=? AND revision=? AND (tracker_project IS NULL OR tracker_project IN (SELECT project FROM tracker_active_projects)) RETURNING id").bind(name,concept,audience,model,cents,notes,id,rev).first();if(!r)return back('Project changed. Reload before saving.',409);return saved()}
const stage=str('stage'),status=str('status'),evidence=str('evidence'),idx=LC_STAGES.findIndex(x=>x[0]===stage);if(idx<0||!LC_STATES.includes(status)||evidence.length>8000||!Number.isSafeInteger(rev)||rev<1||(status==='Approved'&&!evidence))return back('Choose a valid review status; approval requires evidence.');const earlier=LC_STAGES.slice(0,idx).map(x=>x[0]),later=LC_STAGES.slice(idx+1).map(x=>x[0]);let sql="UPDATE lifecycle_gates SET status=?,evidence=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE lifecycle_id=? AND stage=? AND revision=? AND EXISTS(SELECT 1 FROM lifecycle_projects p WHERE p.id=lifecycle_gates.lifecycle_id AND (p.tracker_project IS NULL OR p.tracker_project IN (SELECT project FROM tracker_active_projects)))";const params=[status,evidence,id,stage,rev];if(status==='Approved'&&earlier.length){sql+=" AND (SELECT COUNT(*) FROM lifecycle_gates g WHERE g.lifecycle_id=? AND g.stage IN ("+earlier.map(()=>'?').join(',')+") AND g.status='Approved')=?";params.push(id,...earlier,earlier.length)}if(status!=='Approved'&&later.length){sql+=" AND NOT EXISTS(SELECT 1 FROM lifecycle_gates g WHERE g.lifecycle_id=? AND g.stage IN ("+later.map(()=>'?').join(',')+") AND g.status='Approved')";params.push(id,...later)}const result=await env.TRACKER.prepare(sql+' RETURNING lifecycle_id').bind(...params).first();if(!result)return back('Review not saved. Reload, approve earlier gates first, or reopen later approved gates first.',409);return saved()}catch{return back('Save could not be confirmed. Reload the project before retrying.',503)}}

// Owner account page: who is signed in, subscriptions (none until billing launches) and sign out.
function pzAccountPage(env){const email=String(env.OWNER_EMAIL||'');const body='<div class="grid"><article><h3>Signed in</h3>'+(email?'<p><b>'+esc(email)+'</b></p>':'')+'<p class="muted">Owner of the Project Zero workspace. Sign-in is handled by your Google account and Cloudflare Access; Project Zero stores no password.</p><div class="actions"><a class="button" href="/workspace-sign-out">Sign out</a></div></article>'+'<article id="subscriptions"><h3>Subscriptions</h3><p>No subscription on this workspace.</p><p class="muted">Project Zero paid plans are not available yet. When billing launches, your plan, invoices and cancellation will be managed here.</p></article></div>';return page('Account',body)}
function primaryNav(title){const tabs=[['Overview','/'],['Inbox','/inbox'],['Finance','/finance'],['Customers','/customers'],['Traffic','/traffic'],['Usage','/usage'],['Operations','/operations'],['Development','/development'],['Lifecycle','/lifecycle'],['Brands','/brands'],['Secrets','/secrets']];const active=/chamber of secrets|secret/i.test(title)?'/secrets':/^account$/i.test(title)?'/account':/project lifecycle|portfolio investment review/i.test(title)?'/lifecycle':/brand library|edit brand|brand update/i.test(title)?'/brands':/development|assistant integration|MCP integration|assistant coordination|task changed|update rejected/i.test(title)?'/development':/dashboard|executive overview|executive action center|daily executive briefing/i.test(title)?'/':/inbox|email|sent history|reply|delivery/i.test(title)?'/inbox':/profit|finance|reconciliation/i.test(title)?'/finance':/customer|license/i.test(title)?'/customers':/traffic|performance/i.test(title)?'/traffic':/usage/i.test(title)?'/usage':/operations|security/i.test(title)?'/operations':'';return '<header><nav><div class="masthead"><a class="pz-home" href="/" aria-label="Project Zero overview"><img src="/logo.svg" width="32" height="32" alt=""><b>Project Zero</b></a><span>Executive workspace</span></div><div class="utility-links"><details class="pz-desktop-app pz-account"><summary><svg aria-hidden="true" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="8" r="4"/><path d="M4 21c1.5-4 4.5-6 8-6s6.5 2 8 6"/></svg> Account</summary><div class="pz-desktop-app-panel pz-account-panel"><a href="/account">Account</a><a href="/account#subscriptions">Subscriptions</a><a href="/workspace-sign-out">Sign out</a></div></details></div></nav><div class="section-nav" aria-label="Dashboard sections">'+tabs.map(([label,path])=>'<a href="'+path+'"'+(path===active?' aria-current="page"':'')+'>'+label+'</a>').join('')+'<details class="pz-desktop-app"><summary><svg aria-hidden="true" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="7" y="2" width="10" height="20" rx="2"/><path d="M11 18h2"/></svg> Alerts &amp; app</summary><div class="pz-desktop-app-panel"><h3>Web app</h3><button class="button" id="pz-install-direct" type="button" aria-expanded="false" aria-controls="pz-install-direct-help">Install app</button><div id="pz-install-direct-help" hidden class="warn"><b>Install Project Zero</b><p>Android: open Chrome, tap the menu and choose Install app or Add to Home screen.</p><p>iPhone/iPad: open Safari, tap Share, then Add to Home Screen.</p><p>Desktop: use the install icon or install option in Chrome or Edge.</p></div><p class="pz-app-installed">You are using the installed app.</p><h3>Alerts</h3><a href="/actions">Open action center</a><p>Review items that need your attention.</p></div></details></div></header>'+pzMobileNav(active)}

const css="*{box-sizing:border-box}body{margin:0;background:#f7f8fa;color:#191919;font:15px/1.5 system-ui,-apple-system,sans-serif}header{background:#fff;border-bottom:1px solid #e4e5e7}nav{max-width:1280px;margin:auto;display:flex;align-items:center;justify-content:space-between;padding:16px 24px;gap:12px}nav b{font-size:17px;letter-spacing:-.03em}nav a{font-size:13px}.section-nav .pz-desktop-app summary{font-size:13px;font-weight:550;line-height:1.25;min-height:36px;padding:8px 12px;border-radius:8px;color:#4b5563}.section-nav .pz-desktop-app summary:hover{background:#f3f4f6}.section-nav .pz-desktop-app-panel{left:0;right:auto}.section-nav .pz-desktop-app-panel a{justify-content:flex-start;padding:0;min-height:40px;font-size:14px;color:#252a32}.section-nav .pz-desktop-app-panel a:hover{background:none;text-decoration:underline}.pz-account-panel{width:220px;gap:2px;padding:8px}.pz-account-panel a{display:flex;align-items:center;padding:0 10px;border-radius:8px;font-size:14px}.pz-account-panel a:hover{background:#f3f4f6;text-decoration:none}.pz-account-panel a[href=\"/workspace-sign-out\"]{border-top:1px solid #eceef1;border-radius:0 0 8px 8px;margin-top:4px}main{max-width:1280px;padding:28px 24px 50px;margin:auto}h1{font-size:32px;letter-spacing:-.045em;line-height:1.15;margin:0}h2{font-size:19px;letter-spacing:-.025em;line-height:1.2;margin:3px 0 0}h3{font-size:17px;margin:0 0 14px}.lead{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0 0 22px}.muted,.type,.sub{color:#656b74;font-size:13px}.summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:22px}.summary>div,article,.usage{background:white;border:1px solid #e2e4e8;border-radius:12px;padding:18px}.summary strong{display:block;font-size:29px;font-variant-numeric:tabular-nums;letter-spacing:-.045em}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.cardtop{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}.status{font-size:11px;font-weight:600;border:1px solid #d9dde2;padding:4px 8px;border-radius:20px;white-space:nowrap;color:#4b5563}.connected{color:#186343;border-color:#b9dfca;background:#f2fbf6}.unavailable,.partial{color:#925c0a;background:#fff8ec;border-color:#ebd2a8}.metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:18px 0}.metrics>div{padding:10px 0;border-bottom:1px solid #edf0f2;min-width:0}.metrics strong{display:block;font-size:24px;letter-spacing:-.035em;font-variant-numeric:tabular-nums}.metrics span{display:block;font-size:12px;color:#656b74}.actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:14px}a{color:#252a32;text-decoration:none}a:hover{text-decoration:underline}.actions a,.button{font-size:13px;padding:7px 10px;border:1px solid #dfe2e6;border-radius:7px;background:#fff}.actions .primary{color:#fff;background:#191919;border-color:#191919}.section{margin:26px 0 12px;font-size:13px;font-weight:650;text-transform:uppercase;letter-spacing:.07em;color:#626975}.usage{margin-top:14px}.usage .metrics{grid-template-columns:repeat(3,minmax(0,1fr));margin:0}.foot{margin-top:22px;color:#656b74;font-size:12px}.navlinks{display:flex;gap:14px;align-items:center;flex-wrap:wrap}@media(max-width:740px){main{padding:20px 14px}nav{padding:14px}.grid{grid-template-columns:1fr}.summary{gap:8px}.summary>div{padding:11px}.summary strong{font-size:23px}.summary .muted{font-size:11px}.lead{align-items:flex-start}h1{font-size:25px}.usage .metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.status{white-space:normal;text-align:right}}";



async function piRead(env){try{const o=await env.BRAND_FILES.get('infrastructure/inventory-v1.json');if(!o||o.size>300000)return null;const x=await o.json();return x?.schema===1&&Array.isArray(x.workers)&&Array.isArray(x.databases)&&Array.isArray(x.buckets)?x:null}catch{return null}}
async function piPage(env,u){const x=await piRead(env);if(!x)return response(page('Operations · infrastructure inventory','<article><p class="warn">Inventory snapshot unavailable. No resources are assumed missing.</p><a href="/operations">Operations</a></article>'),503,'text/html;charset=utf-8');const q=(u.searchParams.get('q')||'').trim().toLowerCase().slice(0,120),review=u.searchParams.get('review')==='1',workers=x.workers.filter(w=>(!q||JSON.stringify(w).toLowerCase().includes(q))&&(!review||w.review.startsWith('Review'))),dbs=x.databases.filter(r=>!q||JSON.stringify(r).toLowerCase().includes(q)),buckets=x.buckets.filter(r=>!q||JSON.stringify(r).toLowerCase().includes(q));const stamp=esc(x.observed_at||'Unknown');const route=x.route_coverage,schedule=x.schedule_coverage;const ownerRows=Object.entries(x.workers.reduce((acc,w)=>{const k=w.suggested_project||'Unmapped';acc[k]=(acc[k]||0)+1;return acc},{})).sort((a,b)=>a[0].localeCompare(b[0]));const attribution='<article><h3>Proposed business ownership</h3><p class="muted">Review these mappings before assigning any costs. Shared resources are not duplicated across businesses.</p>'+ownerRows.map(([name,count])=>'<div class="pi-dep"><strong>'+esc(name)+'</strong><span>'+fmt(count)+' Workers</span><a href="/operations/inventory?q='+encodeURIComponent(name)+'">Review ↗</a></div>').join('')+'<p class="muted">Actual charges are unavailable by resource. <a href="/finance/expenses">Record confirmed vendor commitments</a> separately from <a href="/finance/reconcile">actual reconciled costs</a>.</p></article>';const cards=workers.map(w=>'<article class="pi-card"><div class="px-head"><h3>'+esc(w.name)+'</h3><small>'+esc(w.review)+'</small></div><div class="pi-meta"><span>Modified '+esc(w.modified_at?.slice(0,10)||'Unknown')+'</span><span>Custom domains: '+fmt(w.custom_domains?.length)+'</span></div><p class="muted">'+esc(w.suggested_project||'Unmapped')+' · proposed ownership · '+esc(w.environment_hint||'Environment unknown')+'</p><details><summary>Routes &amp; schedules · '+fmt(w.route_patterns?.length)+' routes / '+fmt(w.cron?.length)+' cron</summary><p>'+(!Array.isArray(w.route_patterns)?'Routes unavailable':w.route_patterns.length?w.route_patterns.map(esc).join('<br>'):'No zone routes recorded')+'</p><p>'+(!Array.isArray(w.cron)?'Schedules unavailable':w.cron.length?w.cron.map(esc).join('<br>'):'No cron schedules recorded')+'</p></details>'+(w.custom_domains?.length?'<p>'+w.custom_domains.map(d=>esc(d.hostname)+(d.enabled?'':' (disabled)')).join(' · ')+'</p>':'<p class="muted">No custom domain recorded; other routes may exist.</p>')+'<details><summary>Resource dependencies · '+(w.dependencies===null?'Unavailable':fmt(w.dependencies.length))+'</summary>'+(w.dependencies===null?'<p>Bindings unavailable.</p>':w.dependencies.length?w.dependencies.map(b=>'<div class="pi-dep"><span>'+esc(b.binding)+' · '+esc(b.type)+'</span><b>'+esc(b.target)+'</b></div>').join(''):'<p>No listed resource bindings.</p>')+'<p class="px-note">Repository and deployed commit not confirmed. Verify route patterns, schedules, email, queue consumers and service calls before removing anything.</p></details></article>').join('');const list=(rows,db=false)=>rows.map(r=>'<div class="pi-dep"><div><strong>'+esc(r.name)+'</strong><small>Created '+esc(r.created_at?.slice(0,10)||'Unknown')+'</small></div>'+(db?'<span>'+esc(r.jurisdiction?'Jurisdiction: '+r.jurisdiction:'No explicit jurisdiction reported')+'</span>':'')+'</div>').join('');const body='<div class="px-head"><p class="muted">Read-only Cloudflare resource snapshot · '+stamp+'</p><a class="button" href="/operations">Operations</a></div><div class="px-kpis"><div><small>Workers</small><strong>'+fmt(x.workers.length)+'</strong></div><div><small>D1 databases</small><strong>'+fmt(x.databases.length)+'</strong></div><div><small>R2 buckets</small><strong>'+fmt(x.buckets.length)+'</strong></div></div><article class="pi-scope"><strong>Review before removing resources</strong><p>Route coverage: '+(route?fmt(route.zones_checked)+' / '+fmt(route.zones_total)+' zones · '+fmt(route.patterns)+' patterns':'Unavailable')+' · Schedule coverage: '+(schedule?fmt(schedule.workers_checked)+' / '+fmt(schedule.workers_total)+' Workers':'Unavailable')+' · checked '+esc(x.route_observed_at||'Unknown')+'</p><p>'+esc(x.scope)+' Review labels are based on names, not a finding of inactivity. No resource was deleted and costs are not inferred from resource counts.</p></article>'+attribution+'<form method="get" action="/operations/inventory" class="px-filter"><label>Find resource<input name="q" maxlength="120" value="'+esc(u.searchParams.get('q')||'')+'" placeholder="Worker, domain, dependency"></label><label class="px-check"><input type="checkbox" name="review" value="1" '+(review?'checked':'')+'> Review environments only</label><button type="submit">Filter</button></form><div class="section">Workers · '+workers.length+'</div><div class="pi-grid">'+(cards||'<p>No matching Workers.</p>')+'</div><div class="pi-grid"><article><h2>Databases · '+dbs.length+'</h2>'+list(dbs,true)+'</article><article><h2>Object storage · '+buckets.length+'</h2>'+list(buckets)+'</article></div><p class="px-note">Snapshot is manually refreshed by authorized management tooling. No provider credentials are stored in this inventory.</p>';return response(page('Operations · infrastructure inventory',body).replace('</style>',PX_CSS+PI_CSS+'</style>'),200,'text/html;charset=utf-8')}

const PI_CSS=".pi-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:12px 0}.pi-card h3{font-size:15px;overflow-wrap:anywhere}.pi-card p,.pi-card summary{font-size:12px;overflow-wrap:anywhere}.pi-card summary{cursor:pointer;font-weight:650}.pi-meta{display:flex;gap:8px 12px;flex-wrap:wrap;color:#656b74;font-size:11px}.pi-dep{display:flex;justify-content:space-between;align-items:flex-start;gap:8px;padding:9px 0;border-bottom:1px solid #edf0f2;font-size:12px;overflow-wrap:anywhere}.pi-dep>*{min-width:0}.pi-dep b{text-align:right}.pi-dep small{display:block;font-size:11px;color:#656b74}.pi-scope p{font-size:12px;margin:5px 0 0}.pi-card .px-head small{white-space:normal}@media(max-width:760px){.pi-grid{grid-template-columns:minmax(0,1fr)}.pi-dep{flex-wrap:wrap}}";
const PX_CATEGORIES=['Hosting','Domain','AI','Software','Email','Marketing','Other'],PX_CADENCES=['Monthly','Annual','One-time'],PX_STATES=['Active','Review','Ended'];
const pxMoney=n=>typeof n==='number'&&Number.isFinite(n)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100):'—';
function pxWindow(){const now=new Date(),end=new Date(now.getTime()+30*86400000);return [now.toISOString().slice(0,10),end.toISOString().slice(0,10)]}
async function pxSummary(env,project=''){const [today,end]=pxWindow();const [totals,upcoming]=await Promise.all([safeFirst(env.PORTFOLIO,"SELECT COUNT(*) records,SUM(state<>'Ended') active,SUM(CASE WHEN state<>'Ended' AND cadence<>'One-time' AND amount_cents IS NOT NULL THEN CASE WHEN cadence='Annual' THEN amount_cents/12.0 ELSE amount_cents END ELSE 0 END) recurring_cents,SUM(state<>'Ended' AND cadence<>'One-time' AND amount_cents IS NOT NULL) known_recurring,SUM(state<>'Ended' AND cadence<>'One-time' AND amount_cents IS NULL) unknown_recurring,SUM(state<>'Ended' AND amount_cents IS NULL) unknown_amount,SUM(state<>'Ended' AND next_due='') unknown_due,SUM(state<>'Ended' AND next_due<>'' AND next_due<?) overdue,SUM(state<>'Ended' AND next_due BETWEEN ? AND ?) upcoming,SUM(CASE WHEN state<>'Ended' AND next_due BETWEEN ? AND ? THEN amount_cents END) upcoming_cents FROM portfolio_expenses WHERE (?='' OR project=?)",today,today,end,today,end,project,project),safeRows(env.PORTFOLIO,"SELECT id,project,vendor,service,amount_cents,next_due,state,cadence FROM portfolio_expenses WHERE state<>'Ended' AND next_due<>'' AND next_due<=? AND (?='' OR project=?) ORDER BY next_due,vendor LIMIT 8",end,project,project)]);return {totals,upcoming,today,end}}
function pxStatus(r,today){return r.state==='Ended'?'Ended':r.next_due&&r.next_due<today?'Overdue':r.state}
function pxKpis(x){const t=x.totals;if(!t||typeof t.records!=='number')return '<p class="warn">Expense data unavailable.</p>';const value=t.known_recurring?pxMoney(t.recurring_cents):'—';return '<div class="px-kpis"><div><small>Known recurring commitments / mo</small><strong>'+esc(value)+'</strong><small>'+esc(t.active?(t.unknown_recurring||0)+' recurring amounts unknown':'No active records yet')+'</small></div><div><small>Due in next 30 days</small><strong>'+esc(t.upcoming?pxMoney(t.upcoming_cents):t.active?'$0.00':'—')+'</strong><small>'+fmt(t.upcoming||0)+' scheduled records · known amounts only</small></div><div><small>Overdue / dates missing</small><strong>'+fmt(t.overdue||0)+' / '+fmt(t.unknown_due||0)+'</strong><small>Based on recorded renewal dates (UTC)</small></div></div>'}
function pxBrief(x){if(!x)return '';const rows=x.upcoming,t=x.totals;return '<article class="px-brief"><div class="px-head"><h3>'+execIcon('cost')+' Expenses &amp; renewals</h3><div class="px-actions"><a href="/operations/inventory">Infrastructure ↗</a><a href="/finance/expenses">Manage expenses ↗</a></div></div>'+pxKpis(x)+(rows===null?'<p class="warn">Renewal records unavailable.</p>':rows.length?rows.map(r=>'<a class="px-due" href="/finance/expenses?edit='+encodeURIComponent(r.id)+'"><span><strong>'+esc(r.vendor+' · '+r.service)+'</strong><small>'+esc(r.project)+' · '+esc(r.next_due)+(r.next_due<x.today?' · Overdue':'')+'</small></span><b>'+esc(pxMoney(r.amount_cents))+'</b></a>').join(''):'<p class="muted">'+esc(t?.active?'No recorded renewals due in the next 30 days.':'Add recurring services, subscriptions and domains to start tracking renewals.')+'</p>')+'<p class="px-note">Recorded commitments are forecasts, not paid bills. Actual profit still comes from monthly reconciliation.</p></article>'}
