// Native Stripe balance snapshots. No payment writes and no transaction detail persistence.
// Each named encrypted Chamber secret holds a restricted live key and the exact authorized account ID.
const STRIPE_SOURCES=[['apt','SiteAPT','PZ_STRIPE_APT_READ'],['hum','Humperdinck','PZ_STRIPE_HUM_READ'],['yarr','Yarr','PZ_STRIPE_YARR_READ'],['owl','Story Owl','PZ_STRIPE_OWL_READ']];
// SHA-256 pins of the four exact authorized live account identities, resolved via the Stripe connector. No account identifiers or credentials are persisted here.
const STRIPE_LEGACY_PINS={"apt":"cb27e63e9594bf6bf448a3469637123ce5f86dd44793f427760bbbbbff31dce9","hum":"fda1ab40009511b10488094adb028a291c78f825269cceaae1cee02fdb0cfebc","yarr":"eb8bf1f73477250892bb5562997a7a365aa64d9b204aa15ff8cc4807af9738ea","owl":"14954ebc8d17b6abbc6ce8dc3d817f1acba9e9cf978a91a960c736fd35f12770"};
const stripeChamberProject=spec=>spec[0]==='owl'?'The Story Owl':spec[1];
const stripeChamberSpec=name=>STRIPE_SOURCES.find(s=>s[2]===name);
// Existing owner entries may have been created under Shared systems before the reporting form was released.
const stripeChamberMatch=(row,spec)=>row?.kind==='stripe-key'&&(row.project===stripeChamberProject(spec)||row.project==='Shared systems');
async function stripeChamberConfigs(env){
 const key=await vaultKey(env,VAULT_WORKSPACE).catch(()=>null);
 if(!key)return STRIPE_SOURCES.map(()=>null);
 return Promise.all(STRIPE_SOURCES.map(async spec=>{
  try{
   const secret=await vaultUse(env,VAULT_WORKSPACE,key,spec[2],'Stripe sync','Read-only balance reporting',row=>stripeChamberMatch(row,spec));
   return secret?stripeConfig(secret.value)||stripeLegacyConfig(secret.value,spec):null;
  }catch{return null}
 }));
}
async function stripeChamberConfigured(env){
 if(!await vaultKey(env,VAULT_WORKSPACE).catch(()=>null))return 0;
 const rows=await safeRows(env.PORTFOLIO,"SELECT name,kind,project FROM vault_secrets WHERE workspace_id=? AND status='Active'",VAULT_WORKSPACE);
 return STRIPE_SOURCES.filter(s=>rows?.some(r=>r.name===s[2]&&stripeChamberMatch(r,s))).length;
}
const STRIPE_SNAPSHOT_SOURCE='Stripe live balance transactions · read-only connector';
const stripeCurrency=c=>typeof c==='string'&&/^[a-z]{3}$/.test(c)&&Intl.supportedValuesOf('currency').includes(c.toUpperCase());
const stripeType=t=>typeof t==='string'&&/^[a-z_]{1,80}$/.test(t);
const stripeInteger=Number.isSafeInteger;
const stripeIncomplete=([key,name])=>({key,name,complete:false,count:null,groups:[]});
function stripeConfig(value){try{const c=JSON.parse(value);if(typeof c?.account_id!=='string'||!/^acct_[A-Za-z0-9]+$/.test(c.account_id)||typeof c.api_key!=='string'||!/^rk_live_[A-Za-z0-9]+$/.test(c.api_key))return null;return {account_id:c.account_id,api_key:c.api_key}}catch{return null}}
// Earlier Chamber entries stored a live API key. Owner-authorized standard keys are allowed only in this legacy read path; verify the exact pinned identity before reading balance data.
function stripeLegacyConfig(value,spec){const k=typeof value==='string'?value.trim():'';return /^(?:rk|sk)_live_[A-Za-z0-9]+$/.test(k)&&STRIPE_LEGACY_PINS[spec[0]]?{account_hash:STRIPE_LEGACY_PINS[spec[0]],api_key:k}:null}
function stripeRanges(cutoff){
 const month=cutoff.toISOString().slice(0,7),start=new Date(month+'-01T00:00:00.000Z');
 const out=[{month,start:start.toISOString(),end:cutoff.toISOString()}];
 if(cutoff.getUTCDate()<=3){const prior=new Date(start);prior.setUTCMonth(prior.getUTCMonth()-1);out.unshift({month:prior.toISOString().slice(0,7),start:prior.toISOString(),end:start.toISOString()})}
 return out;
}
async function stripeGet(config,path,request){
 // Standard keys have broad powers; this reporting path permits only these two GET operations.
 if(path!=='account'&&!/^balance_transactions\?limit=100(?:&starting_after=[A-Za-z0-9_%+.-]+)?$/.test(path))throw Error('Stripe reporting endpoint not permitted');
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);
 try{
  let r;try{r=await request('https://api.stripe.com/v1/'+path,{method:'GET',headers:{Authorization:'Bearer '+config.api_key,'Stripe-Version':'2026-11-18.endive'},redirect:'error',signal:controller.signal})}catch{const error=new Error('Stripe transport unavailable');error.stripeReason=controller.signal.aborted?'timeout':'transport';throw error}
  if(!r.ok){const error=new Error('Stripe read unavailable');error.stripeStatus=r.status;throw error;}
  try{return await r.json()}catch{const error=new Error('Stripe response invalid');error.stripeReason=controller.signal.aborted?'timeout':'invalid_json';throw error}
 }finally{clearTimeout(timer)}
}
function stripeGroup(spec,rows,range){
 const groups=new Map(),start=Date.parse(range.start)/1000,end=Date.parse(range.end)/1000;let count=0;
 for(const r of rows){if(r.created<start||r.created>=end)continue;
  const type=r.reporting_category,currency=r.currency,k=currency+':'+type;
  const g=groups.get(k)||{currency,type,count:0,amount_cents:0,fee_cents:0,net_cents:0};
  g.count++;g.amount_cents+=r.amount;g.fee_cents+=r.fee;g.net_cents+=r.net;count++;
  if(![g.count,g.amount_cents,g.fee_cents,g.net_cents].every(stripeInteger))throw Error('Aggregate exceeds safe integer range');
  groups.set(k,g);
 }
 if(groups.size>100)throw Error('Too many reporting groups');
 return {key:spec[0],name:spec[1],complete:true,count,groups:[...groups.values()].sort((a,b)=>(a.currency+':'+a.type).localeCompare(b.currency+':'+b.type))};
}
async function stripeReadAccount(spec,config,ranges,request,report=()=>{}){
 const failed=(reason='invalid_response')=>{report(reason);return ranges.map(()=>stripeIncomplete(spec))};
 if(!config)return failed('credential_invalid');
 let stage='identity';
 try{
  const identity=await stripeGet(config,'account',request);
  if(typeof identity.id!=='string'||!/^acct_[A-Za-z0-9]+$/.test(identity.id)||(config.account_hash?await vaultSha(identity.id)!==config.account_hash:identity.id!==config.account_id)) return failed('account_mismatch');
  stage='balance';
  let cursor='',oldest=Infinity,exhausted=false;const seen=new Set(),rows=[];
  const yearStart=Date.parse(ranges[0].start)/1000;
  for(let page=0;page<5;page++){
   const q=new URLSearchParams({limit:'100'});if(cursor)q.set('starting_after',cursor);
   const x=await stripeGet(config,'balance_transactions?'+q,request);
   if(!Array.isArray(x.data)||x.data.length>100||typeof x.has_more!=='boolean'||(x.has_more&&!x.data.length))return failed();
   for(const r of x.data){
    if(!r||typeof r.id!=='string'||!r.id||seen.has(r.id)||!stripeInteger(r.created)||r.created<0||r.created>oldest||!stripeCurrency(r.currency)||!stripeType(r.reporting_category)||![r.amount,r.fee,r.net].every(stripeInteger)||r.amount-r.fee!==r.net)return failed();
    oldest=r.created;seen.add(r.id);
    rows.push({created:r.created,currency:r.currency,reporting_category:r.reporting_category,amount:r.amount,fee:r.fee,net:r.net});cursor=r.id;
   }
   exhausted=!x.has_more;if(exhausted||oldest<yearStart)break;
  }
  const results=ranges.map(r=>exhausted||oldest<Date.parse(r.start)/1000?stripeGroup(spec,rows,r):stripeIncomplete(spec));
  report(results.every(r=>r.complete)?'complete':'page_limit');return results;
 }catch(error){const code=error.stripeStatus,reason=[400,401,403,404,405,429].includes(code)?String(code):Number.isInteger(code)&&code>=500&&code<=599?'upstream':Number.isInteger(code)?'http_other':['transport','timeout','invalid_json'].includes(error.stripeReason)?error.stripeReason:'unavailable';return failed(stage+'_'+reason)}
}
function stripeSnapshotValid(x,month){
 if(x?.schema!==1||x.month!==month||x.source!==STRIPE_SNAPSHOT_SOURCE||!Array.isArray(x.accounts)||x.accounts.length!==4)return false;
 const start=Date.parse(month+'-01T00:00:00Z'),end=new Date(start);end.setUTCMonth(end.getUTCMonth()+1);
 if(Date.parse(x.range_start)!==start||!Number.isFinite(Date.parse(x.range_end))||Date.parse(x.range_end)<start||Date.parse(x.range_end)>end.getTime()||!Number.isFinite(Date.parse(x.observed_at))||Date.parse(x.observed_at)<Date.parse(x.range_end))return false;
 return STRIPE_SOURCES.every(([key,name])=>{
  const matches=x.accounts.filter(a=>a?.key===key);if(matches.length!==1)return false;
  const a=matches[0];if(a.name!==name||typeof a.complete!=='boolean'||!Array.isArray(a.groups)||a.groups.length>100)return false;
  if(!a.complete)return a.count===null&&a.groups.length===0;
  if(!stripeInteger(a.count)||a.count<0)return false;
  const seen=new Set();let count=0;
  for(const g of a.groups){if(!g||!stripeCurrency(g.currency)||!stripeType(g.type)||![g.count,g.amount_cents,g.fee_cents,g.net_cents].every(stripeInteger)||g.count<=0||g.amount_cents-g.fee_cents!==g.net_cents)return false;
   const k=g.currency+':'+g.type;if(seen.has(k))return false;seen.add(k);count+=g.count;
  }
  return stripeInteger(count)&&count===a.count;
 });
}
async function stripeWrite(bucket,snapshot){
 const month=snapshot.month,key='finance/stripe-balance-v1/'+month+'.json';
 if(!stripeSnapshotValid(snapshot,month))throw Error('Invalid snapshot');
 if(snapshot.accounts.every(a=>!a.complete))return 'unavailable';
 const current=await bucket.get(key);
 if(current){
  if(current.size>100000)throw Error('Existing snapshot too large');
  const old=await current.json();
  if(!stripeSnapshotValid(old,month))throw Error('Existing snapshot invalid');
  if(Date.parse(old.range_end)>=Date.parse(snapshot.range_end))return 'unchanged';
 }
 const body=JSON.stringify(snapshot);
 const saved=await bucket.put(key,body,{httpMetadata:{contentType:'application/json'},onlyIf:current?{etagMatches:current.etag}:{etagDoesNotMatch:'*'}});
 if(!saved)return 'conflict';
 const readback=await bucket.get(key);
 if(!readback||readback.size>100000)throw Error('Snapshot readback unavailable');
 const value=await readback.json();
 if(!stripeSnapshotValid(value,month)||JSON.stringify(value)!==body)throw Error('Snapshot readback mismatch');
 return snapshot.accounts.every(a=>a.complete)?'complete':'partial';
}
export async function stripeRefresh(env,cutoff=new Date(),request=fetch,loadConfigs=stripeChamberConfigs,diagnostics=[]){
 const ranges=stripeRanges(cutoff),configs=await loadConfigs(env);
 const ids=await Promise.all(configs.map(c=>c?(c.account_hash||vaultSha(c.account_id)):null));
 const accounts=await Promise.all(STRIPE_SOURCES.map((s,i)=>stripeReadAccount(s,configs[i]&&ids[i]&&ids.filter(id=>id===ids[i]).length===1?configs[i]:null,ranges,request,reason=>{diagnostics[i]=reason})));
 const outcomes=[];
 for(let i=0;i<ranges.length;i++){const r=ranges[i],snapshot={schema:1,month:r.month,observed_at:cutoff.toISOString(),range_start:r.start,range_end:r.end,source:STRIPE_SNAPSHOT_SOURCE,accounts:accounts.map(a=>a[i])};
  try{outcomes.push(await stripeWrite(env.BRAND_FILES,snapshot))}catch{outcomes.push('failed')}
 }
 return outcomes;
}
function stripeStatus(outcomes){return outcomes.includes('failed')||outcomes.includes('conflict')?'failed':outcomes.includes('unavailable')?'unavailable':outcomes.includes('partial')?'partial':outcomes.every(x=>x==='unchanged')?'unchanged':'complete'}
const stripeStatusMessages={complete:'Stripe balance snapshots refreshed and verified.',partial:'Stripe refreshed with partial coverage. Review each business below.',unavailable:'Stripe access unavailable for all accounts in at least one period. Existing snapshots were retained.',failed:'Stripe snapshot could not be safely written or verified. Review the current coverage and retry.',unchanged:'A snapshot with an equal or newer cutoff already exists.'};
const stripeDiagnosticLabels={credential_invalid:'Missing, malformed or duplicate live connection',account_mismatch:'Account identity did not match',identity_400:'Account identity request rejected (400)',identity_401:'Live key rejected (401)',identity_403:'Account identity read permission denied (403)',identity_429:'Account identity rate limited (429)',identity_404:'Account identity endpoint not found (404)',identity_405:'Account identity method unavailable (405)',identity_upstream:'Stripe account identity service returned 5xx',identity_http_other:'Unexpected account identity HTTP status',identity_transport:'Stripe account identity network request failed',identity_timeout:'Stripe account identity request timed out',identity_invalid_json:'Stripe account identity response was not valid JSON',identity_unavailable:'Account identity read unavailable',balance_400:'Balance request rejected (400)',balance_401:'Balance credential rejected (401)',balance_403:'Balance read permission denied (403)',balance_429:'Balance read rate limited (429)',balance_404:'Balance endpoint not found (404)',balance_405:'Balance method unavailable (405)',balance_upstream:'Stripe balance service returned 5xx',balance_http_other:'Unexpected balance HTTP status',balance_transport:'Stripe balance network request failed',balance_timeout:'Stripe balance request timed out',balance_invalid_json:'Stripe balance response was not valid JSON',balance_unavailable:'Balance read unavailable',invalid_response:'Invalid balance response',page_limit:'Page limit reached',complete:'Complete'};
async function stripeManual(req,env){if(!sameOriginPost(req))return response('Forbidden',403);let status='failed';const diagnostics=[];try{status=stripeStatus(await stripeRefresh(env,new Date(),fetch,stripeChamberConfigs,diagnostics))}catch{}const codes=STRIPE_SOURCES.map((_,i)=>Object.hasOwn(stripeDiagnosticLabels,diagnostics[i])?diagnostics[i]:'');return new Response(null,{status:303,headers:{...headers,Location:'/finance/sources?stripe_refresh='+status+(['complete','unchanged'].includes(status)?'':'&stripe_diagnostics='+encodeURIComponent(codes.join(',')))}})}
async function stripeScheduled(env){const status=stripeStatus(await stripeRefresh(env));if(!['complete','unchanged'].includes(status))console.warn('Stripe balance snapshot: '+status)}
async function afStripeRead(env,month){try{const obj=await env.BRAND_FILES.get('finance/stripe-balance-v1/'+month+'.json');if(!obj||obj.size>100000)return null;const x=await obj.json();return stripeSnapshotValid(x,month)?x:null}catch{return null}}
function afStripeMoney(n,c){return c==='usd'?pxMoney(n):fmt(n)+' minor units '+c.toUpperCase()}
function afStripePanel(x,key=null){if(!x)return '<p class="af-note">Direct Stripe balance snapshot not available yet.</p>';const age=Date.now()-Date.parse(x.range_end),stale=age>36*3600000||age<0,accounts=key?x.accounts.filter(a=>a.key===key):x.accounts;if(!accounts.length)return '';return '<section class="af-stripe"><div class="px-head"><h3>Direct Stripe balance coverage</h3><small>'+esc(stale?'Stale · review required':'Live-mode read · snapshot')+'</small></div><p class="af-note">UTC period '+esc(x.range_start)+' to '+esc(x.range_end)+' · observed '+esc(x.observed_at)+'. Direct provider records are shown separately, never added to local ledger totals.</p>'+accounts.map(a=>'<div class="af-source"><div><strong>'+esc(a.name)+'</strong><small>'+esc(a.complete?'Period covered':'Incomplete / unavailable')+'</small></div><div><strong>'+fmt(a.count)+'</strong><small>Balance transactions</small></div>'+(!a.complete?'<p>Not eligible for financial totals until the complete period is retrieved.</p>':a.count===0?'<p>No balance transactions found in the checked period. This is not proof of zero total business revenue or costs.</p>':a.groups.length?'<div class="af-groups">'+a.groups.map(g=>'<div><strong>'+esc(g.type.replaceAll('_',' '))+' · '+esc(g.currency.toUpperCase())+'</strong><small>'+fmt(g.count)+' transactions · amount '+esc(afStripeMoney(g.amount_cents,g.currency))+' · fee '+esc(afStripeMoney(g.fee_cents,g.currency))+' · net '+esc(afStripeMoney(g.net_cents,g.currency))+'</small></div>').join('')+'</div>':'<p>Transaction amounts unavailable.</p>')+'</div>').join('')+'<p class="af-note">Balance activity includes transfers, payouts and adjustments; these are not sales or operating profit. Tax treatment, off-platform revenue and actual business expenses require reconciliation.</p></section>'}

function afMonth(month){const [y,m]=month.split('-').map(Number);const start=new Date(Date.UTC(y,m-1,1)),end=new Date(Date.UTC(y,m,1));return {start:start.toISOString(),end:end.toISOString(),startSec:Math.floor(start.getTime()/1000),endSec:Math.floor(end.getTime()/1000)}}
function afAmount(rows,predicate){if(rows===null)return null;const picked=rows.filter(predicate);return picked.some(r=>typeof r.cents!=='number'||!Number.isFinite(r.cents))?null:picked.reduce((n,r)=>n+r.cents,0)}
function afBuild(month,apt,hum,legacy,yarr,grim,usage,expenses){const usd=r=>String(r.currency||'').toLowerCase()==='usd';const aptGross=afAmount(apt,r=>usd(r)&&r.kind==='invoice'),aptRefund=afAmount(apt,r=>usd(r)&&r.kind==='refund'),humGross=afAmount(hum,usd);const num=(r)=>r===null?null:r.reduce((n,x)=>n+Number(x.n||0),0);const nonusd=r=>r===null?null:r.filter(x=>!usd(x)).reduce((n,x)=>n+Number(x.n||0),0);const lines=[{key:'apt',name:'SiteAPT',provider:'Stripe · local live invoice/refund ledger',receipts:aptGross,refunds:aptRefund,count:num(apt),otherCurrency:nonusd(apt),note:apt===null?'Source unavailable.':'Invoice paid amounts and refund events in this UTC month. Taxes, fees, chargebacks and provider completeness are not established.'},{key:'hum',name:'Humperdinck',provider:'Stripe · live checkout orders',receipts:humGross,refunds:null,count:num(hum),otherCurrency:nonusd(hum),note:hum===null?'Source unavailable.':'Gross originally paid orders dated this month. Refund/dispute amounts and dates unavailable; other provider orders are excluded to avoid duplicates.'},{key:'yarr',name:'Yarr',provider:'Stripe · purchase records',receipts:null,refunds:null,count:yarr?.n??null,otherCurrency:null,note:yarr===null?'Source unavailable.':'Current live-prefix purchase records are available, but archive creation dates are not verified payment timestamps; excluded from monthly amounts.'},{key:'grim',name:'Grim Thread',provider:'Shopify · rolling sales snapshot',receipts:null,refunds:null,count:grim?.orders??null,otherCurrency:null,note:grim?.checked_at?'Rolling snapshot '+grim.since_at+' to '+grim.checked_at+' · '+(grim.complete?'source reports complete':'coverage incomplete')+' · '+(typeof grim.subtotal==='number'?'recorded subtotal '+grim.subtotal+' (source units)':'subtotal unavailable')+'. Not a reconciled calendar month; excluded.':'Snapshot unavailable.'},{key:'owl',name:'Story Owl',provider:'Membership / payment events',receipts:null,refunds:null,count:null,otherCurrency:null,note:'No verified monthly payment-amount ledger connected.'},{key:'pz',name:'Project Zero',provider:'Commercial billing disabled',receipts:null,refunds:null,count:null,otherCurrency:null,note:'No live billing or affiliate ledger connected.'}];const known=lines.filter(r=>r.receipts!==null),total=known.length?known.reduce((n,r)=>n+r.receipts,0):null;const t=expenses?.totals;return {schema:1,month,observed_at:new Date().toISOString(),lines,recordedGross:total,sourceCount:known.length,legacyCount:num(legacy),usageObserved:usage?.updated||null,commitments:t?.known_recurring?t.recurring_cents:null,unknownCommitments:t?.unknown_recurring??null}}
async function afRead(env,month=new Date().toISOString().slice(0,7),expenses){const b=afMonth(month);const [apt,hum,legacy,yarr,grim,usage,commitments]=await Promise.all([safeRows(env.APT,"SELECT kind,currency,COUNT(*) n,SUM(amount_cents) cents FROM billing_payments WHERE livemode=1 AND julianday(occurred_at)>=julianday(?) AND julianday(occurred_at)<julianday(?) GROUP BY kind,currency",b.start,b.end),safeRows(env.HUM,"SELECT status,currency,COUNT(*) n,SUM(amount_cents) cents FROM commerce_stripe_live_orders WHERE paid_at>=? AND paid_at<? GROUP BY status,currency",b.startSec,b.endSec),safeRows(env.HUM,"SELECT status,currency,COUNT(*) n,SUM(amount_cents) cents FROM commerce_live_orders GROUP BY status,currency"),safeFirst(env.YARR,"SELECT COUNT(*) n FROM (SELECT id AS session FROM stripe_checkout_sessions WHERE substr(id,1,8)='cs_live_' AND status IN ('paid','refunded','disputed') UNION SELECT checkout_session_id AS session FROM stripe_purchase_archive WHERE substr(checkout_session_id,1,8)='cs_live_' AND status IN ('paid','refunded','disputed'))"),safeFirst(env.GRIM,"SELECT checked_at,since_at,status,json_extract(details_json,'$.orderCount') orders,json_extract(details_json,'$.subtotal') subtotal,json_extract(details_json,'$.complete') complete FROM grim_sales_snapshot WHERE json_valid(details_json) ORDER BY checked_at DESC LIMIT 1"),loadSnapshot(env,'analytics/cloudflare-usage-v1.json').catch(()=>null),expenses===undefined?pxSummary(env):expenses]);const result=afBuild(month,apt,hum,legacy,yarr,grim,usage,commitments);result.stripe=await afStripeRead(env,month);return result}
async function afStore(env){const x=await afRead(env);await env.BRAND_FILES.put('finance/source-coverage/'+x.month+'.json',JSON.stringify(x),{httpMetadata:{contentType:'application/json'}})}
function afSourceLine(r){return '<div class="af-source"><div><strong>'+esc(r.name)+'</strong><small>'+esc(r.provider)+'</small></div><div><strong>'+esc(pxMoney(r.receipts))+'</strong><small>'+ (r.receipts===null?'Monthly receipts unavailable':'Recorded gross USD')+'</small></div><p>'+esc(r.note)+(r.otherCurrency?' '+fmt(r.otherCurrency)+' non-USD records excluded.':'')+'</p></div>'}
function afPanel(x){if(!x)return '<article class="af-panel"><p class="warn">Automatic source reporting unavailable.</p></article>';return '<article class="af-panel"><div class="px-head"><h3>'+execIcon('revenue')+' Financial sources · '+esc(x.month)+'</h3><a href="/finance/sources">View sources &amp; missing data ↗</a></div><div class="af-summary"><div><small>Recorded gross receipts</small><strong>'+esc(pxMoney(x.recordedGross))+'</strong><small>'+fmt(x.sourceCount)+' local month-dated ledgers · not total portfolio revenue</small></div><div><small>Known recurring commitments / mo</small><strong>'+esc(pxMoney(x.commitments))+'</strong><small>Forecast only · '+(x.unknownCommitments==null?'coverage unknown':fmt(x.unknownCommitments)+' amounts unknown')+'</small></div><div><small>Verified operating profit</small><strong>See scorecard</strong><small>Requires actual costs, fees and refunds</small></div></div><p class="af-note">'+(x.stripe?esc(x.stripe.accounts.filter(a=>a.complete).length)+' / 4 direct Stripe accounts checked through '+esc(x.stripe.range_end.slice(0,10))+' UTC. ':'Direct Stripe snapshot unavailable. ')+'Live aggregate read '+esc(x.observed_at.replace('T',' ').slice(0,19))+' UTC. Excludes test records and unverified currency/periods. A zero is a zero in the queried ledger, not proof of zero business revenue.</p></article>'}
function afLifecycle(x,key){if(!x||!key)return '';const r=x.lines.find(r=>r.key===key);return r?lcWBlock('chart','Automatic payment source',afSourceLine(r)+afStripePanel(x.stripe,key)+'<p class="lc-note">Recorded gross receipts are not reconciled net revenue or profit.</p><a href="/finance/sources">Review all sources ↗</a>'):''}
async function afPage(env,url){const x=await afRead(env),catalog=await lbFinanceCatalog(env);const reports=await safeRows(env.PORTFOLIO,'SELECT project,month,revenue_cents,refund_cents,fees_cents,hosting_cents,other_cents FROM monthly_finance WHERE month=?',x.month);let snapshot=null;try{const obj=await env.BRAND_FILES.get('finance/source-coverage/'+x.month+'.json');if(obj&&obj.size<150000)snapshot=await obj.json()}catch{}const status=reports===null||!catalog?'Reconciliation unavailable':reports.filter(r=>catalog.some(([k])=>k===r.project)).length+' / '+catalog.length+' projects reconciled';const syncStatus=stripeStatusMessages[url?.searchParams.get('stripe_refresh')],diagnosticCodes=(url?.searchParams.get('stripe_diagnostics')||'').split(','),diagnosticText=diagnosticCodes.length===4?STRIPE_SOURCES.map((spec,i)=>Object.hasOwn(stripeDiagnosticLabels,diagnosticCodes[i])?spec[1]+': '+stripeDiagnosticLabels[diagnosticCodes[i]]:'').filter(Boolean).join(' · '):'';const configured=await stripeChamberConfigured(env);const syncControls='<article><div class="px-head"><h2>Stripe balance sync</h2><form method="post" action="/finance/sources/stripe-refresh"><button type="submit">Refresh now</button></form></div><p class="af-note">'+configured+' / 4 native read-only connections configured · hourly refresh (UTC). '+(configured<4?'Missing live credentials in the Chamber of Secrets: previous snapshots may come from the connector fallback. ':'')+'<a href="/secrets#ch-stripe">Manage Stripe connections</a> · Last snapshot: '+esc(x.stripe?.observed_at||'Not recorded yet')+'.</p>'+(typeof syncStatus==='string'?'<p role="status">'+esc(syncStatus)+'</p>':'')+(diagnosticText?'<p class="muted">'+esc(diagnosticText)+'</p>':'')+'</article>';const body=afPanel(x)+syncControls+'<article><div class="px-head"><h2>Per-business source coverage</h2><a href="/finance/reconcile?month='+esc(x.month)+'">Open reconciliation ↗</a></div>'+x.lines.map(afSourceLine).join('')+afStripePanel(x.stripe)+'<p class="af-note">'+esc(status)+'. '+(x.legacyCount===null?'Legacy order source unavailable.':fmt(x.legacyCount)+' legacy Humperdinck orders (all-time) excluded from automatic totals until provider overlap and period are verified.')+'</p></article><article><h2>Expenses &amp; fees</h2><div class="af-source"><div><strong>Cloudflare usage</strong><small>Usage telemetry, not invoices</small></div><div><strong>'+esc(x.usageObserved?'Snapshot available':'Unavailable')+'</strong><small>'+esc(x.usageObserved||'')+'</small></div><p>Account usage is not an actual project bill. Review measured usage and reconcile the invoice and shared allocation. <a href="/usage">Usage</a> · <a href="/operations/inventory">Inventory</a></p></div><div class="af-source"><div><strong>Processor fees &amp; refunds</strong><small>Incomplete</small></div><p>SiteAPT records refund events, but processor balance transaction fees, taxes, adjustments and other businesses’ refund amounts are not available in this monthly aggregation. Provider-level read-only feeds are needed.</p></div><div class="af-source"><div><strong>Printify &amp; other costs</strong><small>Not connected to monthly actuals</small></div><p>Fulfillment, shipping, Shopify invoices, domain charges and shared expenses require confirmed records. <a href="/finance/expenses">Manage commitments</a>.</p></div></article><p class="af-note">The overview queries live sources when opened. A private source-coverage snapshot is scheduled on the existing six-hour refresh cadence; latest stored snapshot: '+esc(snapshot?.observed_at||'Not recorded yet')+'. It is not a reconciled accounting report.</p>';return response(page('Finance · automatic source reporting',body).replace('</style>',AF_CSS+AF_EXTRA_CSS+PX_CSS+'</style>'),200,'text/html;charset=utf-8')}

const AF_EXTRA_CSS=".af-stripe{margin:12px 0}.af-groups{grid-column:1/-1;text-align:left!important;display:grid;gap:6px}.af-groups>div{background:#f7f8fa;border-radius:6px;padding:8px;overflow-wrap:anywhere}.af-stripe .px-head h3{font-size:15px}";const AF_CSS=".af-panel{margin:0 0 14px}.af-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:8px 0}.af-summary>div{background:#f7f8fa;border:1px solid #dfe2e6;border-radius:8px;padding:10px;min-width:0}.af-summary small,.af-source small{display:block;font-size:11px;color:#555b64}.af-summary strong{display:block;font-size:21px;letter-spacing:-.035em;margin:3px 0;overflow-wrap:anywhere}.af-note{font-size:12px;color:#656b74;margin:8px 0 0}.af-source{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:5px 12px;padding:11px 0;border-bottom:1px solid #edf0f2}.af-source>div{min-width:0;overflow-wrap:anywhere}.af-source>div:nth-child(2){text-align:right}.af-source p{grid-column:1/-1;margin:0;font-size:12px;color:#555b64;overflow-wrap:anywhere}.af-source:last-child{border-bottom:0}@media(max-width:760px){.af-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.af-summary>div:last-child{grid-column:1/-1}.af-summary strong{font-size:19px}}";

async function ebRead(env){const now=new Date(),cutoff=new Date(now.getTime()-86400000).toISOString(),today=now.toISOString().slice(0,10),end=new Date(now.getTime()+7*86400000).toISOString().slice(0,10);const [activity,changes,actions,review,priority,schedules,counts]=await Promise.all([
safeRows(env.TRACKER,"SELECT h.actor,COUNT(*) updates,COUNT(DISTINCT h.task_id) tasks,COUNT(DISTINCT CASE WHEN json_extract(h.before_json,'$.status')<>'Done' AND json_extract(h.after_json,'$.status')='Done' AND t.status='Done' THEN h.task_id END) completed,MAX(h.changed_at) latest FROM tracker_history h JOIN tracker_active_tasks t ON t.task_id=h.task_id WHERE julianday(h.changed_at)>=julianday(?) GROUP BY h.actor ORDER BY updates DESC,h.actor LIMIT 10",cutoff),
safeRows(env.TRACKER,"SELECT t.task_id,t.project,t.task,t.priority,t.status,h.actor,h.changed_at,json_extract(h.before_json,'$.status') previous_status,json_extract(h.after_json,'$.status') new_status FROM tracker_history h JOIN tracker_active_tasks t ON t.task_id=h.task_id WHERE julianday(h.changed_at)>=julianday(?) AND json_extract(h.before_json,'$.status')<>json_extract(h.after_json,'$.status') ORDER BY h.id DESC LIMIT 12",cutoff),
safeRows(env.TRACKER,"SELECT t.task_id,t.project,t.task,t.priority,t.status FROM tracker_owner_actions a JOIN tracker_active_tasks t ON t.task_id=a.task_id WHERE a.action_status='Needed' AND t.status NOT IN ('Done','Deferred') ORDER BY CASE t.priority WHEN 'P0' THEN 0 WHEN 'P1' THEN 1 WHEN 'P2' THEN 2 ELSE 3 END,CASE WHEN t.status='Blocked' THEN 0 ELSE 1 END,t.task_id LIMIT 6"),
safeRows(env.TRACKER,"SELECT p.id,p.name,g.decision,g.review_due FROM lifecycle_business_goals g JOIN lifecycle_projects p ON p.id=g.lifecycle_id WHERE g.review_due<>'' AND g.review_due<=? AND (p.tracker_project IS NULL OR p.tracker_project IN (SELECT project FROM tracker_active_projects)) ORDER BY g.review_due,p.name LIMIT 6",end),
safeRows(env.TRACKER,"SELECT t.task_id,t.project,t.task,t.priority,t.status,t.owner FROM tracker_active_tasks t WHERE t.status IN ('Not started','Needs verification','Ready to verify','In progress') AND NOT EXISTS (SELECT 1 FROM tracker_owner_actions a WHERE a.task_id=t.task_id AND a.action_status='Needed') ORDER BY CASE t.priority WHEN 'P0' THEN 0 WHEN 'P1' THEN 1 WHEN 'P2' THEN 2 ELSE 3 END,CASE t.status WHEN 'Ready to verify' THEN 0 WHEN 'In progress' THEN 1 WHEN 'Needs verification' THEN 2 ELSE 3 END,t.project,t.task_id LIMIT 6"),
safeRows(env.TRACKER,"SELECT title,cadence,enabled,observed_at FROM lifecycle_schedule_observations ORDER BY title LIMIT 12"),safeFirst(env.TRACKER,"SELECT COUNT(*) updates,COUNT(DISTINCT CASE WHEN json_extract(h.before_json,'$.status')<>'Done' AND json_extract(h.after_json,'$.status')='Done' AND t.status='Done' THEN h.task_id END) completed FROM tracker_history h JOIN tracker_active_tasks t ON t.task_id=h.task_id WHERE julianday(h.changed_at)>=julianday(?)",cutoff)]);return {now:now.toISOString(),cutoff,today,end,activity,changes,actions,review,priority,schedules,counts}}
function ebTask(r,detail){return '<a class="eb-line" href="/development?q='+encodeURIComponent(r.task_id)+'"><span><small>'+esc(r.project)+' · '+esc(r.task_id)+' · '+esc(r.priority)+'</small><strong>'+esc(r.task)+'</strong><small>'+esc(detail)+'</small></span><span class="eb-arrow" aria-hidden="true">›</span></a>'}
function ebList(rows,render,empty){return rows===null?'<p class="warn">Source unavailable.</p>':rows.length?rows.map(render).join(''):'<p class="muted">'+esc(empty)+'</p>'}
function ebCoverage(e){const catalog=e.financeCatalog,records=catalog&&e.finance?e.finance.filter(r=>catalog.some(([k])=>k===r.project)):null;const n=records?.length,all=catalog?.length;const stripe=e.automatic?.stripe;const age=stripe?Date.now()-Date.parse(stripe.range_end):NaN;const exp=e.expenses?.totals;return '<div class="eb-coverage"><a href="/finance/reconcile"><strong>'+esc(n==null?'—':n+' / '+all)+'</strong><small>Projects reconciled · '+esc(e.month)+'</small></a><a href="/finance/sources"><strong>'+esc(stripe?stripe.accounts.filter(a=>a.complete).length+' / 4':'—')+'</strong><small>Stripe accounts · '+esc(!stripe?'No snapshot':!Number.isFinite(age)||age<0||age>36*3600000?'Stale snapshot':'Snapshot '+stripe.range_end.slice(0,10)+' UTC')+'</small></a><a href="/finance/expenses"><strong>'+fmt(exp?.overdue??(exp?.records===0?0:null))+'</strong><small>Recorded overdue bills</small></a></div>'}
function ebPanel(e,full=false){const b=e.briefing;if(!b)return '<article><p class="warn">Briefing unavailable.</p></article>';const activity=b.activity,updates=b.counts?.updates;const actionCount=e.actions?.n;const review=b.review;const taskCount=b.counts?.completed;const top='<div class="eb-head"><div><h3>'+execIcon('owner')+' Daily briefing</h3><small>Rolling 24 hours · updated '+esc(b.now.slice(11,16))+' UTC</small></div><a href="'+(full?'/':'/briefing')+'">'+(full?'Executive overview':'Full briefing')+' ↗</a></div><div class="eb-kpis"><div><small>Recorded updates</small><strong>'+fmt(updates)+'</strong></div><div><small>Tasks moved to Done</small><strong>'+fmt(taskCount)+'</strong></div><div><small>Owner actions needed</small><strong>'+fmt(actionCount)+'</strong></div></div>'+ebCoverage(e);
const actions='<section><div class="eb-head"><h4>Needs your attention</h4><a href="/development/notes">All owner actions ↗</a></div>'+ebList(full?b.actions:b.actions?.slice(0,3)??null,r=>ebTask(r,r.status),'No open owner actions recorded.')+'</section>';
const work='<section><div class="eb-head"><h4>Development queue</h4><a href="/development?priority=P0">All critical work ↗</a></div>'+ebList(b.priority,r=>ebTask(r,r.status+' · '+r.owner),'No matching open tasks.')+'<p class="eb-note">Ordered by priority and status. Check dependencies and assignments before starting; this is not an automated assignment.</p></section>';
const recent='<section><div class="eb-head"><h4>Recent status changes</h4><a href="/development/history">Full history ↗</a></div>'+ebList(full?b.changes:b.changes?.slice(0,3)??null,r=>ebTask(r,r.previous_status+' → '+r.new_status+' · '+r.actor+' · '+r.changed_at+' UTC'),'No recorded status changes in the last 24 hours.')+'</section>';
const assistant='<section><div class="eb-head"><h4>Reported assistant &amp; owner activity</h4><a href="/assistants">Assistant activity ↗</a></div>'+ebList(activity,r=>'<div class="eb-line"><span><strong>'+esc(r.actor)+'</strong><small>'+fmt(r.tasks)+' distinct tasks touched · '+fmt(r.completed)+' reported Done transitions* · last '+esc(r.latest)+' UTC</small></span><b>'+fmt(r.updates)+'</b></div>','No tracker edits in the last 24 hours.')+'<p class="eb-note">*Per-actor distinct tasks changed to Done and still Done. The same task may appear for multiple actors. These are recorded tracker actions, not verified deployment events or live assistant presence.</p></section>';
const reviews='<section><h4>Business reviews due within 7 days</h4>'+ebList(review,r=>'<a class="eb-line" href="/lifecycle?id='+encodeURIComponent(r.id)+'&amp;step=operate"><span><strong>'+esc(r.name)+'</strong><small>'+esc(r.decision)+' · '+esc(r.review_due)+(r.review_due<b.today?' · overdue':'')+'</small></span><span class="eb-arrow">›</span></a>','No recorded reviews due in the next seven days.')+'<a href="/lifecycle">Business lifecycle ↗</a></section>';
const schedule='<section><h4>Last observed assistant schedules</h4>'+ebList(b.schedules,r=>'<div class="eb-line"><span><strong>'+esc(r.title)+'</strong><small>'+esc(r.cadence)+' · observed '+esc(r.observed_at)+'</small></span><b>'+esc(r.enabled?'Enabled then':'Disabled then')+'</b></div>','No schedule observations saved.')+'<p class="eb-note">Saved observations only; not live execution or task health.</p></section>';
return '<article class="eb-brief">'+top+'<div class="eb-columns">'+(full?actions+work+recent+assistant+reviews+schedule:actions+recent)+'</div>'+(full?'':'<div class="eb-foot"><a href="/briefing">See development queue, assistant activity and business reviews ↗</a></div>')+'</article>'}
async function ebPage(env){const e=await executiveData(env);return response(page('Daily executive briefing',ebPanel(e,true)).replace('</style>',EB_CSS+'</style>'),200,'text/html;charset=utf-8')}

const EB_CSS=".eb-brief{margin:0 0 14px}.eb-head{display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap}.eb-head h3,.eb-head h4{margin:0}.eb-head h3{display:flex;gap:7px;align-items:center}.eb-head svg{width:18px;height:18px}.eb-head small,.eb-line small,.eb-kpis small,.eb-coverage small{display:block;color:#656b74;font-size:11px;overflow-wrap:anywhere}.eb-head a,.eb-foot a,.eb-columns section>a{font-size:12px}.eb-kpis,.eb-coverage{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:10px 0}.eb-kpis>div{background:#f7f8fa;border:1px solid #e2e4e8;border-radius:8px;padding:10px;min-width:0}.eb-kpis strong{font-size:24px;letter-spacing:-.04em;line-height:1.3}.eb-coverage a{padding:8px 9px;border:1px solid #e2e4e8;border-radius:7px;text-decoration:none;color:#191919;min-width:0}.eb-coverage strong{display:block;font-size:17px}.eb-columns{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 18px}.eb-columns section{min-width:0;border-top:1px solid #e2e4e8;padding:10px 0}.eb-columns h4{font-size:14px;margin:0 0 5px}.eb-line{display:flex;gap:8px;justify-content:space-between;align-items:center;padding:9px 0;border-bottom:1px solid #edf0f2;text-decoration:none;color:inherit;font-size:13px}.eb-line span:first-child{min-width:0;overflow-wrap:anywhere}.eb-line strong{display:block;line-height:1.35}.eb-line b{font-size:13px;white-space:nowrap}.eb-arrow{font-size:21px;color:#666}.eb-note{font-size:11px;color:#656b74;margin:8px 0}.eb-foot{margin-top:8px}@media(max-width:760px){.eb-columns{grid-template-columns:1fr}.eb-kpis,.eb-coverage{gap:5px}.eb-kpis>div,.eb-coverage a{padding:7px}.eb-kpis strong{font-size:20px}.eb-coverage strong{font-size:15px}}";

function investmentAdvice(p,plan,commit,actual,work,today){if(p.review_due&&p.review_due<today)return 'Business review overdue';if(p.budget_cents!==null&&((plan?.known>0&&plan.cents>p.budget_cents)||(commit?.known>0&&commit.cents>p.budget_cents)))return 'Review spending ceiling';if(p.decision==='Pause')return 'Review recorded pause decision';if(!p.tracker_project)return 'Validate demand and feasibility';if(work?.p0>0)return 'Resolve critical launch requirements';if(p.profit_cents===null||p.profit_cents===undefined||!actual)return 'Establish targets and reconcile actuals';if(actual.profit<p.profit_cents)return 'Review profit gap';return 'Review results before further investment'}
async function investmentRead(env,month){const [projects,plans,commits,actuals,work]=await Promise.all([safeRows(env.TRACKER,"SELECT p.id,p.name,p.tracker_project,p.budget_cents,g.revenue_cents,g.profit_cents,g.decision,g.review_due FROM lifecycle_projects p LEFT JOIN lifecycle_business_goals g ON g.lifecycle_id=p.id WHERE p.tracker_project IS NULL OR p.tracker_project IN (SELECT project FROM tracker_active_projects) ORDER BY p.name LIMIT 201"),safeRows(env.TRACKER,"SELECT lifecycle_id,COUNT(*) selected,COUNT(monthly_cents) known,SUM(monthly_cents) cents FROM lifecycle_platforms WHERE status NOT IN ('Not decided','Not needed') GROUP BY lifecycle_id"),safeRows(env.PORTFOLIO,"SELECT project,COUNT(*) records,COUNT(CASE WHEN cadence<>'One-time' THEN amount_cents END) known,SUM(CASE WHEN cadence<>'One-time' AND amount_cents IS NULL THEN 1 ELSE 0 END) unknown,SUM(CASE WHEN cadence='Annual' THEN amount_cents/12.0 WHEN cadence='Monthly' THEN amount_cents END) cents FROM portfolio_expenses WHERE state<>'Ended' GROUP BY project"),safeRows(env.PORTFOLIO,"SELECT project,month,revenue_cents,refund_cents,fees_cents,hosting_cents,other_cents FROM monthly_finance WHERE month=?",month),safeRows(env.TRACKER,"SELECT project,COUNT(*) total,SUM(status='Done') done,SUM(priority='P0' AND status NOT IN ('Done','Deferred')) p0,SUM(status='Blocked') blocked FROM tracker_active_tasks GROUP BY project")]);if(projects===null)return null;const today=new Date().toISOString().slice(0,10);const rows=projects.slice(0,200).map(p=>{const plan=plans===null?null:plans.find(r=>r.lifecycle_id===p.id)||{selected:0,known:0,cents:null},commit=commits===null||!p.tracker_project?null:commits.find(r=>r.project===p.tracker_project)||{records:0,known:0,unknown:0,cents:null},actual=actuals===null||!p.tracker_project?null:lbActual(actuals.find(r=>r.project===lbFinanceKey(p))),progress=work===null||!p.tracker_project?null:work.find(r=>r.project===p.tracker_project)||{total:0,done:0,p0:0,blocked:0};return {p,plan,commit,actual,progress,advice:investmentAdvice(p,plan,commit,actual,progress,today)}});return {rows,month,today,truncated:projects.length>200,unavailable:[plans===null?'platform plans':null,commits===null?'expense register':null,actuals===null?'monthly reports':null,work===null?'development tracker':null].filter(Boolean),shared:commits?.find(r=>r.project==='Shared systems')||null}}
function invMetric(label,value,note=''){return '<div><small>'+esc(label)+'</small><strong>'+esc(value)+'</strong>'+(note?'<small>'+esc(note)+'</small>':'')+'</div>'}
function investmentCard(r){const {p,plan,commit,actual,progress,advice}=r;const cost=commit?.known?commit.cents:null;const estimate=plan?.known?plan.cents:null;const delta=actual&&p.profit_cents!=null?pxMoney(actual.profit-p.profit_cents)+' vs target':'Target '+pxMoney(p.profit_cents);const pct=progress?.total?Math.round(progress.done*100/progress.total):null;return '<article class="iv-card"><div class="iv-head"><div class="iv-brand">'+lcLogo(p)+'<div><h3>'+esc(p.name)+'</h3><small>'+esc(p.tracker_project?'Tracker linked':'Idea / draft')+' · '+esc(p.decision||'Not reviewed')+'</small></div></div><a href="'+lcWUrl(p.id,'operate')+'">Review ↗</a></div><div class="iv-metrics">'+invMetric('Net revenue',pxMoney(actual?.revenue),'Target '+pxMoney(p.revenue_cents))+invMetric('Actual costs',pxMoney(actual?.expenses),'Reconciled month only')+invMetric('Operating profit',pxMoney(actual?.profit),delta)+invMetric('Monthly ceiling',pxMoney(p.budget_cents))+invMetric('Known platform estimate',pxMoney(estimate),plan?fmt(plan.selected-plan.known)+' amounts unknown':'Unavailable')+invMetric('Known recurring commitments',pxMoney(cost),commit?fmt(commit.unknown)+' amounts unknown':p.tracker_project?'Unavailable':'Draft')+'</div><div class="iv-progress"><span>Development</span><strong>'+esc(pct===null?'—':pct+'%')+'</strong></div><div class="iv-bar" aria-label="'+esc(pct===null?'No tracked tasks':pct+' percent complete')+'"><i style="width:'+String(pct??0)+'%"></i></div><div class="iv-meta"><span>'+fmt(progress?.p0)+' open P0</span><span>'+fmt(progress?.blocked)+' blocked</span><span>Review '+esc(p.review_due||'not set')+'</span></div><div class="iv-action"><small>Suggested review action</small><strong>'+esc(advice)+'</strong></div><div class="iv-links"><a href="'+lcWUrl(p.id,'brief')+'">Business plan</a><a href="'+lcWUrl(p.id,'operate')+'">Goals &amp; decision</a>'+(p.tracker_project?'<a href="/development?project='+encodeURIComponent(p.tracker_project)+'">Development</a><a href="/finance/expenses?project='+encodeURIComponent(p.tracker_project)+'">Expenses</a>':'')+'</div></article>'}
async function investmentPage(env,u){
const current=new Date().toISOString().slice(0,7),requested=u.searchParams.get("month"),month=isMonth(requested)&&requested>="2000-01"&&requested<=current?requested:current,x=await investmentRead(env,month);
if(!x)return response(page("Portfolio investment review",'<p class="warn">Project data unavailable.</p>'),503,'text/html;charset=utf-8');
const filter=['all','active','draft'].includes(u.searchParams.get('view'))?u.searchParams.get('view'):'all',rows=x.rows.filter(r=>filter==='active'?!!r.p.tracker_project:filter==='draft'?!r.p.tracker_project:true);
const active=x.rows.filter(r=>r.p.tracker_project),known=active.filter(r=>r.actual).length,goals=x.rows.filter(r=>r.p.profit_cents!=null&&r.p.revenue_cents!=null).length;
const url=(view,edit)=>'/investments?view='+encodeURIComponent(view)+'&amp;month='+esc(month)+(edit?'&amp;edit='+encodeURIComponent(edit)+'#iv-editor':'');
const queue=ivQueue(rows,x.today),selected=rows.find(r=>r.p.id===u.searchParams.get('edit'));
let editor='';
if(selected){const [g,history]=await Promise.all([safeFirst(env.TRACKER,'SELECT * FROM lifecycle_business_goals WHERE lifecycle_id=?',selected.p.id),safeRows(env.TRACKER,'SELECT revision,decision,evidence,revenue_cents,profit_cents,review_due,recorded_at FROM lifecycle_business_decisions WHERE lifecycle_id=? ORDER BY revision DESC LIMIT 30',selected.p.id)]);
editor='<article id="iv-editor"><div class="iv-head"><h3>'+esc(selected.p.name)+' · Goals &amp; decision</h3><a href="'+url(filter)+'">Close</a></div>'+lbGoalForm(selected.p,{goals:g}).replace('class="mailform lc-form">','class="mailform lc-form"><input type="hidden" name="return_to" value="investments"><input type="hidden" name="return_month" value="'+esc(month)+'"><input type="hidden" name="return_view" value="'+esc(filter)+'">')+lbDecisionHistory({history})+'</article>';}
const reviewQueue='<article class="iv-queue"><div class="iv-head"><h3>Review queue</h3><small>Rule-based · not an investment ranking</small></div>'+queue.filter(x=>x.q.rank<6).map(({r,q})=>'<a class="iv-queue-row" href="'+url(filter,r.p.id)+'"><strong>'+esc(r.p.name)+'</strong><span>'+esc(q.label)+'<small>'+esc(q.reason)+'</small></span></a>').join('')+(queue.every(x=>x.q.rank===6)?'<p class="muted">No review flags for this selection.</p>':'')+'</article>';
const body='<div class="iv-heading"><small>'+esc(month)+' · USD · live project records</small><a href="/lifecycle">Lifecycle ↗</a></div><form class="iv-month" method="get" action="/investments"><input type="hidden" name="view" value="'+filter+'"><label>Reporting month <input type="month" name="month" min="2000-01" max="'+esc(current)+'" value="'+esc(month)+'"></label><button class="button" type="submit">View month</button></form><div class="iv-metrics iv-summary">'+invMetric('Tracked businesses',fmt(active.length),fmt(x.rows.length-active.length)+' drafts')+invMetric('Reconciled results',known+' / '+active.length,'Actual revenue, fees and costs')+invMetric('Projects with both financial goals',goals+' / '+x.rows.length,'Owner-entered targets')+'</div><div class="iv-tabs">'+[['all','All projects'],['active','Active'],['draft','Drafts']].map(([k,label])=>'<a href="'+url(k)+'"'+(filter===k?' aria-current="page"':'')+'>'+label+'</a>').join('')+'<a href="/finance/profitability?month='+esc(month)+'">Financial reports ↗</a></div>'+(x.unavailable.length?'<p class="warn">Unavailable sources: '+esc(x.unavailable.join(', '))+'.</p>':'')+(x.truncated?'<p class="warn">Only the first 200 projects are shown.</p>':'')+reviewQueue+editor+'<div class="iv-grid">'+(queue.length?queue.map(({r,q})=>investmentCard({...r,advice:q.label}).replace('Goals &amp; decision</a>','Goals &amp; decision</a><a href="'+url(filter,r.p.id)+'">Edit here</a>')).join(''):'<article>No matching projects.</article>')+'</div><p class="iv-note">Financial actuals reflect the selected month; goals, budget, commitments, development and decisions reflect current records. The queue is a review order, not a profitability ranking or authorization. Forecasts are separate from actual costs. Missing figures are not zero. Shared commitments: '+esc(x.shared?.known?pxMoney(x.shared.cents)+'/month known':'not recorded or unavailable')+'. Development completion is not commercial readiness. Review demand, risks, owner labor and actuals before spending.</p>';
return response(page('Portfolio investment review',body).replace('</head>','<style>'+IV_CSS+LB_CSS+LC_CSS+IV_REVIEW_CSS+'</style></head>').replace('</body>',(u.searchParams.get('notice')==='review-saved'?portfolioToast('Business goals and decision saved.'):'')+'</body>'),200,'text/html;charset=utf-8');
}

const IV_CSS=".iv-heading,.iv-head,.iv-progress{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.iv-heading h2,.iv-head h3{margin:0}.iv-heading small,.iv-head small,.iv-metrics small,.iv-action small{display:block;color:#656b74;font-size:12px}.iv-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.iv-card{min-width:0;padding:14px}.iv-brand{display:flex;gap:10px;align-items:center;min-width:0}.iv-brand>div{min-width:0;overflow-wrap:anywhere}.iv-brand img,.iv-brand .project-logo{width:32px;height:32px;object-fit:contain}.iv-head h3{font-size:16px}.iv-head a,.iv-links a{font-size:12px}.iv-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin:12px 0}.iv-metrics>div{min-width:0;padding:9px;border:1px solid #e2e4e8;background:#f7f8fa;border-radius:8px}.iv-metrics strong{display:block;font-size:21px;font-variant-numeric:tabular-nums;letter-spacing:-.035em;overflow-wrap:anywhere}.iv-progress{font-size:12px}.iv-bar{height:8px;background:#e3e5e8;border-radius:8px;overflow:hidden;margin:6px 0}.iv-bar i{height:100%;display:block;background:#52657e}.iv-meta,.iv-links,.iv-tabs{display:flex;gap:8px 14px;flex-wrap:wrap;font-size:12px}.iv-meta{color:#656b74}.iv-action{margin:10px 0;padding:10px;border-left:3px solid #52657e;background:#f7f8fa}.iv-action strong{display:block;font-size:14px}.iv-tabs{margin:12px 0}.iv-tabs a{padding:8px 12px;border:1px solid #ddd;border-radius:8px;text-decoration:none;color:inherit}.iv-tabs a[aria-current]{background:#191919;color:white}.iv-note{color:#656b74;font-size:12px}@media(max-width:760px){.iv-grid{grid-template-columns:1fr}.iv-metrics strong{font-size:18px}.iv-metrics>div{padding:7px}.iv-metrics small{font-size:11px}}";

const IG_PROJECTS=[['Grim Thread','grim'],['Humperdinck','hum'],['Project Zero','pz'],['SiteAPT','apt'],['Story Owl','owl'],['Yarr','yarr']];
function igTime(s){if(typeof s!=='string'||!s)return NaN;return Date.parse(/^\d{4}-\d\d-\d\d \d\d:\d\d:\d\d$/.test(s)?s.replace(' ','T')+'Z':s)}
function igFresh(s,hours,now=Date.now()){const t=igTime(s);return !Number.isFinite(t)||t>now+300000?'Unavailable':now-t>hours*3600000?'Stale':'Current'}
async function igRead(env){const now=new Date(),month=now.toISOString().slice(0,7);const [stripe,usage,storage,inventory,projects,repos,sites,shop,print,docs,health,plans]=await Promise.all([
afStripeRead(env,month),loadSnapshot(env,'analytics/cloudflare-usage-v1.json'),loadSnapshot(env,'analytics/cloudflare-r2-storage-v1.json'),piRead(env),
safeRows(env.TRACKER,"SELECT p.id,p.name,p.tracker_project,t.website,t.repository FROM lifecycle_projects p LEFT JOIN tracker_active_projects t ON t.project=p.tracker_project WHERE p.tracker_project IS NULL OR t.project IS NOT NULL ORDER BY p.name LIMIT 200"),
safeRows(env.TRACKER,"SELECT repository,observed_at FROM lifecycle_repo_catalog"),
safeRows(env.APT,"SELECT s.hostname,MAX(d.day) latest_day,MAX(d.updated_at) last_record,COUNT(d.day) days FROM sites s LEFT JOIN daily_site_stats d ON d.site_id=s.id WHERE s.hostname IN ('guides.projectzero.work','www.projectzero.work','projectzero.work','humperdinck.studio','www.humperdinck.studio','thegrimthread.com','www.thegrimthread.com','thestoryowl.com','www.thestoryowl.com','yarr.media','www.yarr.media','siteapt.app','www.siteapt.app') GROUP BY s.hostname"),
safeFirst(env.GRIM,"SELECT checked_at,status,json_extract(details_json,'$.complete') complete FROM grim_sales_snapshot ORDER BY checked_at DESC LIMIT 1"),
safeFirst(env.GRIM,"SELECT verified_at,matched_products FROM grim_printify_connection WHERE id=1"),
safeFirst(env.TRACKER,"SELECT COUNT(*) total,SUM(CASE WHEN s.synced_revision=t.revision THEN 1 ELSE 0 END) current,MAX(s.verified_at) last_verified FROM tracker_active_tasks t LEFT JOIN tracker_document_sync s ON s.task_id=t.task_id"),
safeFirst(env.APT,"SELECT last_watchdog_at,last_maintenance_at,integrity_mismatch_count FROM worker_health WHERE id=1"),
safeRows(env.TRACKER,"SELECT lifecycle_id,category,provider,status,updated_at FROM lifecycle_platforms WHERE status NOT IN ('Not decided','Not needed') ORDER BY category")]);
const rows=[],add=(project,provider,scope,state,checked,mode,permissions,note,href)=>rows.push({project,provider,scope,state,checked,mode,permissions,note,href});
const fresh=(stamp,h)=>igFresh(stamp,h,now.getTime());
add('Shared systems','Cloudflare','Worker / D1 / R2 usage',usage?fresh(usage.updated,24):'Unavailable',usage?.updated,'Native scheduled snapshot','Usage access observed; billing access unverified','Six-hour refresh target. Usage is not an invoice.','/usage');
add('Shared systems','Cloudflare','R2 storage telemetry',storage?fresh(storage.updated,24):'Unavailable',storage?.updated,'Native scheduled snapshot','Storage telemetry access observed when snapshot exists','Six-hour refresh target.','/usage');
add('Shared systems','Cloudflare','Infrastructure inventory',inventory?fresh(inventory.route_observed_at||inventory.observed_at,168):'Unavailable',inventory?.route_observed_at||inventory?.observed_at,'Saved API observation','Inventory metadata only; native refresh not configured','Proposed ownership and route/schedule coverage; not uptime.','/operations/inventory');
add('Shared systems','Cloudflare','Actual invoices and cost allocation','Not connected',null,'Manual reconciliation','Invoice access and allocation unverified','Measured usage does not establish actual operating cost.','/finance/reconcile');
add('Shared systems','Project Zero','Tracker document sync',docs===null?'Unavailable':fresh(docs.last_verified,1)==='Current'?(docs.current===docs.total?'Current':'Partial'):fresh(docs.last_verified,1),docs?.last_verified,'Native scheduled sync','Tracker D1 and R2 mirror',''+(docs?.total==null?'Coverage unavailable':(docs.current??0)+' / '+docs.total+' active task revisions verified')+' · 15-minute target.','/development/integration');
for(const [name,k] of IG_PROJECTS){const p=projects?.find(p=>p.tracker_project===name);const a=stripe?.accounts.find(a=>a.key===k);if(['apt','hum','yarr','owl'].includes(k)){const state=!stripe||!a?'Unavailable':!a.complete?'Partial':fresh(stripe.range_end,36);add(name,'Stripe','Balance transactions',state,stripe?.range_end,'Native hourly refresh · connector fallback until verified','Read-only access '+(a?.complete?'observed in last report':'not confirmed for complete period'),'Native reporting requires separately scoped live read-only credentials. Existing business credentials stay in their Workers.','/finance/sources')}
if(k==='pz')add(name,'Stripe','Commercial billing','Not connected',null,'Commercial access disabled','Not requested','Private-first; no live billing integration enabled.','/finance/sources');
if(k==='grim'){add(name,'Shopify','Sales snapshot',shop===null||!shop.checked_at?'Unavailable':shop.status!=='ready'||!shop.complete?'Partial':fresh(shop.checked_at,12),shop?.checked_at,'Existing rolling snapshot','Sales scope observed when complete','Rolling sales, not calendar-month reconciliation.','/finance/sources');add(name,'Printify','Product linkage',print?.verified_at?fresh(print.verified_at,168):'Unavailable',print?.verified_at,'Saved verification','Product access observed; cost permission unverified',(print?.matched_products==null?'Product matches unavailable':print.matched_products+' matched products')+'; fulfillment cost sync not connected.','/finance/sources')}
const repo=p?.repository?.replace(/^https:\/\/github\.com\//i,'').replace(/\/$/,'').replace(/\.git$/,'');const found=repo&&repos?.find(r=>r.repository.toLowerCase()===repo.toLowerCase());add(name,'GitHub','Repository oversight',projects===null||repos===null?'Unavailable':!repo?'Not connected':found?'Observed':'Partial',found?.observed_at,'Saved repository catalog',found?'Repository access observed; native PR sync unverified':'Repository access unverified',!repo?'No repository linked in tracker.':found?'Repository catalog match; no native PR, issue or deployment sync.':'Linked repository not found in last catalog.','/development');
const domains={grim:['thegrimthread.com'],hum:['humperdinck.studio'],pz:['projectzero.work','guides.projectzero.work'],apt:['siteapt.app'],owl:['thestoryowl.com'],yarr:['yarr.media']}[k];const matching=sites?.filter(s=>domains.includes(s.hostname.replace(/^www\./,'')))||[];const stamps=matching.map(s=>s.last_record).filter(s=>Number.isFinite(igTime(s))).sort((a,b)=>igTime(b)-igTime(a));const last=stamps[0];add(name,'SiteAPT','Website analytics',sites===null?'Unavailable':!matching.length?'Not connected':!last?'Observed':fresh(last,72)==='Current'?'Current':'Quiet / review',last,'Direct D1 read',matching.length?'Registered site record observed':'Site registration not observed',matching.length?matching.length+' matching hostname(s); latest recorded visit data. Quiet traffic does not establish failure.':'No matching registered hostname in the scoped query.','/traffic');
const workers=inventory?.workers.filter(w=>w.suggested_project===name)||[];add(name,'Cloudflare','Resource mapping',inventory===null?'Unavailable':workers.length?'Observed':'Partial',inventory?.route_observed_at||inventory?.observed_at,'Saved inventory','Resource metadata; ownership not confirmed',workers.length+' proposed Worker mapping(s); no uptime claim.','/operations/inventory');
}
if(health===null||!health.last_watchdog_at)add('SiteAPT','Cloudflare','Application watchdog','Unavailable',null,'Live D1 read','Health record unavailable','No verified watchdog timestamp.','/operations');else add('SiteAPT','Cloudflare','Application watchdog',health.integrity_mismatch_count>0?'Partial':fresh(health.last_watchdog_at,1),health.last_watchdog_at,'Live D1 read','Health record observed',fmt(health.integrity_mismatch_count)+' recorded integrity mismatches.','/operations');
for(const p of projects||[]){for(const c of plans?.filter(r=>r.lifecycle_id===p.id)||[]){add(p.name,c.provider||c.category,'Lifecycle plan · '+c.category,'Owner reported',c.updated_at,'Lifecycle setup','No API permission verified',c.status+' · planned configuration, not live connection.',lcWUrl(p.id,'setup'))}}
return {rows,observed_at:now.toISOString(),sourcesUnavailable:[projects===null?'Project catalog':null,plans===null?'Lifecycle setup':null].filter(Boolean)}}

