function igProvider(name){const key=Object.hasOwn(LC_KEY_MAP,name)?LC_KEY_MAP[name]:null;if(key)return '<span class="ig-provider-brand">'+brandMark({key,name})+'</span>';const icons={Stripe:['#635bff','<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M3 10h18M7 15h4"/>'],Shopify:['#548b28','<path d="M5 8h14l2 13H3L5 8zM9 8V6a3 3 0 0 1 6 0v2"/>'],Printify:['#287c45','<rect x="6" y="3" width="12" height="6" rx="1"/><path d="M6 17H3v-7h18v7h-3M6 14h12v7H6zM17 12h1"/>'],GitHub:['#24292f','<circle cx="6" cy="5" r="2"/><circle cx="6" cy="19" r="2"/><circle cx="18" cy="7" r="2"/><path d="M6 7v10M18 9a8 8 0 0 1-8 8H6"/>'],Cloudflare:['#d87519','<path d="M6 18a4 4 0 0 1-.6-8 6 6 0 0 1 11.5 1.5A3.3 3.3 0 0 1 18 18H6z"/>']};const icon=Object.hasOwn(icons,name)?icons[name]:null;return icon?'<span class="ig-provider-icon" style="--ig-accent:'+icon[0]+'" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+icon[1]+'</svg></span>':'<span class="ig-provider-icon ig-provider-fallback" aria-hidden="true">'+esc(name.slice(0,2).toUpperCase())+'</span>'}

