async function igPage(env,u){const x=await igRead(env),projects=[...new Set(x.rows.map(r=>r.project))].sort(),states=[...new Set(x.rows.map(r=>r.state))].sort();const project=u.searchParams.get('project')||'',state=u.searchParams.get('state')||'',q=(u.searchParams.get('q')||'').trim().toLowerCase().slice(0,100);const rows=x.rows.filter(r=>(!project||r.project===project)&&(!state||r.state===state)&&(!q||[r.provider,r.scope,r.note,r.mode].join(' ').toLowerCase().includes(q)));const opt=(list,value,empty)=>'<option value="">'+esc(empty)+'</option>'+list.map(v=>'<option value="'+esc(v)+'"'+(v===value?' selected':'')+'>'+esc(v)+'</option>').join('');const current=x.rows.filter(r=>r.state==='Current').length,review=x.rows.filter(r=>['Stale','Partial','Unavailable','Quiet / review'].includes(r.state)).length,not=x.rows.filter(r=>r.state==='Not connected').length;const body='<div class="ig-title"><div><h2>Integration management</h2><small>Live source checks · '+esc(x.observed_at.replace('T',' ').slice(0,19))+' UTC</small></div><div><a href="/integrations/google-login">Google login manager ↗</a> · <a href="/integrations">Refresh view ↻</a></div></div><div class="ig-kpis"><div><small>Current sources</small><strong>'+current+'</strong></div><div><small>Needs review</small><strong>'+review+'</strong></div><div><small>Not connected</small><strong>'+not+'</strong></div></div><form class="ig-filter" method="get" action="/integrations"><label>Business<select name="project">'+opt(projects,project,'All businesses')+'</select></label><label>Status<select name="state">'+opt(states,state,'All statuses')+'</select></label><label>Search<input name="q" maxlength="100" value="'+esc(q)+'" placeholder="Provider or data source"></label><button type="submit">Filter</button><a href="/integrations">Reset</a></form><p class="ig-note">'+rows.length+' / '+x.rows.length+' source observations. Current means recent evidence for the stated scope, not a complete provider connection test. Observed and owner reported are not live health. Missing permissions are only reported when established; absent evidence is unverified. No credentials are displayed or changed.</p>'+(x.sourcesUnavailable.length?'<p class="warn">Unavailable: '+esc(x.sourcesUnavailable.join(', '))+'</p>':'')+'<div class="ig-grid">'+(rows.length?rows.map(igCard).join(''):'<article>No matching sources.</article>')+'</div>';return response(page('Operations · integration management',body).replace('</head>','<style>'+IG_CSS+IG_BRAND_CSS+'</style></head>'),200,'text/html;charset=utf-8')}

