async function executiveData(env){
 const month=new Date().toISOString().slice(0,7);
 const [tasks,actions,finance,risks,perProject,history,expenses,financeCatalog]=await Promise.all([
 safeFirst(env.TRACKER,"SELECT COUNT(*) total,SUM(status='Done') done,SUM(priority='P0' AND status NOT IN ('Done','Deferred')) p0,SUM(status='Blocked') blocked,SUM(status='In progress') active FROM tracker_active_tasks"),
 safeFirst(env.TRACKER,"SELECT COUNT(*) n FROM tracker_owner_actions a JOIN tracker_active_tasks t ON t.task_id=a.task_id WHERE a.action_status='Needed' AND t.status NOT IN ('Done','Deferred')"),
 safeRows(env.PORTFOLIO,"SELECT project,revenue_cents,refund_cents,fees_cents,hosting_cents,other_cents FROM monthly_finance WHERE month=?",month),
 safeRows(env.TRACKER,"SELECT task_id,project,task,priority,status,owner FROM tracker_active_tasks WHERE status='Blocked' OR (priority='P0' AND status='Ready to verify') ORDER BY CASE WHEN priority='P0' THEN 0 ELSE 1 END,CASE WHEN status='Blocked' THEN 0 ELSE 1 END,project,task_id LIMIT 8"),
 safeRows(env.TRACKER,"SELECT project,COUNT(*) total,SUM(status='Done') done,SUM(priority='P0' AND status NOT IN ('Done','Deferred')) p0,SUM(status='Blocked') blocked FROM tracker_active_tasks GROUP BY project ORDER BY project"),
 safeRows(env.PORTFOLIO,"SELECT month,COUNT(*) projects,SUM(revenue_cents-refund_cents) revenue,SUM(fees_cents+hosting_cents+other_cents) expenses FROM monthly_finance WHERE month<=? GROUP BY month ORDER BY month DESC LIMIT 6",month),pxSummary(env),lbFinanceCatalog(env)
 ]);
 const [automatic,briefing,actionCenter]=await Promise.all([afRead(env,month,expenses),ebRead(env),acRead(env)]);return {month,tasks,actions,finance,risks,perProject,history,expenses,financeCatalog,automatic,briefing,actionCenter}
}
function execIcon(k){const p={revenue:'M12 3v18M16 7H9a3 3 0 0 0 0 6h6a3 3 0 0 1 0 6H7',cost:'M4 6h16v14H4zM4 10h16M8 3v3m8-3v3',profit:'M3 17l6-6 4 4 8-9m-6 0h6v6',critical:'M12 3 2 21h20zM12 9v5m0 3h.01',owner:'M8 4h8v4H8zM6 6H4v15h16V6h-2M8 13h8m-8 4h5',blocked:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18zM6 6l12 12',progress:'M3 3v18h18M7 15l4-4 4 2 5-7'};return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(p[k]||p.progress)+'"/></svg>'}
function executiveSummary(e,projects){
 const money=n=>typeof n==='number'&&Number.isFinite(n)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100):'—';
 const catalog=e.financeCatalog;const records=catalog?e.finance?.filter(r=>catalog.some(([key])=>key===r.project)):null;const total=records?.length?records.reduce((s,r)=>({revenue:s.revenue+r.revenue_cents-r.refund_cents,expenses:s.expenses+r.fees_cents+r.hosting_cents+r.other_cents}),{revenue:0,expenses:0}):null;
 const partial=records===null||records===undefined?'Finance data unavailable':records.length===catalog.length?'All '+catalog.length+' projects reconciled':records.length+' / '+catalog.length+' projects reconciled';
 const auto=e.automatic;const stats=[total?['Net revenue (reconciled)',money(total.revenue),partial,'/finance/reconcile']:['Recorded gross receipts',money(auto?.recordedGross),fmt(auto?.sourceCount)+' month-dated local ledgers · partial','/finance/sources'],total?['Operating costs (reconciled)',money(total.expenses),partial,'/finance/reconcile']:['Known commitments / mo',money(auto?.commitments),'Forecast · actual costs not reconciled','/finance/expenses'],['Net profit (reconciled)',money(total?total.revenue-total.expenses:null),partial,'/finance/reconcile'],['Critical priorities',fmt(e.tasks?.p0),'Open P0 tasks','/development?priority=P0'],['Needs your attention',fmt(e.actions?.n),'Owner decisions / actions','/actions?view=owner'],['Blocked work',fmt(e.tasks?.blocked),'Blocked development tasks','/actions?view=critical']];
 const items=stats.map(([title,value,note,href],i)=>{const n=[null,null,null,e.tasks?.p0,e.actions?.n,e.tasks?.blocked][i];const cls=i<3?'finance'+(i===2?' profit':''):'attention'+(typeof n==='number'?(n>0?' alert':' clear'):'');const shortTitle=[total?'Net revenue':'Gross receipts',total?'Actual costs':'Commitments / mo','Net profit','P0 priorities','Owner actions','Blocked work'][i];const shortNote=i===0&&!total?fmt(auto?.sourceCount)+' local ledgers · partial':i===1&&!total?'Forecast · not actual':i<3?partial.replace(' projects reconciled',' reconciled'):['Open P0 tasks','Decisions / actions','Blocked tasks'][i-3];return '<a class="executive-kpi '+cls+'" href="'+esc(href)+'" aria-label="'+esc(title+': '+value+'. '+note)+'"><span class="exec-kpi-label">'+execIcon(['revenue','cost','profit','critical','owner','blocked'][i])+'<span class="exec-full">'+esc(title)+'</span><span class="exec-short">'+esc(shortTitle)+'</span></span><strong>'+esc(value)+'</strong><small><span class="exec-full">'+esc(note)+'</span><span class="exec-short">'+esc(shortNote)+'</span></small></a>'}).join('');
 const financial=e.history?.length?listing(['Month','Projects','Net revenue','Costs','Profit'],e.history.slice().reverse(),r=>[plain(r.month),plain(r.projects+' entered'),plain(money(r.revenue)),plain(money(r.expenses)),plain(money(r.revenue-r.expenses))]):'<p class="muted">No reconciled monthly reports yet. Enter actual revenue, expenses and fees to calculate profit.</p>';
 const risks=e.risks===null?'<p class="warn">Development risks unavailable.</p>':e.risks?.length?e.risks.map(r=>'<a class="exec-risk" href="/development?q='+encodeURIComponent(r.task_id)+'"><span>'+trBrand(r.project)+'<small>'+esc(r.task_id)+'</small></span><strong>'+esc(r.task)+'</strong>'+trState(r.status)+'</a>').join(''):'<p class="muted">No blocked or critical verification tasks reported.</p>';
 const progress=e.perProject===null?'<p class="warn">Project progress unavailable.</p>':(e.perProject||[]).map(r=>{const pct=r.total?Math.round(100*r.done/r.total):0;return '<a class="exec-progress" href="/development?project='+encodeURIComponent(r.project)+'"><span>'+trBrand(r.project)+'</span><span class="exec-progress-bar" aria-label="'+pct+'% complete"><i style="width:'+pct+'%"></i></span><small>'+pct+'% · '+fmt(r.p0)+' P0</small></a>'}).join('');
 return '<div class="exec-period"><span>Executive scorecard</span><small>'+esc(e.month)+' · UTC month · source coverage matters</small></div><div class="executive-kpis">'+items+'</div><div class="actions"><a href="/finance/profitability">Profitability by business ↗</a><a href="/integrations">Integration health ↗</a><a href="/investments">Portfolio investment review ↗</a></div>'+acPanel(e.actionCenter)+ebPanel(e)+afPanel(e.automatic)+'<div class="exec-panels"><article><div class="exec-head"><h3>'+execIcon('critical')+' Risks &amp; decisions</h3><a href="/development/notes">Owner actions ↗</a></div>'+risks+'</article><article><div class="exec-head"><h3>'+execIcon('progress')+' Development progress</h3><a href="/development">All tasks ↗</a></div>'+progress+'</article></div>'+pxBrief(e.expenses)+'<details class="exec-financial"><summary>Monthly financial history</summary>'+financial+'<a href="/finance/reconcile?month='+esc(e.month)+'">Reconcile this month ↗</a></details>';
}

