function portfolioFlash(html,url){const q=url.searchParams,p=url.pathname;let message='',warning=false;if(p==='/inbox'&&['bulk-archived','bulk-restored','bulk-spam','bulk-notspam'].includes(q.get('notice'))){const n=Math.min(100,Math.max(1,Math.floor(Number(q.get('count'))||1)));message=n+' message'+(n===1?'':'s')+({'bulk-archived':' archived.','bulk-restored':' restored.','bulk-spam':' moved to Spam.','bulk-notspam':' moved to Inbox; sender trusted.'})[q.get('notice')]}else if(p==='/inbox'&&['select-message','mail-changed','mail-unavailable'].includes(q.get('notice'))){warning=true;message=({'select-message':'Select at least one message.','mail-changed':'The selected messages changed. Refresh and select again.','mail-unavailable':'Archive action could not be confirmed. Refresh and check the inbox.'})[q.get('notice')]}else if(p==='/development'&&q.get('created'))message='P0 feature added to the development queue.';else if(p==='/development'&&q.get('saved'))message='Task saved: '+q.get('saved');else if(p==='/brands'&&q.get('published'))message='Publication configuration saved. Verify the live website.';else if(p==='/brands'&&q.get('saved'))message='Brand draft saved.';else if(p==='/usage'&&q.get('refresh')==='verified')message='Cloudflare usage refreshed.';else if(p==='/usage'&&['pending','unconfirmed'].includes(q.get('refresh'))){message='Refresh requested; newer data is not yet verified.';warning=true}else{message=({'/development/notes':{'response':'Owner response saved.'},'/development/integration':{'revoked':'API key revoked.'},'/mail/sent':{'sent':'Email send recorded.'},'/inbox':{'archived':'Message archived.','restored':'Message restored.'},'/finance/reconcile':{'report':'Monthly report saved.'},'/secrets':{'created':'Secret stored and encrypted.','rotated':'Secret replaced.','revoked':'Secret revoked and its value deleted.'}}[p]||{})[q.get('notice')]||''}return message?html.replace('</body>',portfolioToast(message,warning)+'</body>'):html}

