async function getUsage(env){const [u,s,dbs]=await Promise.all([loadSnapshot(env,'analytics/cloudflare-usage-v1.json'),loadSnapshot(env,'analytics/cloudflare-r2-storage-v1.json'),Promise.all(Object.entries(DB_BIND).map(async ([binding,name])=>{try{const r=await env[binding].prepare('SELECT 1 AS ok').run();return [name,Number.isFinite(r.meta?.size_after)?r.meta.size_after:null]}catch{return [name,null]}}))]);return {u,s,sizes:Object.fromEntries(dbs)}}
function sumField(rows,key){return rows.length?rows.reduce((a,r)=>a+(Number.isFinite(r[key])?r[key]:0),0):null}
function usagePage(data,days,refresh){const {u,s,sizes}=data;const latest=u?.updated?Date.parse(u.updated):0;const cutoff=new Date(Date.now()-(days-1)*86400000).toISOString().slice(0,10);const slice=rows=>Array.isArray(rows)?rows.filter(r=>r.day>=cutoff):[];const d=slice(u?.data?.d1),w=slice(u?.data?.workers),r=slice(u?.data?.r2);const store=Array.isArray(s?.rows)?s.rows:[];const last=new Map();for(const row of store){if(!last.has(row.bucketName)||last.get(row.bucketName).day<row.day)last.set(row.bucketName,row)}const validStorage=[...last.values()].filter(v=>Number.isFinite(v.bytes));const totalBytes=sumField(validStorage,'bytes');const coverage=latest?Math.max(0,Math.round((Date.now()-latest)/3600000)):null;const dNames=new Map(DATABASES.map(x=>[x[0],x.slice(1)]));for(const row of d){if(!dNames.has(row.databaseId))dNames.set(row.databaseId,[u.databases?.[row.databaseId]||row.databaseId,'Unmapped resource'])}const bNames=new Map(BUCKETS);for(const name of [...last.keys(),...r.map(x=>x.bucketName)])if(!bNames.has(name))bNames.set(name,'Unmapped resource');const wNames=[...new Set(w.map(x=>x.scriptName))].sort();const trend=(rows,key)=>{const values=new Map();for(const v of rows)values.set(v.day,(values.get(v.day)||0)+(v[key]||0));const a=[...values].sort();const max=Math.max(1,...a.map(x=>x[1]));return a.length?'<div class="spark" aria-label="Daily activity">'+a.map(([day,n])=>'<i title="'+esc(day+': '+fmt(n))+'" style="height:'+Math.max(3,100*n/max)+'%"></i>').join('')+'</div>':''};return formPage('Cloudflare usage','<div class="actions"><form method="post" action="/usage/refresh"><button class="mail-action" type="submit">Refresh Cloudflare data now</button></form></div>'+(refresh==='verified'?'<p class="muted">New usage and storage snapshots verified.</p>':refresh==='pending'||refresh==='unconfirmed'?'<p class="warn">Refresh requested but a newer complete snapshot has not been verified. The last available data remains displayed.</p>':'')+'<div class="filters">'+[7,14,30].map(n=>'<a class="'+(n===days?'selected':'')+'" href="/usage?days='+n+'">'+n+' days</a>').join('')+'</div><p class="muted">Account-wide sampled Cloudflare Analytics SQL activity. UTC range '+esc(cutoff)+' through latest available records. Activity updated '+esc(u?.updated||'unavailable')+'; storage updated '+esc(s?.updated||'unavailable')+'. Snapshot coverage starts '+esc(u?.start||'unknown')+'. No row means unavailable, not zero.</p>'+(!latest||coverage>24?'<p class="warn">Usage snapshot '+(latest?'is '+coverage+' hours old':'is unavailable')+'. Recent activity may be missing.</p>':'')+gridStats([['D1 rows read',fmt(sumField(d,'reads'))],['D1 rows written',fmt(sumField(d,'writes'))],['R2 operations',fmt(sumField(r,'operations'))],['R2 payload storage',humanBytes(totalBytes)]])+'<div class="grid"><article><h3>D1 reads by day</h3>'+trend(d,'reads')+'</article><article><h3>R2 operations by day</h3>'+trend(r,'operations')+'</article><article><h3>Worker invocations by day</h3>'+trend(w,'requests')+'</article><article><h3>D1 writes by day</h3>'+trend(d,'writes')+'</article></div><div class="section">D1 databases</div>'+table(['Database','Rows read','Rows written','Current file size'],[...dNames].map(([id,[name,project]])=>{const rows=d.filter(x=>x.databaseId===id);return [resource(name,project),fmt(sumField(rows,'reads')),fmt(sumField(rows,'writes')),humanBytes(sizes[name])]}))+'<p class="muted">Current file size is read from query metadata for seven database bindings; other databases are not queried by this dashboard.</p><div class="section">R2 buckets</div>'+table(['Bucket','Operations','Payload size','Metadata','Objects','Storage date'],[...bNames].map(([name,project])=>{const v=last.get(name);return [resource(name,project),fmt(sumField(r.filter(x=>x.bucketName===name),'operations')),humanBytes(v?.bytes),humanBytes(v?.metadataBytes),fmt(v?.objects),esc(v?.day||'—')]}))+'<p class="muted">Storage totals use latest observed snapshot per bucket ('+validStorage.length+' of '+bNames.size+' listed buckets). Operations are combined, not separated by billing class. This is not an invoice or cost estimate.</p><div class="section">Workers</div>'+table(['Worker','Invocations'],wNames.map(name=>[resource(name,'All invocation types'),fmt(sumField(w.filter(x=>x.scriptName===name),'requests'))]))+'<p class="foot">The existing usage-refresh service publishes these snapshots. This dashboard does not list or download product files, customer attachments or signing recovery material.</p>')}
