const SPAM_THRESHOLD=60,SPAM_SUSPECT=30;
function mailAddress(v){const s=decodeMailSubject(v).toLowerCase();const m=s.match(/<([^<>\s]{3,254})>/)||s.match(/([^\s<>"',;]+@[^\s<>"',;]+)/);return (m?m[1]:s).trim().slice(0,254)}
function spamText(v){return String(v||'').toLowerCase().replace(/[‘’ʼ]/g,"'").replace(/[‐-―]/g,'-').replace(/\s+/g,' ')}
function classifySpam(m,trust={}){const text=spamText(decodeMailSubject(m.subject)+' \n '+String(m.body||'').slice(0,20000));const reasons=[];let score=0;for(const [weight,label,phrases] of SPAM_RULES){if(phrases.some(p=>text.includes(p))){score+=weight;reasons.push(label)}}if(trust.contact){score-=100;reasons.push('Sender previously marked not spam')}else if(trust.conversation){score-=50;reasons.push('Existing email conversation')}const level=score>=100?'Spam':score>=SPAM_THRESHOLD?'Marketing spam':score>=SPAM_SUSPECT?'Suspected spam':'Normal';return {score,level,reasons,auto:score>=SPAM_THRESHOLD}}
function inboxHref(project,view,notice){const v=view===true?'archive':view;const p=new URLSearchParams();if(project)p.set('project',project);if(v==='archive'||v==='spam')p.set('view',v);if(notice)p.set('notice',notice);return '/inbox'+(p.size?'?'+p.toString():'')}
const inboxKey=(key,id)=>JSON.stringify([key,String(id)]);
async function inboxSnapshot(env,filter,view){const selected=MAIL_SOURCES.find(s=>s.key===filter),sources=selected?[selected]:MAIL_SOURCES,results=await Promise.all(sources.map(s=>loadMail(env,s)));const all=results.flatMap(r=>r.rows.filter(m=>m.id!==null&&m.id!==undefined&&String(m.id).length>0&&String(m.id).length<=160&&!/[\r\n]/.test(String(m.id))).map(m=>({...m,id:String(m.id),project:r.src.name,url:r.src.url,key:r.src.key}))).sort((a,b)=>timestamp(b.ts)-timestamp(a.ts));const unique=[...new Map(all.map(m=>[inboxKey(m.key,m.id),m])).values()];const state=await Promise.all(sources.map(async s=>{const ids=unique.filter(m=>m.key===s.key).map(m=>m.id);if(!ids.length)return [];return safeRows(env.PORTFOLIO,'SELECT project,message_id FROM mailbox_state WHERE archived=1 AND project=? AND message_id IN ('+ids.map(()=>'?').join(',')+')',s.key,...ids)}));const [spamState,trusted,replied]=await Promise.all([Promise.all(sources.map(async s=>{const ids=unique.filter(m=>m.key===s.key).map(m=>m.id);if(!ids.length)return [];return safeRows(env.PORTFOLIO,'SELECT project,message_id,spam FROM mailbox_spam WHERE project=? AND message_id IN ('+ids.map(()=>'?').join(',')+')',s.key,...ids)})),safeRows(env.PORTFOLIO,"SELECT DISTINCT sender FROM mailbox_spam WHERE spam=0 AND sender<>'' LIMIT 1000"),safeRows(env.PORTFOLIO,'SELECT DISTINCT lower(to_address) address FROM outbound LIMIT 2000')]);const spamReady=spamState.every(x=>x!==null)&&trusted!==null;const overrides=new Map(spamState.flatMap(x=>x||[]).map(x=>[inboxKey(x.project,x.message_id),Number(x.spam)]));const trustedSenders=new Set((trusted||[]).map(x=>String(x.sender)));const repliedTo=new Set((replied||[]).map(x=>String(x.address)));for(const m of unique){const sender=mailAddress(m.sender);m.senderAddress=sender;m.spam=classifySpam(m,{contact:trustedSenders.has(sender),conversation:repliedTo.has(sender)});const o=overrides.get(inboxKey(m.key,m.id));m.spamOverride=o===0||o===1?o:null;m.isSpam=m.spamOverride===null?m.spam.auto:m.spamOverride===1}const archiveReady=state.every(x=>x!==null);const keys=new Set(state.flatMap(x=>x||[]).map(x=>inboxKey(x.project,x.message_id)));const live=archiveReady?unique.filter(m=>!keys.has(inboxKey(m.key,m.id))):[];const visible=archiveReady?(view==='archive'?unique.filter(m=>keys.has(inboxKey(m.key,m.id))):live.filter(m=>m.isSpam===(view==='spam'))).slice(0,100):[];const spamCount=live.filter(m=>m.isSpam).length;return {selected,sources,results,all:unique,visible,archiveReady,spamReady,spamCount,failed:results.filter(x=>x.failed||x.partial).map(x=>x.src.name)}}
function inboxIcon(name){const paths={archive:'<path d="M4 8h16v12H4zM3 4h18v4H3zM10 12h4"/>',restore:'<path d="M4 8h16v12H4zM3 4h18v4H3zM12 17v-6m-3 3 3-3 3 3"/>',compose:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14z"/>',chevron:'<path d="m9 6 6 6-6 6"/>',sent:'<path d="m3 3 18 9-18 9 4-9zM7 12h14"/>',spam:'<path d="M12 3 3 7v5c0 5 4 8 9 9 5-1 9-4 9-9V7zM9 9l6 6m0-6-6 6"/>',inbox:'<path d="M3 13h5l2 3h4l2-3h5M5 5h14l2 8v6H3v-6z"/>'};return '<svg class="ib-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+paths[name]+'</svg>'}
function spamTag(m){if(!m.spam)return '';const lvl=m.spamOverride===1?'Spam':m.spamOverride===0?'':m.spam.level;if(!lvl||lvl==='Normal')return '';return '<span class="ib-spam-tag'+(lvl==='Suspected spam'?' ib-suspect':'')+'" title="'+esc('Spam score '+m.spam.score)+'">'+esc(lvl)+'</span>'}
function inboxOps(view,spamReady){return view==='archive'?[['restore','Restore','restore']]:view==='spam'?[...(spamReady?[['notspam','Not spam','inbox']]:[]),['archive','Archive','archive']]:[['archive','Archive','archive'],...(spamReady?[['spam','Spam','spam']]:[])]}
function inboxInlineOps(m,view,filter,spamReady){return '<form class="mailinline" method="post" action="/mail/bulk"><input type="hidden" name="filter" value="'+esc(filter||'')+'"><input type="hidden" name="view" value="'+esc(view)+'"><input type="hidden" name="item" value="'+esc(inboxKey(m.key,m.id))+'">'+inboxOps(view,spamReady).map(([op,label])=>'<button class="mail-action" type="submit" name="op" value="'+op+'">'+label+'</button>').join('')+'</form>'}
function inboxMessage(m,view,filter,spamReady){const archive=view==='archive',spamView=view==='spam';const subject=decodeMailSubject(m.subject)||'(No subject)',sender=decodeMailSubject(m.sender)||'Unknown sender';const at=timestamp(m.ts);const when=at?new Date(at).toISOString().slice(5,16).replace('T',' '):'Unknown date';const unread=String(m.status).toLowerCase()==='unread';return '<article class="ib-message'+(unread?' ib-unread':'')+'"><label class="ib-check" title="Select message"><input type="checkbox" name="item" form="ib-bulk" value="'+esc(inboxKey(m.key,m.id))+'" aria-label="'+esc('Select '+subject)+'"></label><details class="ib-details"><summary><div class="ib-msghead">'+brandMark({key:m.key,name:m.project})+'<div class="ib-identity"><span class="ib-project">'+esc(m.project)+(unread?'<span class="ib-dot" aria-label="Unread"></span>':'')+spamTag(m)+'</span><span class="ib-sender">'+esc(sender)+'</span></div><time>'+esc(when)+'</time></div><strong class="ib-subject">'+esc(subject)+'</strong><div class="ib-preview">'+esc(String(m.body||'').replace(/\s+/g,' ').slice(0,180))+'</div></summary><div class="mailmeta">From '+esc(sender)+' · To '+esc(m.recipient||'Unknown')+' · '+esc(m.status||'Status unavailable')+' · UTC</div>'+(m.spam&&(m.spam.reasons.length||m.spamOverride!==null)?'<p class="ib-spam-why">'+esc((m.spamOverride===1?'Marked as spam by you. ':m.spamOverride===0?'Marked not spam by you. ':'')+'Spam score '+m.spam.score+(m.spam.reasons.length?': '+m.spam.reasons.join(', '):'')+'.')+'</p>':'')+'<div class="mailbody">'+esc(m.body||'(No stored text)')+'</div><div class="actions">'+(ALLOWED_SENDERS[m.key]&&!spamView?link('Reply','/mail/compose?project='+encodeURIComponent(m.key)+'&id='+encodeURIComponent(m.id),'primary'):'')+inboxInlineOps(m,view,filter,spamReady)+(spamView&&ALLOWED_SENDERS[m.key]?link('Request removal','/mail/compose?project='+encodeURIComponent(m.key)+'&id='+encodeURIComponent(m.id)+'&template=removal'):'')+(m.key==='pz'?link('Download original','/mail/raw?id='+encodeURIComponent(m.id)):link('Original inbox',m.url))+'</div></details></article>'}
async function inboxPage(env,filter,rawView){const view=['archive','spam'].includes(rawView)?rawView:'active';const data=await inboxSnapshot(env,filter,view),archive=view==='archive',spamView=view==='spam',selected=data.selected;const filterKey=selected?.key||'';const loaded=data.results.filter(x=>!x.failed).length;const unread=data.visible.filter(m=>String(m.status).toLowerCase()==='unread').length;const brandLinks='<a class="ib-project-filter'+(!selected?' active':'')+'" href="'+esc(inboxHref('',view))+'">All projects</a>'+MAIL_SOURCES.map(s=>'<a class="ib-project-filter'+(selected?.key===s.key?' active':'')+'" href="'+esc(inboxHref(s.key,view))+'">'+brandMark({key:s.key,name:s.name})+'<span>'+esc(s.name)+'</span></a>').join('');
const html='<div class="ib-top"><div class="ib-tabs"><a class="'+(view==='active'?'active':'')+'" href="'+esc(inboxHref(filterKey,''))+'">Inbox</a><a class="'+(spamView?'active':'')+'" href="'+esc(inboxHref(filterKey,'spam'))+'">Spam'+(data.spamCount?'<span class="ib-tabcount">'+esc(fmt(data.spamCount))+'</span>':'')+'</a><a class="'+(archive?'active':'')+'" href="'+esc(inboxHref(filterKey,'archive'))+'">Archive</a><a href="/mail/sent">Sent</a></div><a class="ib-compose" href="/mail/compose">'+inboxIcon('compose')+'<span>Compose</span></a></div><div class="ib-projects" data-no-swipe aria-label="Filter by project">'+brandLinks+'</div><div class="ib-count"><span>'+fmt(data.visible.length)+' '+(archive?'archived':spamView?'in spam':'messages')+(unread?' · '+fmt(unread)+' unread':'')+'</span><small>'+loaded+'/'+data.sources.length+' sources responding · UTC</small></div>'+(data.failed.length?'<p class="warn">Unavailable or incomplete: '+esc(data.failed.join(', '))+'</p>':'')+(!data.archiveReady?'<p class="warn">Archive state unavailable. Messages and actions are temporarily hidden.</p>':'')+(data.archiveReady&&!data.spamReady?'<p class="warn">Spam overrides unavailable. Automatic filtering still applies; Spam and Not spam actions are hidden.</p>':'')+(data.visible.length?'<form id="ib-bulk" class="ib-bulk" method="post" action="/mail/bulk" data-no-swipe><input type="hidden" name="filter" value="'+esc(filterKey)+'"><input type="hidden" name="view" value="'+esc(view)+'"><input type="hidden" name="op" value="" id="ib-op"><label class="ib-select-all"><input type="checkbox" id="ib-all" aria-label="Select all visible messages"><span>Select all</span></label><span id="ib-selection" aria-live="polite">0 selected</span>'+inboxOps(view,data.spamReady).map(([op,label,icon],i)=>'<button class="ib-op'+(i?' ib-secondary':'')+'"'+(i?'':' id="ib-submit"')+' type="submit" name="op" value="'+op+'" aria-label="'+esc(label+' selected')+'">'+inboxIcon(icon)+'<span>'+esc(label)+'</span></button>').join('')+'</form><div class="ib-list">'+data.visible.map(m=>inboxMessage(m,view,filterKey,data.spamReady)).join('')+'</div>':'<article class="ib-empty">'+(archive?'No archived messages in the current source window.':spamView?'No spam in the current source window.':'No messages in this selection.')+'</article>')+'<details class="ib-info"><summary>Mailbox information &amp; original inboxes</summary><p>Latest 40 messages per source, up to 100 displayed. Story Owl uses 30 days of metadata; Grim Thread uses stored previews. Opening here does not mark read. Central archive, restore and spam filing do not change original mailbox records. Messages scoring '+SPAM_THRESHOLD+' or more on marketing-spam phrases are filed in Spam automatically; '+SPAM_SUSPECT+'&ndash;'+(SPAM_THRESHOLD-1)+' are flagged as suspected. Not spam also trusts that sender for future messages.</p><div class="ib-originals">'+MAIL_SOURCES.map(s=>link(s.name,s.url)).join('')+'</div></details>';
return formPage('Central inbox',html).replace('</head>','<style>'+INBOX_CSS+'</style></head>')}
async function inboxBulk(req,env){if(!sameOriginPost(req)||!req.headers.get('content-type')?.startsWith('application/x-www-form-urlencoded'))return response('Forbidden',403);const max=64000;if(Number(req.headers.get('Content-Length')||0)>max)return response('Too large',413);const raw=await req.text();if(raw.length>max)return response('Too large',413);const f=new URLSearchParams(raw),filter=f.get('filter')||'',view=f.get('view'),archive=view==='archive';if(filter&&!MAIL_SOURCES.some(s=>s.key===filter)||!['archive','active','spam'].includes(view))return response('Invalid request',400);const op=f.getAll('op').find(Boolean)||(archive?'restore':'archive');if(!inboxOps(view,true).some(([o])=>o===op))return response('Invalid request',400);const redirect=(notice,count)=>new Response(null,{status:303,headers:{...headers,Location:inboxHref(filter,view,notice)+(count?'&count='+count:'')}});const items=f.getAll('item');if(!items.length||items.length>100)return redirect('select-message');const selected=new Map();try{for(const item of items){const parsed=JSON.parse(item);if(!Array.isArray(parsed)||parsed.length!==2)throw Error('Invalid item');const [key,id]=parsed;if(!MAIL_SOURCES.some(s=>s.key===key)||typeof id!=='string'||!id||id.length>160||/[\r\n]/.test(id)||(filter&&filter!==key))throw Error('Invalid item');selected.set(inboxKey(key,id),{key,id})}}catch{return redirect('mail-changed')}
try{const data=await inboxSnapshot(env,filter,view);if(!data.archiveReady||(['spam','notspam'].includes(op)&&!data.spamReady))return redirect('mail-unavailable');const visible=new Map(data.visible.map(m=>[inboxKey(m.key,m.id),m]));if([...selected.keys()].some(k=>!visible.has(k)))return redirect('mail-changed');const time=new Date().toISOString();const writes=[...selected.keys()].map(k=>visible.get(k)).map(m=>['spam','notspam'].includes(op)?env.PORTFOLIO.prepare("INSERT INTO mailbox_spam(project,message_id,sender,spam,updated_at) VALUES(?,?,?,?,?) ON CONFLICT(project,message_id) DO UPDATE SET sender=excluded.sender,spam=excluded.spam,updated_at=excluded.updated_at").bind(m.key,m.id,String(m.senderAddress||'').slice(0,254),op==='spam'?1:0,time):env.PORTFOLIO.prepare("INSERT INTO mailbox_state(project,message_id,archived,updated_at) VALUES(?,?,?,?) ON CONFLICT(project,message_id) DO UPDATE SET archived=excluded.archived,updated_at=excluded.updated_at").bind(m.key,m.id,op==='restore'?0:1,time));const results=await env.PORTFOLIO.batch(writes);if(results.length!==writes.length||results.some(r=>!r.success))return redirect('mail-unavailable');return redirect({restore:'bulk-restored',archive:'bulk-archived',spam:'bulk-spam',notspam:'bulk-notspam'}[op],writes.length)}catch{return redirect('mail-unavailable')}}

