const TR_KEYS={'SiteAPT':'apt','Humperdinck':'hum','Yarr':'yarr','Grim Thread':'grim','Story Owl':'owl','Project Zero':'pz','Shared systems':'shared'};
function trBrand(p){const k=Object.hasOwn(TR_KEYS,p)?TR_KEYS[p]:'shared';return '<span class="tr-brand"><span class="tr-logo tr-logo-'+k+'" aria-hidden="true">'+(k==='shared'?'▦':'')+'</span><span>'+esc(p)+'</span></span>'}
function trState(s){const k={'Done':'done','Blocked':'blocked','In progress':'progress','Ready to verify':'verify','Needed':'blocked','Responded':'verify','Resolved':'done'}[s]||'neutral';return '<span class="tr-state tr-state-'+k+'">'+esc(s||'Unknown')+'</span>'}
function trLine(t){return '<summary class="tr-line"><div class="tr-ident">'+trBrand(t.project)+'<small>'+esc(t.task_id)+(t.priority?' · <span class="tracker-'+esc(t.priority.toLowerCase())+'">'+esc(t.priority)+'</span>':'')+'</small></div><div class="tr-title"><strong>'+esc(t.task)+'</strong>'+(t.owner_action_status==='Needed'?'<small class="tr-attention">Owner action required</small>':t.owner_action_status==='Responded'?'<small>Owner responded</small>':'')+'</div><div class="tr-status">'+trState(t.status)+'</div><small class="tr-assignee">'+esc(t.owner||t.updated_by||'Unassigned')+'</small><span class="tr-chevron" aria-hidden="true">⌄</span></summary>'}
function trProjectFilter(u,project,rows,path='/development'){const params=new URLSearchParams(u.searchParams);for(const key of ['page','saved','created','notice','count'])params.delete(key);const href=p=>{if(p)params.set('project',p);else params.delete('project');return path+(params.toString()?'?'+esc(params.toString()):'')};return '<div class="tr-projects" aria-label="Filter by project">'+['',...new Set([...TRACKER_PROJECTS,...(rows||[]).map(r=>r.project)])].map(p=>'<a href="'+href(p)+'"'+(project===p?' aria-current="page"':'')+'>'+(p?trBrand(p):'<span class="tr-logo tr-logo-shared" aria-hidden="true">▦</span>All projects')+(p&&rows?.find(r=>r.project===p)?.total!=null?'<small>'+fmt(rows.find(r=>r.project===p).total)+'</small>':'')+'</a>').join('')+'</div>'}
const trBrandCss=()=>[...new Set(Object.values(TR_KEYS))].filter(k=>BRAND_ASSETS[k]).map(k=>'.tr-logo-'+k+'{background-image:url("'+BRAND_ASSETS[k]+'")}').join('');

