const BL_BASELINE={"hum":{"colors":[["Background","#090909"],["Card surface","#141414"],["Secondary surface","#171717"],["Primary text","#E9E9E9"],["Secondary text","#A4A4A4"],["White / focus","#FFFFFF"],["Primary button","#EDEDED"],["Button ink","#111111"],["Muted accent","#777777"],["Border","#333333"],["Header border","#232323"],["Button border","#4A4A4A"]],"logos":[["Brand mark","https://humperdinck.studio/assets/brand-modern.png?v=20261108a",true],["Favicon","https://humperdinck.studio/assets/humperdinck-favicon.ico",true]],"og":"https://humperdinck.studio/assets/og-image.png"},"apt":{"colors":[["White","#FFFFFF"],["Light grey","#FAFAFA"],["Soft grey","#F0F0F0"],["Bone highlight","#F8F6F2"],["Black","#191919"],["Muted","#666666"],["Border","#E5E5E5"],["Section border","#D9D9D9"],["Selected / accent","#202020"],["Accent border","#DCDCDC"]],"logos":[["Black logo","https://siteapt.app/assets/siteapt-logo-black-v1.png?v=20261123-4",false],["White logo","https://siteapt.app/assets/siteapt-logo-white-v1.png",true],["Brand mark","https://siteapt.app/siteapt-mark.png?v=20261123-3",false]],"og":"https://siteapt.app/og/siteapt-social-v1.jpg"},"grim":{"colors":[["Ink","#171717"],["Paper","#F8F7F3"],["White","#FFFFFF"],["Orange accent","#FF5835"],["Muted text","#57534E"],["Border","#C8C5BD"],["Secondary border","#BCB9B1"],["Warm grey","#E8E5DF"],["Alternate surface","#EEECE7"],["Dark surface","#282828"],["Error","#B24538"],["Secondary ink","#111111"]],"logos":[["Store logo","https://thegrimthread.com/assets/grim-thread-logo.webp",false],["Favicon","https://thegrimthread.com/favicon.ico",false]],"og":"https://thegrimthread.com/assets/grim-thread-og-v1.jpg"},"owl":{"colors":[["Background","#1A1B25"],["Panel","#252635"],["Text","#EBE8EE"],["Accent","#FD8087"],["Muted","#B6B1C4"],["Border","#373847"],["White","#FFFFFF"]],"logos":[["Owl mark","https://www.thestoryowl.com/imgs/theOwl.webp",true],["Favicon","https://www.thestoryowl.com/favicon.png",true]],"og":"https://www.thestoryowl.com/imgs/storyowl-og.png"},"yarr":{"colors":[["Background","#0A0A0A"],["Off-white / ink","#F5F1E8"],["Crimson accent","#A61E1E"],["Bright accent","#EB8888"],["Muted","#C2BCB2"],["Translucent border","#FFFFFF25"],["Logo white","#FFFFFF"]],"logos":[["Moon and sail mark","https://yarr.media/brand-mark.svg?v=moon-sail-v1",true],["SVG favicon","https://yarr.media/favicon.svg",true]],"og":"https://yarr.media/assets/yarr-media-og-v2.jpg"}};

const blLiveKey=k=>'live/'+k+'/manifest.json';
async function blPublished(env,k){const o=await env.BRAND_FILES.get(blLiveKey(k));return o?{manifest:await o.json(),etag:o.etag}:{manifest:null,etag:null}}
function blPlan(b){const base=BL_BASELINE[b.key];if(!base)throw Error('Project not connected');const norm=s=>String(s||'').toLowerCase().trim();const colors={},colorRows=[],files=[],ignored=[];for(const [label,hex] of base.colors){const row=b.colors.find(x=>norm(x[0])===norm(label));if(row&&row[1].toUpperCase()!==hex.toUpperCase()){const before=hex.toUpperCase(),after=row[1].toUpperCase();if(!/^#[A-F0-9]{6}(?:[A-F0-9]{2})?$/.test(after))throw Error('Invalid color');if(colors[before]&&colors[before]!==after)throw Error('Conflicting replacements for '+before);colors[before]=after;colorRows.push([label,before,after])}}for(const [label] of b.colors)if(!base.colors.some(x=>norm(x[0])===norm(label)))ignored.push('New color role: '+label);for(const [label,url] of base.logos){const row=b.logos.find(x=>norm(x[0])===norm(label));if(row&&row[1]&&row[1]!==url)files.push({label,path:new URL(url).pathname,source:row[1]})}for(const [label] of b.logos)if(!base.logos.some(x=>norm(x[0])===norm(label)))ignored.push('New logo variant: '+label);if(b.og&&b.og!==base.og)files.push({label:'Open Graph image',path:new URL(base.og).pathname,source:b.og});return {colors,colorRows,files,ignored}}
async function blPublishPage(env,u){const key=u.searchParams.get('project');if(!BL_KEYS.includes(key))return response('Not found',404);const b=await blRead(env,key);if(!b)return response('Not found',404);const {manifest,etag}=await blPublished(env,key);let plan;try{plan=blPlan(b)}catch(e){return response(blPage('Review brand changes','<p class="warn">'+esc(e.message)+'</p><a href="/brands/edit?project='+key+'">Edit brand</a>'),400,'text/html;charset=utf-8')}const hidden='<input type="hidden" name="project" value="'+esc(key)+'"><input type="hidden" name="revision" value="'+esc(b.revision)+'"><input type="hidden" name="etag" value="'+esc(etag||'')+'">';return response(blPage('Publish · '+b.name,'<div class="actions"><a href="/brands?project='+key+'">Back to library</a><a href="'+esc(b.site)+'" target="_blank" rel="noopener noreferrer">Live website ↗</a></div><article><h3>Review production changes</h3><p>'+esc(manifest?.revision?'Published revision '+manifest.revision:'Original site branding')+' · Draft '+fmt(b.revision)+'</p><p class="muted">Connected homepage and shared CSS colors, existing logos, icons and OG images only. New roles, typography and notes stay in the library. Removing a connected value restores its original. Colors sharing an original hex are changed together.</p></article><div class="section">Colors</div>'+(plan.colorRows.length?table(['Role','Original','Replacement'],plan.colorRows.map(([l,x,y])=>[esc(l),esc(x),esc(y)])):'<p class="muted">No color changes.</p>')+'<div class="section">Images</div>'+(plan.files.length?table(['Asset','Live path','Replacement'],plan.files.map(f=>[esc(f.label),esc(f.path),'<a href="'+esc(f.source)+'">Preview ↗</a>'])):'<p class="muted">No image changes.</p>')+(plan.ignored.length?'<p class="warn">Library only: '+esc(plan.ignored.join('; '))+'</p>':'')+'<form class="mailform" action="/brands/publish" method="post">'+hidden+'<label class="check"><input type="checkbox" name="confirm" value="yes" required> Publish this draft to production.</label><button>Publish to live site</button></form>'+(manifest?.revision?'<form class="mailform" action="/brands/restore" method="post">'+hidden+'<label class="check"><input type="checkbox" name="confirm" value="yes" required> Restore original site branding; keep my draft.</label><button>Restore original branding</button></form>':'')+'<p class="muted">Use uploaded PNG, JPEG or WebP images, or a different image URL on the same project domain. Published assets are public. Cache and social previews may take longer to refresh.</p>'),200,'text/html;charset=utf-8')}
function blImage(bytes){if(bytes.length>24&&[137,80,78,71,13,10,26,10].every((v,i)=>bytes[i]===v))return {mime:'image/png',ext:'png'};if(bytes.length>4&&bytes[0]===255&&bytes[1]===216&&bytes[2]===255)return {mime:'image/jpeg',ext:'jpg'};if(bytes.length>16&&String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP')return {mime:'image/webp',ext:'webp'};throw Error('Replacement must be PNG, JPEG or WebP.')}
async function blBounded(body){const reader=body?.getReader();if(!reader)throw Error('Image unavailable');let size=0,parts=[];while(true){const {value,done}=await reader.read();if(done)break;size+=value.byteLength;if(size>BL_MAX){await reader.cancel();throw Error('Image exceeds 3 MiB.')}parts.push(value)}const data=new Uint8Array(size);let i=0;for(const part of parts){data.set(part,i);i+=part.byteLength}return data}
async function blGetImage(env,b,f){if(BL_PATH.test(f.source)&&f.source.split('/')[3]===b.key){const o=await env.BRAND_FILES.get(f.source.slice('/brands/asset/'.length));if(!o||o.size>BL_MAX)throw Error('Uploaded image unavailable.');return blBounded(o.body)}let url;try{url=new URL(f.source)}catch{throw Error('Upload a replacement image.')}const domain=new URL(b.site).hostname.replace(/^www\./,'');if(url.protocol!=='https:'||url.username||url.password||url.port||![domain,'www.'+domain].includes(url.hostname)||url.pathname===f.path)throw Error('Use a different image URL on this project’s domain or upload a replacement.');const r=await fetch(url.toString(),{redirect:'error',signal:AbortSignal.timeout(10000),headers:{Accept:'image/png,image/jpeg,image/webp'}});if(!r.ok||!/^image\/(png|jpeg|webp)(?:;|$)/i.test(r.headers.get('Content-Type')||'')||Number(r.headers.get('Content-Length')||0)>BL_MAX)throw Error('Replacement URL must return PNG, JPEG or WebP up to 3 MiB.');return blBounded(r.body)}
async function blPublish(req,env,restore){if(!sameOriginPost(req)||!req.headers.get('Content-Type')?.startsWith('application/x-www-form-urlencoded'))return response('Forbidden',403);if(Number(req.headers.get('Content-Length')||0)>4096)return response('Too large',413);const raw=await req.text();if(raw.length>4096)return response('Too large',413);const form=new URLSearchParams(raw),key=form.get('project'),rev=Number(form.get('revision')),expected=form.get('etag')||null;if(!BL_KEYS.includes(key)||key==='pz'||!Number.isSafeInteger(rev)||rev<1||form.get('confirm')!=='yes')return response('Invalid publication request',400);try{const b=await blRead(env,key);if(!b||b.revision!==rev)throw Error('The draft changed. Reload before publishing.');const old=await blPublished(env,key);if(old.etag!==expected)throw Error('The publication changed. Reload before publishing.');const plan=restore?{colors:{},files:[]}:blPlan(b);const files={};for(const f of plan.files){const bytes=await blGetImage(env,b,f),info=blImage(bytes);const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');const object='live/'+key+'/objects/'+hash+'.'+info.ext;await env.BRAND_FILES.put(object,bytes,{httpMetadata:{contentType:info.mime}});files[f.path]={object,mime:info.mime}}const latest=await blRead(env,key);if(latest?.revision!==rev)throw Error('The draft changed during publishing. Reload.');const manifest={version:1,project:key,revision:restore?0:rev,colors:plan.colors,files,publishedAt:new Date().toISOString()};const result=await env.BRAND_FILES.put(blLiveKey(key),JSON.stringify(manifest),{httpMetadata:{contentType:'application/json'},onlyIf:expected?{etagMatches:expected}:{etagDoesNotMatch:'*'}});if(!result)throw Error('Another publication occurred. Reload.');return new Response(null,{status:303,headers:{...headers,Location:'/brands?project='+key+'&published=1'}})}catch(e){const m=String(e.message||'');return response(blPage('Brand update not published','<p class="warn">'+esc(/^(The draft|The publication|Another publication|Invalid color|Conflicting replacements|Uploaded image|Upload a replacement|Use a different|Replacement|Image exceeds|Image unavailable)/.test(m)?m:'Publication could not be confirmed. Check the live site before retrying.')+'</p><a class="button" href="/brands/publish?project='+esc(key)+'">Return to publication</a>'),409,'text/html;charset=utf-8')}}
function blCardNew(b,live){const status=b.key==='pz'?'Private draft':live?.revision===b.revision?'Published':live?.revision?'Unpublished changes':'Original branding';const swatches=b.colors.map(([label,hex])=>'<div class="brand-color-item"><span class="brand-color-dot" style="background:'+esc(hex)+'"></span><div><strong>'+esc(label)+'</strong><input readonly aria-label="'+esc(label)+' hex" value="'+esc(hex)+'"></div></div>').join('');const logos=b.logos.map(([label,url,dark])=>'<div class="brand-asset"><a class="brand-image'+(dark?' dark':'')+'" href="'+esc(url)+'" target="_blank" rel="noopener noreferrer"><img src="'+esc(blPreview(b,url))+'" alt="'+esc(label)+'" loading="lazy"></a><strong>'+esc(label)+'</strong></div>').join('');return '<article class="brand-detail"><div class="brand-title"><div>'+brandMark({key:b.key,name:b.name})+'<div><h2>'+esc(b.name)+'</h2><a href="'+esc(b.site)+'" target="_blank" rel="noopener noreferrer">'+esc(new URL(b.site).hostname)+' ↗</a></div></div><div class="brand-actions"><span class="brand-state">'+esc(status)+'</span><a class="button" href="/brands/edit?project='+b.key+'">Edit brand</a>'+(b.key==='pz'?'<span class="muted">Private brand draft</span>':'<a class="primary" href="/brands/publish?project='+b.key+'">Publish to live site</a>')+'</div></div><div class="brand-showcase"><section><h3>Logos &amp; icons</h3><div class="brand-logos">'+logos+'</div></section><section><h3>Social sharing image</h3>'+(b.og?'<a class="brand-og" href="'+esc(b.og)+'" target="_blank" rel="noopener noreferrer"><img src="'+esc(b.og)+'" alt="'+esc(b.name)+' social image" loading="lazy"></a>':'<p>No image recorded</p>')+'</section></div><section class="brand-palette-section"><h3>Color palette</h3><div class="brand-palette">'+swatches+'</div></section><details class="brand-guidelines"><summary>Typography, guidelines &amp; source</summary><p>'+esc(b.fonts||'Not specified')+'</p><p>'+esc(b.note||'')+'</p><p class="muted">'+esc(b.source)+' · Draft revision '+fmt(b.revision)+'</p></details></article>'}
async function brandLibraryNew(env,u){const brands=(await Promise.all(BL_KEYS.map(k=>blRead(env,k)))).filter(Boolean);const key=BL_KEYS.includes(u.searchParams.get('project'))?u.searchParams.get('project'):BL_KEYS[0];const b=brands.find(b=>b.key===key);if(!b)return blPage('Brand library','<p class="warn">Brand unavailable.</p>');const live=await blPublished(env,key).then(x=>x.manifest).catch(()=>null);return blPage('Brand library','<div class="brand-tabs">'+brands.map(x=>'<a href="/brands?project='+x.key+'"'+(x.key===key?' aria-current="page"':'')+'>'+brandMark({key:x.key,name:x.name})+'<span>'+esc(x.name)+'</span></a>').join('')+'</div>'+(u.searchParams.get('published')?'<p class="bl-saved">Publication configuration saved. Verify the live website.</p>':u.searchParams.get('saved')?'<p class="bl-saved">Draft saved. Publish when ready.</p>':'')+blCardNew(b,live)+(key==='pz'?pzBrandKitGallery():''))}

