async function trackerFeatures(env,u){const projectNames=(await safeRows(env.TRACKER,'SELECT project FROM tracker_active_projects ORDER BY project')||[]).map(r=>r.project);const project=projectNames.includes(u.searchParams.get('project'))?u.searchParams.get('project'):projectNames[0]||'';const recent=await safeRows(env.TRACKER,"SELECT * FROM tracker_active_tasks WHERE task_id GLOB '*-F-*' ORDER BY updated_at DESC,task_id LIMIT 50");return featurePage('Development feature requests',trackerTabs()+featurePageHtml(project,{title:(u.searchParams.get('title')||'').slice(0,1000),details:(u.searchParams.get('details')||'').slice(0,12000)},'',projectNames)+'<div class="section">Submitted features · latest 50</div>'+ (recent===null?'<p class="warn">Feature requests unavailable.</p>':recent.length?'<div class="tracker-list">'+recent.map(taskCard).join('')+'</div>':'<article>No features submitted yet.</article>'))}
async function trackerCreateFeature(req,env){if(!sameOriginPost(req)||!req.headers.get('content-type')?.startsWith('application/x-www-form-urlencoded'))return response('Forbidden',403);if(Number(req.headers.get('Content-Length')||0)>60000)return response('Too large',413);const raw=await req.text();if(raw.length>60000)return response('Too large',413);const f=new URLSearchParams(raw),project=f.get('project')||'',title=(f.get('title')||'').trim(),details=(f.get('details')||'').trim(),due=f.get('due')||'',request_id=f.get('request_id')||'';const projectNames=(await safeRows(env.TRACKER,'SELECT project FROM tracker_active_projects ORDER BY project')||[]).map(r=>r.project);const values={title,details,due,request_id};const fail=(message,status=400)=>response(featurePage('Development feature requests',trackerTabs()+featurePageHtml(projectNames.includes(project)?project:projectNames[0]||'',values,message,projectNames)),status,'text/html;charset=utf-8');if(!projectNames.includes(project)||!title||title.length>1000||!details||details.length>12000||!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(request_id)|| (due&&(!/^\d{4}-\d{2}-\d{2}$/.test(due)||!Number.isFinite(Date.parse(due+'T00:00:00Z'))||new Date(due+'T00:00:00Z').toISOString().slice(0,10)!==due)))return fail('Select an active project and enter a title, requirements and a valid optional date.');const id=(Object.hasOwn(FEATURE_PREFIX,project)?FEATURE_PREFIX[project]:'LC')+'-F-'+request_id.toUpperCase();try{const result=await env.TRACKER.prepare("INSERT INTO tracker_tasks(project,task_id,priority,task,status,owner,due_date,source_updated,evidence,notes,repository,revision,updated_at,updated_by) SELECT project,?,'P0',?,'Not started','Unassigned',?,'Owner feature request','',?,COALESCE(repository,''),1,?,'Owner' FROM tracker_active_projects WHERE project=? ON CONFLICT(task_id) DO NOTHING RETURNING task_id").bind(id,title,due,details,new Date().toISOString(),project).first();if(!result){const existing=await env.TRACKER.prepare("SELECT task_id,project FROM tracker_active_tasks WHERE task_id=?").bind(id).first();if(!existing||existing.project!==project)return fail('Feature could not be created. Reload and try again.',409)}return new Response(null,{status:303,headers:{...headers,Location:'/development?q='+encodeURIComponent(id)+'&created='+encodeURIComponent(id)}})}catch{return fail('Feature creation could not be confirmed. Retry this same form to avoid creating a duplicate.',503)}}

// ---- Chamber of Secrets (PZ-05) --------------------------------------------------------------
// Encrypted, workspace-scoped credential store. Values are sealed with AES-256-GCM using a key
// derived per workspace (HKDF) from the VAULT_MASTER_KEY Worker secret and bound to the row by AAD.
// Values are never rendered or returned after saving. Agents never receive values: they can only
// invoke brokered actions (deploy / preflight / rollback) that use the stored credentials server-side.
const VAULT_WORKSPACE='owner';
const VAULT_KINDS={'cloudflare-token':'Cloudflare API token','cloudflare-account':'Cloudflare account ID','build-manifest':'Build manifest (JSON)','github-token':'GitHub token','stripe-key':'Stripe key','api-key':'Other API key','other':'Other'};
const VAULT_MAX=65536;
const VAULT_DEPLOY_SECRETS=[['cloudflare-deploy-token','cloudflare-token','Cloudflare API token with Workers Scripts: Edit (and D1: Edit for migrations)',true,['CLOUDFLARE_API_TOKEN']],['cloudflare-account-id','cloudflare-account','32-character Cloudflare account ID',true,['CLOUDFLARE_ACCOUNT_ID']],['build-manifest','build-manifest','Private release manifest (docs/RELEASE.md)',true,['PZ_BUILD_MANIFEST']],['github-token','github-token','Optional read-only token; avoids GitHub API rate limits',false,['GITHUB_TOKEN']]];
const vaultDeployNames=spec=>[spec[0],...(spec[4]||[])];
const VAULT_DEPLOYABLE=['portfolio-owner','portfolio-tracker-api','portfolio-brand-edge','projectzero-commercial','projectzero-guides'];
const VAULT_REPO='blarkin13/projectzero.work';
const vaultEnc=new TextEncoder(),vaultDec=new TextDecoder();
class ChamberError extends Error{constructor(message,status=400){super(message);this.status=status}}
function vaultB64(bytes){let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s)}
function vaultUnb64(s){const bin=atob(s);const out=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)out[i]=bin.charCodeAt(i);return out}
async function vaultSha(text){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',typeof text==='string'?vaultEnc.encode(text):text)),x=>x.toString(16).padStart(2,'0')).join('')}
async function vaultKey(env,workspace){let bytes;try{bytes=vaultUnb64(String(env.VAULT_MASTER_KEY||'').trim())}catch{return null}if(bytes.length!==32)return null;const base=await crypto.subtle.importKey('raw',bytes,'HKDF',false,['deriveKey']);return crypto.subtle.deriveKey({name:'HKDF',hash:'SHA-256',salt:vaultEnc.encode('projectzero-chamber-v1'),info:vaultEnc.encode('workspace:'+workspace)},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
const vaultAad=(ws,id,kind)=>vaultEnc.encode('pz-chamber|v1|'+ws+'|'+id+'|'+kind);
async function vaultSeal(key,ws,id,kind,value){const iv=crypto.getRandomValues(new Uint8Array(12));const ct=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:vaultAad(ws,id,kind)},key,vaultEnc.encode(value)));return {iv:vaultB64(iv),ciphertext:vaultB64(ct)}}
async function vaultOpen(key,row){return vaultDec.decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:vaultUnb64(row.iv),additionalData:vaultAad(row.workspace_id,row.id,row.kind)},key,vaultUnb64(row.ciphertext)))}
function vaultValidate(kind,raw,name=''){const value=String(raw||'').replace(/\r\n/g,'\n').trim();if(!value)throw new ChamberError('Enter the secret value.');const google=GOOGLE_LOGIN_TARGETS.find(t=>googleSecretName(t)===name);if(google){if(kind!=='other')throw new ChamberError('Use Google login manager to import Web client credentials.');return JSON.stringify(googleClientConfig(value,google));}if(stripeChamberSpec(name)){if(kind!=='stripe-key'||!stripeConfig(value))throw new ChamberError('Enter a JSON object with the live Stripe account ID and restricted read-only API key.');return JSON.stringify(stripeConfig(value));}if(vaultEnc.encode(value).length>VAULT_MAX)throw new ChamberError('Secret values are limited to 64 KB.');if(kind==='cloudflare-account'&&!/^[0-9a-f]{32}$/.test(value))throw new ChamberError('A Cloudflare account ID is 32 lowercase hexadecimal characters.');if(kind==='build-manifest'){let m;try{m=JSON.parse(value)}catch{throw new ChamberError('The build manifest must be valid JSON.')}if(m?.schema!==1||!m.workers||typeof m.workers!=='object')throw new ChamberError('The build manifest must use schema 1 with a workers object.');if(JSON.stringify(m).match(/"type"\s*:\s*"secret_text"/))throw new ChamberError('The build manifest must not contain secret binding values.')}if(/[\n\s]/.test(value)&&!['build-manifest','other'].includes(kind))throw new ChamberError('This kind of secret cannot contain spaces or line breaks.');return value}
function vaultHint(kind,value,name=''){if(GOOGLE_LOGIN_TARGETS.some(t=>googleSecretName(t)===name))return 'Google Web client';if(stripeChamberSpec(name))return 'Restricted Stripe connection';if(kind==='build-manifest')return 'JSON · '+Math.max(1,Math.round(value.length/1024))+' KB';if(kind==='cloudflare-account')return '…'+value.slice(-4);return value.length>=16?'…'+value.slice(-4):''}
async function vaultAudit(env,ws,secret,action,actor,detail){try{await env.PORTFOLIO.prepare('INSERT INTO vault_audit(workspace_id,secret_id,secret_name,action,actor,at,detail) VALUES(?,?,?,?,?,?,?)').bind(ws,secret?.id||'',secret?.name||'',action,actor,new Date().toISOString(),String(detail||'').slice(0,500)).run();return true}catch{return false}}
const vaultAuditStmt=(env,ws,secret,action,actor,detail,at)=>env.PORTFOLIO.prepare('INSERT INTO vault_audit(workspace_id,secret_id,secret_name,action,actor,at,detail) VALUES(?,?,?,?,?,?,?)').bind(ws,secret.id,secret.name,action,actor,at,String(detail||'').slice(0,500));
async function vaultLoad(env,ws,name){return env.PORTFOLIO.prepare("SELECT * FROM vault_secrets WHERE workspace_id=? AND name=? AND status='Active'").bind(ws,name).first()}
async function vaultUse(env,ws,key,name,actor,purpose,eligible=()=>true){const row=await vaultLoad(env,ws,name);if(!row||!eligible(row))return null;let value;try{value=await vaultOpen(key,row)}catch{throw new ChamberError('Stored secret '+name+' could not be decrypted. Check VAULT_MASTER_KEY.',500)}const at=new Date().toISOString();try{await env.PORTFOLIO.batch([env.PORTFOLIO.prepare('UPDATE vault_secrets SET last_used_at=?,last_used_by=? WHERE id=? AND workspace_id=?').bind(at,actor,row.id,ws),vaultAuditStmt(env,ws,row,'Used',actor,purpose,at)])}catch{throw new ChamberError('Chamber audit log unavailable; refusing to use secrets.',503)}return {row,value}}
async function vaultUseSpec(env,ws,key,spec,actor,purpose){for(const n of vaultDeployNames(spec)){const r=await vaultUse(env,ws,key,n,actor,purpose);if(r&&r.row.kind===spec[1])return r}return null}

