const GOOGLE_LOGIN_TARGETS=[
 {key:'pz',project:'Project Zero',worker:'projectzero-commercial',origin:'https://account.projectzero.work',start:'/auth/login',callback:'https://account.projectzero.work/auth/google/callback',id:'PZW_GOOGLE_CLIENT_ID',secret:'PZW_GOOGLE_CLIENT_SECRET',home:'https://www.projectzero.work',note:'Owner-only access; provisioning never changes the audience.'},
 {key:'apt',project:'SiteAPT',worker:'statatlas-web',origin:'https://account.siteapt.app',start:'/auth/google',callback:'https://account.statatlas.app/auth/google/callback',id:'GOOGLE_CLIENT_ID',secret:'GOOGLE_CLIENT_SECRET',home:'https://siteapt.app',note:'Existing legacy callback is intentionally preserved. Do not remove the statatlas.app authorization until its migration is released.'},
 {key:'hum',project:'Humperdinck',worker:'humperdinck',origin:'https://humperdinck.studio',start:'/api/account/start/google',callback:'https://humperdinck.studio/api/account/callback/google',id:'GOOGLE_CLIENT_ID',secret:'GOOGLE_CLIENT_SECRET',home:'https://humperdinck.studio'},
 {key:'grim',project:'Grim Thread',worker:'grim-accounts',origin:'https://account.thegrimthread.com',start:'/auth/google/start',callback:'https://account.thegrimthread.com/auth/google/callback',id:'GRIM_GOOGLE_CLIENT_ID',secret:'GRIM_GOOGLE_CLIENT_SECRET',home:'https://thegrimthread.com'},
 {key:'owl',project:'Story Owl',worker:'storyowl-preview',origin:'https://www.thestoryowl.com',start:'/auth/google',callback:'https://www.thestoryowl.com/auth/google/callback',id:'GOOGLE_CLIENT_ID',secret:'GOOGLE_CLIENT_SECRET',home:'https://www.thestoryowl.com'},
 {key:'yarr',project:'Yarr',worker:'yarr',origin:'https://accounts.yarr.media',start:'/auth/google/start',callback:'https://accounts.yarr.media/auth/google/callback',id:'GOOGLE_CLIENT_ID',secret:'GOOGLE_CLIENT_SECRET',home:'https://yarr.media'}
];
const googleTarget=k=>GOOGLE_LOGIN_TARGETS.find(t=>t.key===k);
const googleSecretName=t=>'google-login-'+t.key;
const GOOGLE_HEALTH_KEY='private/integrations/google-login-health-v1.json';
function googleClientConfig(raw,target){
 let parsed;try{parsed=JSON.parse(raw)}catch{throw new ChamberError('Enter the Google Web application client JSON.')}
 const x=parsed?.web||parsed;
 if(!x||typeof x.client_id!=='string'||! /^[A-Za-z0-9_-]{8,240}\.apps\.googleusercontent\.com$/.test(x.client_id)||typeof x.client_secret!=='string'||! /^[A-Za-z0-9_-]{12,200}$/.test(x.client_secret))throw new ChamberError('Invalid Web application client ID or secret.');
 if(!Array.isArray(x.redirect_uris)||!x.redirect_uris.includes(target.callback))throw new ChamberError('The client JSON must include this project’s exact authorized redirect URI.');
 return {client_id:x.client_id,client_secret:x.client_secret,redirect_uris:[target.callback]};
}
export async function googleLoginProbe(target,request=fetch){
 const time=new Date().toISOString();
 try{
  const r=await request(target.origin+target.start,{method:'GET',redirect:'manual',headers:{'Cache-Control':'no-cache'},signal:AbortSignal.timeout(12000)});
  const location=r.headers.get('Location');if(!location)return {state:r.status===503?'Not ready':'Unverified',at:time,detail:'Start endpoint returned HTTP '+r.status};
  const u=new URL(location,target.origin);
  if(u.origin!=='https://accounts.google.com'||u.pathname!=='/o/oauth2/v2/auth'||!['301','302','303','307','308'].includes(String(r.status)))return {state:'Unverified',at:time,detail:'Start endpoint did not redirect to Google'};
  if(u.searchParams.get('redirect_uri')!==target.callback)return {state:'Needs review',at:time,detail:'Callback differs from the reviewed configuration'};
  const scope=(u.searchParams.get('scope')||'').split(/\s+/);
  if(!u.searchParams.get('client_id')?.endsWith('.apps.googleusercontent.com')||u.searchParams.get('response_type')!=='code'||!u.searchParams.get('state')||!scope.includes('openid'))return {state:'Needs review',at:time,detail:'OAuth authorization parameters incomplete'};
  return {state:'Redirect ready',at:time,detail:'Google authorization redirect and exact callback observed; consent and token exchange not tested'};
 }catch{return {state:'Unavailable',at:time,detail:'Endpoint could not be reached'}}
}
async function googleHealthRead(env){try{return await (await env.BRAND_FILES.get(GOOGLE_HEALTH_KEY))?.json()||{}}catch{return {}}}
async function googleTask(env,project,detail,incident=false){
 const now=new Date().toISOString(),target=GOOGLE_LOGIN_TARGETS.find(x=>x.project===project);
 const info=await env.TRACKER.prepare('SELECT project,repository FROM tracker_active_projects WHERE project=?').bind(project).first();
 if(!info)throw new ChamberError('Select an active tracker project.');
 const title='Google sign-in — '+(incident?'investigate authentication configuration':'configure and verify authentication');
 const id=(target?'AUTH-'+target.key.toUpperCase():'AUTH-'+(await vaultSha(project)).slice(0,12))+(incident?'-HEALTH-'+now.slice(0,10):'-SETUP');
 const open=await env.TRACKER.prepare("SELECT task_id FROM tracker_active_tasks WHERE project=? AND task=? AND status NOT IN ('Done','Deferred') LIMIT 1").bind(project,title).first();
 if(open)return open.task_id;
 await env.TRACKER.prepare("INSERT INTO tracker_tasks(project,task_id,priority,task,status,owner,due_date,source_updated,evidence,notes,repository,revision,updated_at,updated_by) VALUES(?,?,'P0',?,'Not started','Unassigned','','Google login manager','',?,?,1,?,'Project Zero') ON CONFLICT(task_id) DO NOTHING").bind(project,id,title,detail,info.repository||'',now).run();
 return id;
}
async function googleHealthRefresh(env,only=null){
 const previous=await googleHealthRead(env),next={...previous};
 const targets=only?[only]:GOOGLE_LOGIN_TARGETS;
 await Promise.all(targets.map(async t=>{
  const check=await googleLoginProbe(t),bad=['Not ready','Needs review'].includes(check.state);
  check.failures=bad?((Number(previous[t.key]?.failures)||0)+(previous[t.key]?.at&&Date.now()-Date.parse(previous[t.key].at)<30*60000?0:1)):0;
  if(check.failures>=2&&(!previous[t.key]?.at||Date.now()-Date.parse(previous[t.key].at)>1000*60*30)){try{check.task=await googleTask(env,t.project,check.detail+'. Inspect the reviewed OAuth callback, bindings and secure session flow. Do not rotate credentials or change the user audience automatically.',true)}catch{check.task='Tracker unavailable'}}
  next[t.key]=check;
 }));
 await env.BRAND_FILES.put(GOOGLE_HEALTH_KEY,JSON.stringify(next),{httpMetadata:{contentType:'application/json'}});
 return next;
}
// The bulk endpoint applies the two credentials together, leaving unrelated bindings untouched.
// It is intentionally new-install only: credential rotation requires a separate reviewed release.
export async function googleInstallPair(target,config,request){
 const forbidden=new Set([target.id,target.secret,'GOOGLE_CLIENT_ID','GOOGLE_CLIENT_SECRET','PZW_GOOGLE_CLIENT_ID','PZW_GOOGLE_CLIENT_SECRET','GRIM_GOOGLE_CLIENT_ID','GRIM_GOOGLE_CLIENT_SECRET']);
 const settings=await request('GET','settings');
 if(!Array.isArray(settings?.bindings))throw new ChamberError('Worker binding inventory unavailable.',503);
 if(settings.bindings.some(b=>forbidden.has(b.name)))throw new ChamberError('Existing or partial Google credentials are present; no changes made.',409);
 await request('PATCH','secrets-bulk',{secrets:{[target.id]:{name:target.id,type:'secret_text',text:config.client_id},[target.secret]:{name:target.secret,type:'secret_text',text:config.client_secret}}});
 const after=await request('GET','settings');
 if(![target.id,target.secret].every(name=>after?.bindings?.some(b=>b.name===name&&b.type==='secret_text')))throw new ChamberError('Installation could not be verified. Inspect Worker bindings before retrying.',503);
}
async function googleInstall(env,t){
 const ws=VAULT_WORKSPACE,key=await vaultKey(env,ws),name=googleSecretName(t),lock='deploy:'+t.worker;
 if(!key)throw new ChamberError('Chamber is locked.',503);
 if(!await chamberLock(env,lock,'Owner:'+crypto.randomUUID()))throw new ChamberError('Another deployment is active.',409);
 try{
  const [cred,tok,acct]=await Promise.all([vaultUse(env,ws,key,name,'Owner','Google credential installation',r=>r.kind==='other'&&r.project===t.project),vaultUseSpec(env,ws,key,VAULT_DEPLOY_SECRETS[0],'Owner','Google credential installation'),vaultUseSpec(env,ws,key,VAULT_DEPLOY_SECRETS[1],'Owner','Google credential installation')]);
  if(!cred||!tok||!acct)throw new ChamberError('Store this Google client and Cloudflare deploy credentials first.');
  const config=googleClientConfig(cred.value,t);
  if(!/^[0-9a-f]{32}$/.test(acct.value))throw new ChamberError('Invalid Cloudflare account ID.');
  if(!await vaultAudit(env,ws,cred.row,'Preflight','Owner','New Google credential installation · '+t.worker))throw new ChamberError('Audit unavailable; no changes made.',503);
  const request=async(method,path,body)=>{
   try{return await chamberCfJson(tok.value,acct.value,t.worker+'/'+path,{method,...(body?{headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})})}
   catch{throw new ChamberError('Cloudflare operation failed; inspect binding metadata before retrying.',503)}
  };
  await googleInstallPair(t,config,request);
  await vaultAudit(env,ws,cred.row,'Updated','Owner','Google credential bindings installed and observed · '+t.worker);
 }finally{await env.PORTFOLIO.prepare('DELETE FROM vault_locks WHERE name=?').bind(lock).run()}
}
async function googleManagerPage(env,notice='',status=200){
 const [health,rows,projects,key]=await Promise.all([googleHealthRead(env),safeRows(env.PORTFOLIO,"SELECT name,project,kind FROM vault_secrets WHERE workspace_id=? AND status='Active'",VAULT_WORKSPACE),safeRows(env.TRACKER,'SELECT project FROM tracker_active_projects ORDER BY project'),vaultKey(env,VAULT_WORKSPACE)]);
 const card=t=>{
  const h=health[t.key],stored=rows?.some(r=>r.name===googleSecretName(t)&&r.project===t.project&&r.kind==='other');
  const field=(name,value)=>'<dt>'+esc(name)+'</dt><dd><code>'+esc(value)+'</code></dd>';
  const action=(mode,label)=>'<form method="post" action="/integrations/google-login"><input type="hidden" name="project" value="'+esc(t.key)+'"><input type="hidden" name="action" value="'+mode+'"><button type="submit">'+label+'</button></form>';
  return '<section class="ch-card"><div class="ch-head"><h3>'+esc(t.project)+'</h3><span class="ch-pill '+(h?.state==='Redirect ready'?'ok':'')+'">'+esc(h?.state||'Not checked')+'</span></div><p class="ch-meta">'+esc(h?.detail||'Run a check to inspect the public authorization redirect.')+' '+esc(h?.at||'')+(h?.task?' · '+esc(h.task):'')+'</p><dl>'+field('Homepage',t.home)+field('Authorized origin',t.origin)+field('Authorized redirect URI',t.callback)+field('Worker',t.worker)+field('Bindings',t.id+' / '+t.secret)+'</dl><p>'+esc(t.note||'Use a separate Google OAuth client for this business.')+'</p><p><a href="https://console.cloud.google.com/auth/clients" rel="noreferrer">Open Google Auth Platform ↗</a> · <a href="'+esc(t.origin+t.start)+'" rel="noreferrer">Test sign-in in browser ↗</a></p><div class="ch-two">'+action('check','Check redirect')+action('task','Create setup task')+'</div><details><summary>'+ (stored?'Credentials stored in Chamber':'Import Google credentials')+'</summary><p class="ch-meta">Download the Web application client JSON from Google after registering the exact redirect above. Existing deployed credentials are not changed. Rotate stored credentials in the Chamber.</p>'+(stored?'<a href="/secrets">Open Chamber of Secrets</a><form class="ch-form" method="post" action="/integrations/google-login"><input type="hidden" name="project" value="'+esc(t.key)+'"><input type="hidden" name="action" value="install"><label class="check"><input type="checkbox" name="confirm" value="yes" required> Install only if neither credential exists. This creates a Worker version; existing bindings will never be replaced.</label><button type="submit">Install new credentials</button></form>':key&&rows!==null?'<form method="post" class="ch-form" action="/integrations/google-login" autocomplete="off"><input type="hidden" name="project" value="'+esc(t.key)+'"><input type="hidden" name="action" value="import"><label>Web client JSON<textarea name="credentials" required maxlength="10000" spellcheck="false" autocomplete="off"></textarea></label><label class="check"><input type="checkbox" name="confirm" value="yes" required> Store encrypted credentials for this business only.</label><button type="submit">Store in Chamber</button></form>':'<p>Chamber unavailable.</p>')+'</details></section>';
 };
 const body='<div class="ch-grid"><p><a href="/integrations">← Integrations</a> · <a href="/secrets">Chamber of Secrets</a></p><h2>Google login manager</h2>'+(notice?'<p role="status">'+esc(notice)+'</p>':'')+'<p>Independent Google clients, exact callback configuration, encrypted credentials and automated redirect checks. A successful check is not a complete customer login. Google client creation and consent verification are completed in Google Auth Platform. No existing Worker credentials or access policies are overwritten.</p><form method="post" action="/integrations/google-login"><input type="hidden" name="action" value="check-all"><button type="submit">Check all projects</button></form><div class="ch-grid">'+GOOGLE_LOGIN_TARGETS.map(card).join('')+'</div><section class="ch-card"><h3>Provision a future project</h3><form class="ch-form" method="post" action="/integrations/google-login"><input type="hidden" name="action" value="future"><label>Active project<select name="future_project">'+(projects||[]).filter(p=>!GOOGLE_LOGIN_TARGETS.some(t=>t.project===p.project)).map(p=>'<option>'+esc(p.project)+'</option>').join('')+'</select></label><button type="submit">Create P0 provisioning task</button></form><p class="ch-meta">New projects need a reviewed domain, Worker, callback and session implementation before credentials can be installed.</p></section></div>';
 return response(formPage('Google login manager',body).replace('</head>','<style>'+CHAMBER_CSS+'.ch-card dl{display:grid;gap:4px;overflow-wrap:anywhere}.ch-card dt{font-size:12px;color:#656b74}.ch-card dd{margin:0 0 8px}</style></head>'),status,'text/html;charset=utf-8');
}
async function googleManagerPost(req,env){
 if(!sameOriginPost(req)||!req.headers.get('content-type')?.startsWith('application/x-www-form-urlencoded'))return response('Forbidden',403);
 if(Number(req.headers.get('Content-Length')||0)>32000)return response('Too large',413);const raw=await req.text();if(raw.length>32000)return response('Too large',413);
 const f=new URLSearchParams(raw),action=f.get('action'),t=googleTarget(f.get('project'));
 try{
  if(action==='check-all'||action==='check'&&t){await googleHealthRefresh(env,action==='check'?t:null);return googleManagerPage(env,'Redirect checks refreshed.')}
  if(action==='future'||action==='task'&&t){const id=await googleTask(env,t?.project||f.get('future_project'),t?'Review '+t.origin+t.start+' and '+t.callback+'; use separate Google credentials in the Chamber and existing approved deployment process. Verify login, logout, account isolation, CSRF, token validation and session expiry. Never overwrite current credentials or enable public signup without approval.':'Review project source and domain; establish secure Google authorization code flow with PKCE, state, nonce, token validation, sessions, logout and rate limits. Generate exact HTTPS callback and branding configuration; use separate Web client and Chamber credentials; test before approved release.');return googleManagerPage(env,'Tracker task: '+id);}
  if(action==='install'&&t&&f.get('confirm')==='yes'){await googleInstall(env,t);return googleManagerPage(env,'New bindings installed and verified. Complete a real Google sign-in test before marking authentication ready.')}
  if(action==='import'&&t&&f.get('confirm')==='yes'){
   const key=await vaultKey(env,VAULT_WORKSPACE);if(!key)throw new ChamberError('Chamber is locked.',503);
   const config=googleClientConfig(f.get('credentials'),t),value=JSON.stringify(config),id=crypto.randomUUID(),name=googleSecretName(t),at=new Date().toISOString(),secret={id,name},kind='other';
   // Keep secrets scoped; do not expose a client ID, secret or raw input even on failure.
   const count=await env.PORTFOLIO.prepare("SELECT COUNT(*) n FROM vault_secrets WHERE workspace_id=? AND status='Active'").bind(VAULT_WORKSPACE).first();if(Number(count?.n)>=100)throw new ChamberError('The Chamber is full.',409);
   if(await vaultLoad(env,VAULT_WORKSPACE,name))throw new ChamberError('Credentials already stored. Use the Chamber rotation workflow.',409);
   const sealed=await vaultSeal(key,VAULT_WORKSPACE,id,kind,value);
   await env.PORTFOLIO.batch([env.PORTFOLIO.prepare('INSERT INTO vault_secrets(id,workspace_id,name,project,kind,ciphertext,iv,hint,bytes,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)').bind(id,VAULT_WORKSPACE,name,t.project,kind,sealed.ciphertext,sealed.iv,'Google Web client',vaultEnc.encode(value).length,at,at),vaultAuditStmt(env,VAULT_WORKSPACE,secret,'Created','Owner','Google Web client · '+t.project,at)]);
   return googleManagerPage(env,'Google credentials stored securely. Live authentication is unchanged.');
  }
  return response('Invalid request',400);
 }catch(e){return googleManagerPage(env,e instanceof ChamberError?e.message:'Google login operation unavailable; review the Chamber or tracker and retry.',e instanceof ChamberError?e.status:503)}
}

// ---- Owner pages ----
const CHAMBER_CSS='.ch-grid{display:grid;gap:14px}.ch-card{background:#fff;border:1px solid #e2e4e8;border-radius:12px;padding:14px}.ch-card h3{margin:0 0 10px;font-size:15px}.ch-form{display:grid;gap:10px}.ch-form label{display:grid;gap:4px;font-size:13px;font-weight:600}.ch-form input,.ch-form select,.ch-form textarea{font:14px system-ui;padding:9px 10px;border:1px solid #cfd3d9;border-radius:8px;background:#fff;min-height:42px;width:100%;box-sizing:border-box}.ch-form textarea{min-height:90px;font-family:ui-monospace,monospace;-webkit-text-security:disc}.ch-form .check{display:flex;gap:8px;align-items:flex-start;font-weight:500}.ch-form .check input{width:auto;min-height:0}.ch-form button,.ch-row button{min-height:42px;padding:8px 14px;border:0;border-radius:8px;background:#191919;color:#fff;font:600 13px system-ui;cursor:pointer}.ch-two{display:grid;gap:10px;grid-template-columns:repeat(auto-fit,minmax(180px,1fr))}.ch-list{display:grid;gap:8px}.ch-row{display:grid;gap:6px;border:1px solid #e2e4e8;border-radius:10px;padding:10px 12px;background:#fff}.ch-row.revoked{opacity:.6}.ch-head{display:flex;flex-wrap:wrap;gap:6px 10px;align-items:center}.ch-head strong{font-size:15px;overflow-wrap:anywhere}.ch-head code{font-size:12px;color:#656b74}.ch-pill{padding:1px 8px;border-radius:9px;background:#eef0f3;font-size:11px;font-weight:650}.ch-pill.ok{background:#e1f2e6;color:#1d5e33}.ch-pill.off{background:#f6e3e1;color:#8a2b20}.ch-meta{font-size:12px;color:#656b74}.ch-row details summary{cursor:pointer;font-size:13px;font-weight:600;padding:4px 0}.ch-row details[open]{padding-bottom:4px}.ch-need{display:grid;gap:6px;margin:0;padding:0;list-style:none}.ch-need li{display:flex;gap:8px;align-items:baseline;font-size:13px}.ch-need code{font-size:12px}.ch-audit{width:100%;border-collapse:collapse;font-size:12px}.ch-audit td,.ch-audit th{padding:6px 4px;border-bottom:1px solid #eef0f3;text-align:left;vertical-align:top}.ch-audit td:last-child{overflow-wrap:anywhere}@media(max-width:600px){.ch-audit th:nth-child(4),.ch-audit td:nth-child(4){display:none}}';
function chamberProjects(){return ['Shared systems',...new Set(['Project Zero',...PROJECTS.map(p=>p.name)])]}
async function chamberPage(env,problem){const ws=VAULT_WORKSPACE;const [rows,audit,key]=await Promise.all([safeRows(env.PORTFOLIO,'SELECT id,name,project,kind,hint,bytes,status,revision,created_at,updated_at,revoked_at,last_used_at,last_used_by FROM vault_secrets WHERE workspace_id=? ORDER BY status,name LIMIT 200',ws),safeRows(env.PORTFOLIO,'SELECT secret_name,action,actor,at,detail FROM vault_audit WHERE workspace_id=? ORDER BY id DESC LIMIT 40',ws),vaultKey(env,ws)]);const when=v=>v?esc(String(v).slice(0,16).replace('T',' ')):'—';let html=problem?'<p class="warn" role="alert">'+esc(problem)+'</p>':'';if(!key)html+='<p class="warn">The Chamber is locked: the <code>VAULT_MASTER_KEY</code> Worker secret is missing or invalid. Set it to 32 random bytes in base64 (for example <code>openssl rand -base64 32</code>) on the portfolio-owner Worker. Store a backup offline; losing it makes stored values unrecoverable.</p>';if(rows===null)html+='<p class="warn">Chamber storage is not initialized. Apply <code>schema/migrations/006-secret-chamber.sql</code> to the owner database.</p>';const active=new Map((rows||[]).filter(r=>r.status==='Active').map(r=>[r.name,r]));html+='<p><a href="/integrations/google-login">Google login manager ↗</a> · <a href="/integrations/mcp">MCP integration ↗</a></p>';html+='<div class="ch-grid"><section class="ch-card" aria-labelledby="ch-deploy"><h3 id="ch-deploy">Agent deploy readiness</h3><ul class="ch-need">'+VAULT_DEPLOY_SECRETS.map(spec=>{const [name,kind,desc,req]=spec;const names=vaultDeployNames(spec);const r=names.map(n=>active.get(n)).find(x=>x&&x.kind===kind);return '<li><span class="ch-pill '+(r?'ok':req?'off':'')+'">'+(r?'Stored':req?'Missing':'Optional')+'</span><span><code>'+esc(r?r.name:name)+'</code> · '+esc(desc)+(r?'':' (name: '+names.join(' or ')+')')+'</span></li>'}).join('')+'</ul><p class="ch-meta">Agents call <code>POST /api/agent/deploy</code> with their tracker API key. They can deploy only commits merged to main with passing checks, after live drift checks, and never see these values.</p></section>';
html+='<section class="ch-card" aria-labelledby="ch-stripe"><h3 id="ch-stripe">Stripe reporting connections</h3><ul class="ch-need">'+STRIPE_SOURCES.map(spec=>{const r=active.get(spec[2]),ready=stripeChamberMatch(r,spec);return '<li><span class="ch-pill '+(ready?'ok':'off')+'">'+(ready?'Stored':'Missing')+'</span><span><code>'+esc(spec[2])+'</code> · '+esc(stripeChamberProject(spec))+'</span></li>'}).join('')+'</ul><p class="ch-meta">Add each connection below using Kind: Stripe key and the matching project. Existing correctly named Shared systems entries are also supported, including owner-approved existing standard live keys verified against the pinned account. New entries use JSON with <code>account_id</code> and <code>api_key</code> (restricted live key recommended and required for new entries). Standard keys have broader permissions; this sync only uses GET balance and account identity requests. Values remain encrypted; synchronization uses the Chamber audit log. <a href="/finance/sources">View finance sync status</a>.</p></section>';
if(key&&rows!==null)html+='<section class="ch-card" aria-labelledby="ch-add"><h3 id="ch-add">Add a secret</h3><form class="ch-form" method="post" action="/secrets/create" autocomplete="off"><div class="ch-two"><label>Name<input name="name" required maxlength="80" pattern="[A-Za-z0-9][A-Za-z0-9 ._\\-]{0,79}" placeholder="cloudflare-deploy-token" list="ch-names"></label><label>Kind<select name="kind">'+Object.entries(VAULT_KINDS).map(([k,l])=>'<option value="'+k+'">'+esc(l)+'</option>').join('')+'</select></label><label>Project<select name="project">'+chamberProjects().map(p=>'<option>'+esc(p)+'</option>').join('')+'</select></label></div><datalist id="ch-names">'+[...VAULT_DEPLOY_SECRETS.flatMap(vaultDeployNames),...STRIPE_SOURCES.map(s=>s[2])].map(n=>'<option value="'+esc(n)+'">').join('')+'</datalist><label>Value<textarea name="value" required maxlength="65536" spellcheck="false" autocapitalize="off" autocomplete="off"></textarea></label><label class="check"><input type="checkbox" name="confirm" value="yes" required> Store this encrypted value for Project Zero automation. It will not be shown again.</label><button type="submit">Store secret</button></form></section>';
html+='<section class="ch-card" aria-labelledby="ch-list"><h3 id="ch-list">Stored secrets</h3>'+(!rows||!rows.length?'<p class="ch-meta">No secrets stored yet.</p>':'<div class="ch-list">'+rows.map(r=>{const live=r.status==='Active';return '<article class="ch-row'+(live?'':' revoked')+'"><div class="ch-head"><strong>'+esc(r.name)+'</strong><span class="ch-pill">'+esc(VAULT_KINDS[r.kind]||r.kind)+'</span><span class="ch-pill '+(live?'ok':'off')+'">'+esc(r.status)+'</span>'+(r.hint?'<code>'+esc(r.hint)+'</code>':'')+'</div><div class="ch-meta">'+esc(r.project||'Shared systems')+' · updated '+when(r.updated_at)+' · last used '+(r.last_used_at?when(r.last_used_at)+' by '+esc(r.last_used_by||'unknown'):'never')+(live?'':' · revoked '+when(r.revoked_at))+'</div>'+(live&&key?'<details><summary>Replace value</summary><form class="ch-form" method="post" action="/secrets/rotate" autocomplete="off"><input type="hidden" name="id" value="'+esc(r.id)+'"><input type="hidden" name="revision" value="'+esc(r.revision)+'"><label>New value<textarea name="value" required maxlength="65536" spellcheck="false" autocapitalize="off"></textarea></label><button type="submit">Replace</button></form></details>':'')+(live?'<details><summary>Revoke</summary><form class="ch-form" method="post" action="/secrets/revoke"><input type="hidden" name="id" value="'+esc(r.id)+'"><input type="hidden" name="revision" value="'+esc(r.revision)+'"><label>Type <code>'+esc(r.name)+'</code> to permanently delete the stored value<input name="confirm_name" required autocomplete="off"></label><button type="submit">Revoke secret</button></form></details>':'')+'</article>'}).join('')+'</div>')+'</section>';
html+='<section class="ch-card" aria-labelledby="ch-audit"><h3 id="ch-audit">Audit log</h3>'+(!audit||!audit.length?'<p class="ch-meta">No activity yet.</p>':'<table class="ch-audit"><thead><tr><th>UTC</th><th>Secret</th><th>Action</th><th>Actor</th><th>Detail</th></tr></thead><tbody>'+audit.map(a=>'<tr><td>'+when(a.at)+'</td><td>'+esc(a.secret_name||'—')+'</td><td>'+esc(a.action)+'</td><td>'+esc(a.actor)+'</td><td>'+esc(a.detail||'')+'</td></tr>').join('')+'</tbody></table>')+'</section></div>';
return formPage('Chamber of Secrets',html).replace('</head>','<style>'+CHAMBER_CSS+'</style></head>')}
async function chamberPost(req,env,path){if(!sameOriginPost(req)||!req.headers.get('content-type')?.startsWith('application/x-www-form-urlencoded'))return response('Forbidden',403);const max=220000;if(Number(req.headers.get('Content-Length')||0)>max)return response('Too large',413);const raw=await req.text();if(raw.length>max)return response('Too large',413);const f=new URLSearchParams(raw),ws=VAULT_WORKSPACE,actor='Owner';const done=n=>new Response(null,{status:303,headers:{...headers,Location:'/secrets?notice='+n}});const fail=async(msg,status=400)=>response(await chamberPage(env,msg),status,'text/html;charset=utf-8');try{
if(path==='/secrets/revoke'){const id=f.get('id')||'',rev=Number(f.get('revision'));const row=await env.PORTFOLIO.prepare("SELECT id,name,revision FROM vault_secrets WHERE id=? AND workspace_id=? AND status='Active'").bind(id,ws).first();if(!row||row.revision!==rev)return fail('That secret changed or no longer exists. Review it and try again.',409);if((f.get('confirm_name')||'')!==row.name)return fail('Type the secret name exactly to revoke it.');const at=new Date().toISOString();const r=await env.PORTFOLIO.batch([env.PORTFOLIO.prepare("UPDATE vault_secrets SET status='Revoked',ciphertext='',iv='',hint='',revoked_at=?,updated_at=?,revision=revision+1 WHERE id=? AND workspace_id=? AND revision=? AND status='Active'").bind(at,at,row.id,ws,rev),vaultAuditStmt(env,ws,row,'Revoked',actor,'Stored value deleted',at)]);if(r[0]?.meta?.changes!==1)return fail('That secret changed. Review it and try again.',409);return done('revoked')}
const key=await vaultKey(env,ws);if(!key)return fail('The Chamber is locked. Set VAULT_MASTER_KEY first.',503);
if(path==='/secrets/create'){if(f.get('confirm')!=='yes')return fail('Confirm that the value should be stored.');const name=(f.get('name')||'').trim(),kind=f.get('kind')||'',project=f.get('project')||'';if(!/^[A-Za-z0-9][A-Za-z0-9 ._-]{0,79}$/.test(name))return fail('Names use letters, numbers, spaces, dots, dashes and underscores (up to 80).');if(!VAULT_KINDS[kind])return fail('Choose a secret kind.');if(!chamberProjects().includes(project))return fail('Choose a project.');if(GOOGLE_LOGIN_TARGETS.some(t=>googleSecretName(t)===name))return fail('Import Google Web clients through the Google login manager.');const required=VAULT_DEPLOY_SECRETS.find(spec=>vaultDeployNames(spec).includes(name));if(required&&required[1]!==kind)return fail(name+' must be stored as '+VAULT_KINDS[required[1]]+'.');const stripeSpec=stripeChamberSpec(name);if(stripeSpec&&(kind!=='stripe-key'||project!==stripeChamberProject(stripeSpec)))return fail('This Stripe connection requires kind Stripe key and project '+stripeChamberProject(stripeSpec)+'.');const value=vaultValidate(kind,f.get('value'),name);const id=crypto.randomUUID(),at=new Date().toISOString();const sealed=await vaultSeal(key,ws,id,kind,value);const secret={id,name};const count=await env.PORTFOLIO.prepare("SELECT COUNT(*) n FROM vault_secrets WHERE workspace_id=? AND status='Active'").bind(ws).first();if(Number(count?.n)>=100)return fail('The Chamber holds up to 100 active secrets. Revoke unused secrets first.');try{await env.PORTFOLIO.batch([env.PORTFOLIO.prepare('INSERT INTO vault_secrets(id,workspace_id,name,project,kind,ciphertext,iv,hint,bytes,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)').bind(id,ws,name,project,kind,sealed.ciphertext,sealed.iv,vaultHint(kind,value,name),vaultEnc.encode(value).length,at,at),vaultAuditStmt(env,ws,secret,'Created',actor,VAULT_KINDS[kind]+' · '+project,at)])}catch{return fail('An active secret named '+name+' already exists. Replace or revoke it instead.',409)}return done('created')}
if(path==='/secrets/rotate'){const id=f.get('id')||'',rev=Number(f.get('revision'));const row=await env.PORTFOLIO.prepare("SELECT * FROM vault_secrets WHERE id=? AND workspace_id=? AND status='Active'").bind(id,ws).first();if(!row||row.revision!==rev)return fail('That secret changed or no longer exists. Review it and try again.',409);const stripeSpec=stripeChamberSpec(row.name);if(stripeSpec&&!stripeChamberMatch(row,stripeSpec))return fail('Revoke and recreate this Stripe connection with the correct kind and project.');const value=vaultValidate(row.kind,f.get('value'),row.name);const sealed=await vaultSeal(key,ws,row.id,row.kind,value),at=new Date().toISOString();const r=await env.PORTFOLIO.batch([env.PORTFOLIO.prepare("UPDATE vault_secrets SET ciphertext=?,iv=?,hint=?,bytes=?,revision=revision+1,updated_at=? WHERE id=? AND workspace_id=? AND revision=? AND status='Active'").bind(sealed.ciphertext,sealed.iv,vaultHint(row.kind,value,row.name),vaultEnc.encode(value).length,at,row.id,ws,rev),vaultAuditStmt(env,ws,row,'Rotated',actor,'Value replaced',at)]);if(r[0]?.meta?.changes!==1)return fail('That secret changed. Review it and try again.',409);return done('rotated')}
return response('Not found',404)}catch(e){if(e instanceof ChamberError)return fail(e.message,e.status);return fail('The Chamber is temporarily unavailable. Nothing was changed.',503)}}
async function chamberRoute(req,env,url){if(req.method==='POST'&&['/secrets/create','/secrets/rotate','/secrets/revoke'].includes(url.pathname))return chamberPost(req,env,url.pathname);if(url.pathname!=='/secrets')return response('Not found',404);if(!['GET','HEAD'].includes(req.method))return response('Method not allowed',405);return response(req.method==='HEAD'?null:portfolioFlash(await chamberPage(env),url),200,'text/html;charset=utf-8')}

// ---- Agent deploy broker ----
const agentJson=(x,status=200)=>new Response(JSON.stringify(x),{status,headers:{'Content-Type':'application/json;charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
async function agentAuth(req,env){const m=(req.headers.get('Authorization')||'').match(/^Bearer (ptk_[0-9a-f]{64})$/);if(!m||!env.TRACKER)return null;return env.TRACKER.prepare('SELECT id,actor FROM tracker_api_keys WHERE token_hash=? AND revoked_at IS NULL AND expires_at>?').bind(await vaultSha(m[1]),new Date().toISOString()).first()}
async function chamberGitHub(path,token,raw){const url=raw?'https://raw.githubusercontent.com/'+VAULT_REPO+path:'https://api.github.com/repos/'+VAULT_REPO+path;const r=await fetch(url,{headers:{'User-Agent':'projectzero-chamber','Accept':raw?'text/plain':'application/vnd.github+json',...(token?{Authorization:'Bearer '+token}:{})}});if(!r.ok)throw new ChamberError('GitHub returned '+r.status+' for '+(raw?'source':path.split('?')[0]),502);if(raw){const t=await r.text();if(t.length>5000000)throw new ChamberError('Worker source is too large',413);return t}return r.json()}
async function chamberCf(token,account,path,init={}){const r=await fetch('https://api.cloudflare.com/client/v4/accounts/'+account+'/workers/scripts/'+path,{...init,headers:{Authorization:'Bearer '+token,...(init.headers||{})}});return r}
async function chamberCfJson(token,account,path,init){const r=await chamberCf(token,account,path,init);let j=null;try{j=await r.json()}catch{}if(!r.ok||!j?.success)throw new ChamberError('Cloudflare API '+path.split('/').slice(1).join('/')+' failed ('+r.status+(j?.errors?.[0]?.message?': '+String(j.errors[0].message).slice(0,160):'')+')',502);return j.result}
async function chamberLiveSource(token,account,name){const r=await chamberCf(token,account,name+'/content/v2');if(!r.ok)throw new ChamberError('Cloudflare API content failed ('+r.status+')',502);const type=r.headers.get('content-type')||'';if(type.includes('multipart/form-data')){const form=await r.formData();const entry=r.headers.get('cf-entrypoint');const files=[...form.entries()].filter(([,v])=>typeof v!=='string');const file=(entry&&files.find(([k,v])=>k===entry||v.name===entry))||files[0];if(!file||files.length!==1)throw new ChamberError('Live Worker is not a single module; reconcile manually',409);return file[1].text()}return r.text()}
function chamberRestore(template,replacements){let out=template;for(const [k,v] of Object.entries(replacements||{})){if(!/^__PZ_CONFIG_\d{3}__$/.test(k)||typeof v!=='string')throw new ChamberError('Invalid manifest replacement',412);out=out.split(k).join(v)}if(/__PZ_CONFIG_\d{3}__/.test(out))throw new ChamberError('Unresolved configuration placeholder; update the build manifest',412);return out}
async function chamberCommitMatches(rev,name,entry,liveSha,ghTok){let tpl;try{tpl=await chamberGitHub('/'+rev+'/workers/'+name+'/worker.mjs',ghTok,true)}catch{return false}try{if(await vaultSha(chamberRestore(tpl,entry.replacements))===liveSha)return true}catch{}return await vaultSha(tpl)===liveSha}
async function chamberObserve(token,account,name,entry,ghTok){const [source,settings,schedules,deployments]=await Promise.all([chamberLiveSource(token,account,name),chamberCfJson(token,account,name+'/settings'),chamberCfJson(token,account,name+'/schedules'),chamberCfJson(token,account,name+'/deployments')]);const dep=deployments?.deployments?.[0];if(!dep||!Array.isArray(dep.versions)||dep.versions.length!==1||dep.versions[0].percentage!==100)throw new ChamberError('Expected one active version at 100%; finish or roll back the gradual deployment first',409);const versionId=dep.versions[0].version_id,sourceSha=await vaultSha(source);
const detail=await chamberCfJson(token,account,name+'/versions/'+versionId).catch(()=>null);const tag=detail?.annotations?.['workers/tag']||detail?.metadata?.annotations?.['workers/tag']||'';let baseline;
if(/^[0-9a-f]{40}$/.test(tag)){if(!await chamberCommitMatches(tag,name,entry,sourceSha,ghTok))throw new ChamberError('Production source differs from its tagged commit '+tag.slice(0,12)+'; reconcile before releasing',409);baseline='tagged commit '+tag.slice(0,12)}
else if(sourceSha===entry.source_sha256)baseline='manifest source_sha256';
else{const commits=await chamberGitHub('/commits?sha=main&per_page=10&path='+encodeURIComponent('workers/'+name+'/worker.mjs'),ghTok);let match='';for(const c of (Array.isArray(commits)?commits:[])){if(/^[0-9a-f]{40}$/.test(c?.sha||'')&&await chamberCommitMatches(c.sha,name,entry,sourceSha,ghTok)){match=c.sha;break}}if(!match)throw new ChamberError('Production source ('+sourceSha.slice(0,12)+') matches none of the last 10 commits of this Worker; reconcile before releasing',409);baseline='untagged; matches commit '+match.slice(0,12)}
const secretTypes=['secret_text','secret_key'],liveBindings=(settings?.bindings||[]).filter(b=>!secretTypes.includes(b.type)),wantBindings=(entry.metadata?.bindings||[]).filter(b=>!secretTypes.includes(b.type));
const typeClash=wantBindings.filter(w=>liveBindings.some(l=>l.name===w.name&&l.type!==w.type)).map(w=>w.name);if(typeClash.length)throw new ChamberError('Binding type differs between production and the release manifest: '+typeClash.join(', '),409);
const settingClash=[];for(const w of wantBindings){const l=liveBindings.find(x=>x.name===w.name&&x.type===w.type);if(!l)continue;for(const k of Object.keys(w))if(!['name','type'].includes(k)&&k in l&&JSON.stringify(l[k])!==JSON.stringify(w[k]))settingClash.push(w.name+'.'+k)}const effective=wantBindings.map(w=>liveBindings.find(l=>l.name===w.name&&l.type===w.type)||w);
const carried=liveBindings.filter(l=>!wantBindings.some(w=>w.name===l.name));
const liveSecrets=new Set((settings?.bindings||[]).filter(b=>secretTypes.includes(b.type)).map(b=>b.name));const missing=(entry.required_secret_names||[]).filter(n=>!liveSecrets.has(n));if(missing.length)throw new ChamberError('Production is missing required secrets: '+missing.join(', '),409);
const crons=x=>JSON.stringify((x||[]).map(s=>typeof s==='string'?s:s.cron).sort());const liveCrons=crons(schedules?.schedules),cronDrift=liveCrons!==crons(entry.schedules);
return {previous_version:versionId,previous_deployment:dep.id,source_sha256:sourceSha,baseline,bindings:[...effective,...carried],carried:carried.map(b=>b.name+':'+b.type),settingDrift:settingClash,liveCrons,cronDrift:cronDrift?'production '+liveCrons+' kept (manifest lists '+crons(entry.schedules)+')':''}}
function chamberCommercialGuard(name,entry){if(name!=='projectzero-commercial')return;const b=entry.metadata?.bindings||[],find=n=>b.find(x=>x.name===n);if(find('CUSTOMER_ACCESS')?.text!=='disabled'&&!(find('CUSTOMER_ACCESS')?.text==='enabled'&&find('GOOGLE_LOGIN_MODE')?.text==='owner_only'))throw new ChamberError('Commercial customer access must stay disabled or owner-only',409)}
async function chamberLock(env,name,holder){const now=new Date().toISOString(),until=new Date(Date.now()+10*60000).toISOString();await env.PORTFOLIO.prepare('DELETE FROM vault_locks WHERE name=? AND expires_at<?').bind(name,now).run();const r=await env.PORTFOLIO.prepare('INSERT OR IGNORE INTO vault_locks(name,holder,expires_at) VALUES(?,?,?)').bind(name,holder,until).run();return r?.meta?.changes===1}
async function agentDeploy(req,env){if(req.method!=='POST')return agentJson({error:'Method not allowed'},405);const agent=await agentAuth(req,env).catch(()=>null);if(!agent)return agentJson({error:'Unauthorized'},401);if(!req.headers.get('content-type')?.startsWith('application/json'))return agentJson({error:'Expected JSON'},415);const raw=await req.text();if(raw.length>2000)return agentJson({error:'Too large'},413);let p;try{p=JSON.parse(raw)}catch{return agentJson({error:'Invalid JSON'},400)}const ws=VAULT_WORKSPACE,actor=agent.actor;const name=p?.worker,mode=p?.mode||'preflight';if(!p||typeof p!=='object'||Object.keys(p).some(k=>!['worker','commit','mode','version_id'].includes(k))||!VAULT_DEPLOYABLE.includes(name)||!['preflight','deploy','rollback'].includes(mode))return agentJson({error:'Expected {worker, commit, mode: preflight|deploy|rollback}'},400);if(mode!=='rollback'&&!/^[0-9a-f]{40}$/.test(p.commit||''))return agentJson({error:'commit must be a full 40-character SHA'},400);if(mode==='rollback'&&!/^[0-9a-f-]{36}$/.test(p.version_id||''))return agentJson({error:'version_id required for rollback'},400);
const recent=await env.PORTFOLIO.prepare("SELECT COUNT(*) n FROM vault_audit WHERE workspace_id=? AND action IN ('Preflight','Deploy','Rollback','Denied') AND at>?").bind(ws,new Date(Date.now()-3600000).toISOString()).first().catch(()=>null);if(!recent)return agentJson({error:'Chamber storage unavailable'},503);if(Number(recent.n)>=20)return agentJson({error:'Rate limit: 20 deploy actions per hour'},429);
const key=await vaultKey(env,ws);if(!key)return agentJson({error:'Chamber locked: VAULT_MASTER_KEY is not configured'},503);let locked=false;const lockName='deploy:'+name;const deny=async(e)=>{await vaultAudit(env,ws,null,'Denied',actor,mode+' '+name+(p.commit?' @'+p.commit.slice(0,12):'')+': '+e.message);return agentJson({error:e.message,worker:name,mode},e.status||500)};
try{if(!await chamberLock(env,lockName,actor+':'+crypto.randomUUID()))throw new ChamberError('Another deploy action for '+name+' is in progress',409);locked=true;
const purpose=mode+' '+name+(p.commit?' @'+p.commit.slice(0,12):' → '+p.version_id);const [tok,acct,man,ghk]=await Promise.all(VAULT_DEPLOY_SECRETS.map(spec=>vaultUseSpec(env,ws,key,spec,actor,purpose)));if(!tok||!acct||!man)throw new ChamberError('Chamber is missing '+[!tok&&'cloudflare-deploy-token',!acct&&'cloudflare-account-id',!man&&'build-manifest'].filter(Boolean).join(', '),412);let manifest;try{manifest=JSON.parse(man.value)}catch{throw new ChamberError('Stored build manifest is not valid JSON',412)}const entry=manifest.workers?.[name];if(!entry?.metadata||!entry.replacements)throw new ChamberError('Build manifest has no complete entry for '+name,412);chamberCommercialGuard(name,entry);const cfTok=tok.value,account=acct.value,ghTok=ghk?.value||'';
if(mode==='rollback'){const versions=await chamberCfJson(cfTok,account,name+'/versions?per_page=50');const known=(versions?.items||versions||[]).some(v=>v.id===p.version_id);if(!known)throw new ChamberError('Unknown version for '+name,404);const dep=await chamberCfJson(cfTok,account,name+'/deployments');const previous=dep?.deployments?.[0]?.versions?.[0]?.version_id||'';await chamberCfJson(cfTok,account,name+'/deployments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({strategy:'percentage',versions:[{percentage:100,version_id:p.version_id}],annotations:{'workers/message':'Chamber rollback by '+actor}})});await vaultAudit(env,ws,null,'Rollback',actor,name+': '+previous+' → '+p.version_id);return agentJson({worker:name,mode,previous_version:previous,active_version:p.version_id,status:'rolled back; verify live now'})}
const cmp=await chamberGitHub('/compare/'+p.commit+'...main',ghTok);if(!['ahead','identical'].includes(cmp?.status))throw new ChamberError('Commit '+p.commit.slice(0,12)+' is not on main; merge the reviewed pull request first',409);const checks=await chamberGitHub('/commits/'+p.commit+'/check-runs?per_page=100',ghTok);const runs=checks?.check_runs||[];if(!runs.length||runs.some(c=>c.status!=='completed'||!['success','neutral','skipped'].includes(c.conclusion)))throw new ChamberError('Checks for '+p.commit.slice(0,12)+' are missing, running or failing',409);
const template=await chamberGitHub('/'+p.commit+'/workers/'+name+'/worker.mjs',ghTok,true);const candidate=chamberRestore(template,entry.replacements);const candidateSha=await vaultSha(candidate);
const live=await chamberObserve(cfTok,account,name,entry,ghTok);const plan={worker:name,commit:p.commit,mode,baseline:live.baseline,previous_version:live.previous_version,previous_deployment:live.previous_deployment,live_source_sha256:live.source_sha256,candidate_sha256:candidateSha,change:candidateSha===live.source_sha256?'no-op':'source change',bindings:live.carried.length?'kept from production (add to build manifest): '+live.carried.join(', '):'match manifest',binding_settings:live.settingDrift.length?'production values kept for '+live.settingDrift.join(', ')+' (update build manifest)':'match manifest',schedules:live.cronDrift||'match manifest',checks:runs.length};
if(mode==='preflight'){await vaultAudit(env,ws,null,'Preflight',actor,name+' @'+p.commit.slice(0,12)+' '+plan.change);return agentJson({...plan,status:'preflight passed; nothing deployed'})}
if(plan.change==='no-op'){await vaultAudit(env,ws,null,'Deploy',actor,name+' @'+p.commit.slice(0,12)+' no-op');return agentJson({...plan,status:'no-op; already live'})}
const metadata={...entry.metadata,main_module:'worker.js',bindings:live.bindings,keep_bindings:['secret_text','secret_key'],annotations:{'workers/tag':p.commit,'workers/message':'Chamber release by '+actor}};const form=new FormData();form.append('metadata',new Blob([JSON.stringify(metadata)],{type:'application/json'}));form.append('worker.js',new Blob([candidate],{type:'application/javascript+module'}),'worker.js');await chamberCfJson(cfTok,account,name,{method:'PUT',body:form});const after=await chamberCfJson(cfTok,account,name+'/deployments');const newVersion=after?.deployments?.[0]?.versions?.[0]?.version_id||'';
const liveAfter=await vaultSha(await chamberLiveSource(cfTok,account,name));await vaultAudit(env,ws,null,'Deploy',actor,name+' @'+p.commit.slice(0,12)+': '+live.previous_version+' → '+newVersion+(liveAfter===candidateSha?'':' (live hash mismatch)'));if(liveAfter!==candidateSha)throw new ChamberError('Uploaded, but live source does not match the build. Roll back to '+live.previous_version+' and investigate.',502);const cronsAfter=JSON.stringify(((await chamberCfJson(cfTok,account,name+'/schedules'))?.schedules||[]).map(s=>s.cron).sort());if(cronsAfter!==live.liveCrons)throw new ChamberError('Uploaded, but cron schedules changed; restore them and investigate',502);return agentJson({...plan,new_version:newVersion,rollback:{mode:'rollback',worker:name,version_id:live.previous_version},status:'deployed; verify live now'})}
catch(e){return deny(e instanceof ChamberError?e:new ChamberError('Deploy action failed: '+String(e?.message||e).slice(0,200),500))}finally{if(locked)await env.PORTFOLIO.prepare('DELETE FROM vault_locks WHERE name=?').bind(lockName).run().catch(()=>{})}}

// ---- Remote MCP: stateless Streamable HTTP, explicit per-assistant grants ----
// Existing tracker keys are accepted only after an owner opts in. No raw vault
// values, arbitrary HTTP requests, SQL, or credential export are MCP capabilities.
const MCP_VERSIONS=['2025-11-25','2025-06-18','2025-03-26'];
const MCP_SCOPES={'tracker.read':'Read portfolio and tasks','tracker.write':'Update tasks and owner actions','chamber.read':'Inspect Chamber credential readiness (metadata only)','deploy.preflight':'Run guarded release preflight','deploy.write':'Deploy or rollback reviewed Project Zero releases','stripe.refresh':'Refresh private Stripe reporting snapshots'};
const mcpStr=(maxLength=100)=>({type:'string',maxLength});
const mcpId={type:'string',pattern:'^[A-Z0-9-]{1,48}$'};
const mcpRevision={type:'integer',minimum:1};
const mcpWorker={type:'string',enum:VAULT_DEPLOYABLE};
const mcpCommit={type:'string',pattern:'^[0-9a-f]{40}$'};
const mcpTool=(name,description,scope,properties={},required=[],readOnly=true)=>({name,description,scope,inputSchema:{type:'object',properties,required,additionalProperties:false},annotations:{readOnlyHint:readOnly,destructiveHint:!readOnly,openWorldHint:true}});
const MCP_TOOLS=[
 mcpTool('get_instructions','Read authoritative Project Zero operating instructions.','tracker.read'),
 mcpTool('list_projects','List active portfolio projects.','tracker.read'),
 mcpTool('list_tasks','List tasks in priority order, optionally filtered and paginated.','tracker.read',{project:mcpStr(),priority:{type:'string',enum:['P0','P1','P2','Exposure']},status:mcpStr(),owner:mcpStr(),limit:{type:'integer',minimum:1,maximum:100},offset:{type:'integer',minimum:0,maximum:10000}}),
 mcpTool('get_task','Read task details and current revision before any update.','tracker.read',{task_id:mcpId},['task_id']),
 mcpTool('update_task','Update an existing task using its current revision. Done requires verified evidence.','tracker.write',{task_id:mcpId,revision:mcpRevision,priority:mcpStr(20),task:mcpStr(1000),status:mcpStr(40),owner:mcpStr(),due_date:mcpStr(80),evidence:mcpStr(16000),notes:mcpStr(24000)},['task_id','revision'],false),
 mcpTool('list_owner_actions','List open decisions requiring the owner.','tracker.read'),
 mcpTool('get_owner_action','Read an owner action and response before updating.','tracker.read',{task_id:mcpId},['task_id']),
 mcpTool('update_owner_action','Create or update an owner action; only the owner marks Responded.','tracker.write',{task_id:mcpId,revision:{type:'integer',minimum:0},instructions:mcpStr(12000),action_status:{type:'string',enum:['Needed','Resolved']}},['task_id','revision'],false),
 mcpTool('chamber_status','List owner Chamber credential names, project, kind and state. Never returns secret values, hints, ciphertext or configuration.','chamber.read'),
 mcpTool('release_preflight','Use Chamber deployment credentials internally to check a merged, tested commit against live production. Does not deploy.','deploy.preflight',{worker:mcpWorker,commit:mcpCommit},['worker','commit'],false),
 mcpTool('release_deploy','Deploy a reviewed, merged Project Zero commit through existing release gates. Requires explicit deployment authorization.','deploy.write',{worker:mcpWorker,commit:mcpCommit,confirm:{type:'string',enum:['deploy']}},['worker','commit','confirm'],false),
 mcpTool('release_rollback','Roll back an authorized Project Zero Worker to a known version.','deploy.write',{worker:mcpWorker,version_id:{type:'string',pattern:'^[0-9a-f-]{36}$'},confirm:{type:'string',enum:['rollback']}},['worker','version_id','confirm'],false),
 mcpTool('refresh_stripe_reports','Refresh private aggregate Stripe snapshots using existing Chamber connections. Returns status only; no payment mutations.','stripe.refresh',{},[],false)
];
function mcpValid(schema,a){if(!a||typeof a!=='object'||Array.isArray(a)||schema.required.some(k=>!Object.hasOwn(a,k)))return false;return Object.entries(a).every(([k,v])=>{const p=schema.properties[k];if(!Object.hasOwn(schema.properties,k)||!p)return false;if(p.type==='string'&&(typeof v!=='string'||(p.maxLength&&v.length>p.maxLength)||(p.pattern&&!new RegExp(p.pattern).test(v))))return false;if(p.type==='integer'&&(!Number.isSafeInteger(v)||v<(p.minimum??0)||v>(p.maximum??Number.MAX_SAFE_INTEGER)))return false;return !p.enum||p.enum.includes(v)})}
async function mcpBounded(req,max){if(Number(req.headers.get('Content-Length')||0)>max)throw new ChamberError('Request too large',413);const reader=req.body?.getReader();if(!reader)return '';let size=0,out='';const decoder=new TextDecoder();try{while(true){const {done,value}=await reader.read();if(done)break;size+=value.byteLength;if(size>max){await reader.cancel();throw new ChamberError('Request too large',413)}out+=decoder.decode(value,{stream:true})}return out+decoder.decode()}finally{reader.releaseLock()}}
