function mcpScopeFields(selected){return '<div class="mcp-scopes">'+Object.entries(MCP_SCOPE_DETAILS).map(([s,[label,desc]])=>'<label class="mcp-option"><input type="checkbox" name="scope" value="'+s+'"'+(selected.includes(s)?' checked':'')+'><span>'+esc(label)+'<small>'+esc(desc)+'</small></span></label>').join('')+'</div>'}
const mcpConfirm=(label='Confirm permission changes')=>'<label class="mcp-option mcp-confirm"><input type="checkbox" name="confirm" value="yes" required><span>'+esc(label)+'</span></label>';
