 if(!await vaultAudit(env,VAULT_WORKSPACE,null,'Used',agent.actor,'MCP '+tool.name))return mcpResult({error:'Chamber audit unavailable'},true);
 if(tool.name==='chamber_status'){
  const rows=await env.PORTFOLIO.prepare('SELECT name,project,kind,status,revision FROM vault_secrets WHERE workspace_id=? ORDER BY name LIMIT 200').bind(VAULT_WORKSPACE).all();
  return mcpResult({locked:!await vaultKey(env,VAULT_WORKSPACE),credentials:rows.results});
 }
 if(tool.name==='refresh_stripe_reports')return mcpResult({status:await stripeRefresh(env)});
 const mode=tool.name==='release_preflight'?'preflight':tool.name==='release_deploy'?'deploy':'rollback';
 const res=await agentDeploy(new Request(req.url,{method:'POST',headers:{Authorization:authorization,'Content-Type':'application/json'},body:JSON.stringify({worker:args.worker,mode,...(args.commit?{commit:args.commit}:{version_id:args.version_id})})}),env);
