  if(p.method==='resources/list'||p.method==='resources/templates/list'||p.method==='prompts/list')return rpc(id,{[p.method==='resources/list'?'resources':p.method==='prompts/list'?'prompts':'resourceTemplates']:[]});
  if(p.method==='tools/call'&&MCP_TOOLS.some(t=>t.name===p.params?.name))return rpc(id,{content:[{type:'text',text:'Sign in to Project Zero and authorize this connection before using its tools.'}],isError:true,_meta:{'mcp/www_authenticate':[MCP_AUTH_CHALLENGE]}});
