  if(!rate)return error(id,-32000,'Rate limit exceeded',429);
  if(dedicated)await env.PORTFOLIO.prepare('UPDATE mcp_connections SET last_seen_at=? WHERE id=? AND (last_seen_at IS NULL OR last_seen_at<?)').bind(new Date().toISOString(),agent.id,new Date(Date.now()-60000).toISOString()).run();
