  if(p.method==='tools/list')return rpc(id,{tools:mcpDescriptors(tools)});
  if(p.method==='resources/list')return rpc(id,{resources:scopes.includes('tracker.read')?[{uri:'projectzero://instructions',name:'Development instructions',mimeType:'application/json'},{uri:'projectzero://projects',name:'Active projects',mimeType:'application/json'}]:[]});
