const mcpOAuthError=(error,status=400)=>mcpOAuthJson({error},status);
const mcpOAuthNow=()=>Math.floor(Date.now()/1000);
const mcpOAuthRedirectOk=uri=>typeof uri==='string'&&(/^https:\/\/chatgpt\.com\/connector_platform_oauth_redirect$/.test(uri)||/^https:\/\/chatgpt\.com\/connector\/oauth\/[A-Za-z0-9_-]{1,128}$/.test(uri));
const mcpOAuthScopes=s=>typeof s==='string'&&s.split(/ +/).every(x=>['projectzero','offline_access',''].includes(x));
const mcpOAuthResource=f=>f.getAll('resource').length===1&&f.get('resource')===MCP_ENDPOINT;
const mcpOAuthClean=f=>[...new Set(f.keys())].every(k=>f.getAll(k).length===1);
const mcpOAuthChallenge=async verifier=>btoa(String.fromCharCode(...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier))))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
function mcpOAuthCallback(row,fields){const u=new URL(row.redirect_uri);for(const [k,v] of Object.entries({...fields,state:row.state,iss:MCP_ISSUER}))u.searchParams.set(k,v);return pzDashRedirect(u.href,{'Set-Cookie':mcpOAuthCookieHeader('',0)})}
async function mcpOAuthPage(req,env,ctx,row,id){
 if(!row||row.expires_at<=mcpOAuthNow()||row.used_at||row.code_hash)return response('Connection request expired. Restart authorization in ChatGPT.',400);
 const authEnv={ACCESS_AUD:env.PROJECT_ZERO_AUD,ACCESS_ISSUER:env.ACCESS_ISSUER,OWNER_EMAIL:env.OWNER_EMAIL};
 if(!await pzGoogleSession(req,env)&&(!authEnv.ACCESS_AUD||!await authorized(req,authEnv,ctx)))return pzDashRedirect(PZ_ACCOUNT+'/auth/dashboard',{'Set-Cookie':mcpOAuthCookieHeader(id,600)});
 // Rotate the pre-login request handle into a one-time owner-only consent handle.
 // A rendered form then survives another tab overwriting the temporary login cookie.
 const consent=pzToken(),rotated=await env.PORTFOLIO.prepare('UPDATE mcp_oauth_requests SET id=? WHERE id=? AND expires_at>? AND used_at IS NULL AND code_hash IS NULL RETURNING id').bind(await vaultSha('consent:'+consent),row.id,mcpOAuthNow()).first();
 if(!rotated)return response('Connection request expired. Restart authorization in ChatGPT.',400);
 const r=mcpPage('<section class="mcp-box mcp-consent"><div class="mcp-card-top"><h2>Authorize ChatGPT</h2><span class="mcp-badge on">Owner verified</span></div><p>Choose permissions for this connection once. Manage them later under MCP integration. Chamber secret values are never shared.</p><form method="post" action="/oauth/authorize"><input type="hidden" name="request" value="'+esc(consent)+'">'+mcpScopeFields(['tracker.read'])+mcpConfirm('I authorize the selected permissions')+'<div class="mcp-actions"><button class="mcp-btn" type="submit" name="decision" value="allow">Authorize connection</button><button class="mcp-btn secondary" type="submit" name="decision" value="deny" formnovalidate>Cancel</button></div></form></section>');
 r.headers.set('Set-Cookie',mcpOAuthCookieHeader(consent,600));r.headers.set('Referrer-Policy','no-referrer');r.headers.set('X-Frame-Options','DENY');return r;
}
async function mcpOAuthRoute(req,env,ctx){
 const u=new URL(req.url),path=u.pathname,db=env.PORTFOLIO,now=mcpOAuthNow();
 if(req.method==='GET'&&path.startsWith('/.well-known/oauth-protected-resource'))return mcpOAuthJson({resource:MCP_ENDPOINT,authorization_servers:[MCP_ISSUER],scopes_supported:['projectzero'],bearer_methods_supported:['header']});
 if(req.method==='GET'&&path==='/.well-known/oauth-authorization-server')return mcpOAuthJson({issuer:MCP_ISSUER,authorization_endpoint:MCP_ISSUER+'/oauth/authorize',token_endpoint:MCP_ISSUER+'/oauth/token',registration_endpoint:MCP_ISSUER+'/oauth/register',response_types_supported:['code'],grant_types_supported:['authorization_code','refresh_token'],token_endpoint_auth_methods_supported:['none'],code_challenge_methods_supported:['S256'],scopes_supported:['projectzero','offline_access'],authorization_response_iss_parameter_supported:true});
 if(!db)return mcpOAuthError('temporarily_unavailable',503);
 try{
  if(path==='/oauth/register'&&req.method==='POST'){
   if(!req.headers.get('Content-Type')?.startsWith('application/json'))return mcpOAuthError('invalid_client_metadata');
   const p=JSON.parse(await mcpBounded(req,12000));
   if(!p||!Array.isArray(p.redirect_uris)||p.redirect_uris.length!==1||!mcpOAuthRedirectOk(p.redirect_uris[0])||!['none',undefined].includes(p.token_endpoint_auth_method)||p.grant_types?.some(x=>!['authorization_code','refresh_token'].includes(x))||p.response_types?.some(x=>x!=='code'))return mcpOAuthError('invalid_client_metadata');
   const redirect=p.redirect_uris[0];
   let client=await db.prepare('SELECT client_id FROM mcp_oauth_clients WHERE redirect_uri=?').bind(redirect).first();
   if(!client){
    const id=pzToken();
    await db.prepare('INSERT OR IGNORE INTO mcp_oauth_clients(client_id,redirect_uri,created_at) SELECT ?,?,? WHERE (SELECT COUNT(*) FROM mcp_oauth_clients)<200').bind(id,redirect,now).run();
    client=await db.prepare('SELECT client_id FROM mcp_oauth_clients WHERE redirect_uri=?').bind(redirect).first();
   }
   if(!client)return mcpOAuthError('temporarily_unavailable',503);
   return mcpOAuthJson({client_id:client.client_id,client_name:'ChatGPT',redirect_uris:[redirect],token_endpoint_auth_method:'none',grant_types:['authorization_code','refresh_token'],response_types:['code']},201);
  }
  if(path==='/oauth/authorize'&&req.method==='GET'){
   const f=u.searchParams,client=await db.prepare('SELECT * FROM mcp_oauth_clients WHERE client_id=?').bind(f.get('client_id')||'').first();
   if(!client||client.redirect_uri!==f.get('redirect_uri')||!mcpOAuthRedirectOk(client.redirect_uri)||!mcpOAuthClean(f)||f.get('response_type')!=='code'||f.get('code_challenge_method')!=='S256'||!pzTokenOk(f.get('code_challenge'))||!f.get('state')||f.get('state').length>1024||!mcpOAuthResource(f)||!mcpOAuthScopes(f.get('scope')||''))return mcpOAuthError('invalid_request');
   const id=pzToken(),hash=await vaultSha(id);
   await db.prepare('DELETE FROM mcp_oauth_requests WHERE expires_at<=?').bind(now).run();
   const r=await db.prepare('INSERT INTO mcp_oauth_requests(id,client_id,redirect_uri,state,challenge,expires_at) SELECT ?,?,?,?,?,? WHERE (SELECT COUNT(*) FROM mcp_oauth_requests)<500').bind(hash,client.client_id,client.redirect_uri,f.get('state'),f.get('code_challenge'),now+600).run();
   if(r.meta?.changes!==1)return mcpOAuthError('temporarily_unavailable',503);
   const row=await db.prepare('SELECT * FROM mcp_oauth_requests WHERE id=?').bind(hash).first();
   return mcpOAuthPage(req,env,ctx,row,id);
  }
  if(path==='/oauth/authorize/resume'&&req.method==='GET'){
   const id=mcpOAuthCookie(req);if(!id)return response('No pending connection. Restart authorization in ChatGPT.',400);
   return mcpOAuthPage(req,env,ctx,await db.prepare('SELECT * FROM mcp_oauth_requests WHERE id=? OR id=?').bind(await vaultSha(id),await vaultSha('consent:'+id)).first(),id);
  }
  if(path==='/oauth/authorize'&&req.method==='POST'){
   if(!sameOriginPost(req)||!req.headers.get('Content-Type')?.startsWith('application/x-www-form-urlencoded'))return response('Forbidden',403);
   const authEnv={ACCESS_AUD:env.PROJECT_ZERO_AUD,ACCESS_ISSUER:env.ACCESS_ISSUER,OWNER_EMAIL:env.OWNER_EMAIL};
   if(!await pzGoogleSession(req,env)&&(!authEnv.ACCESS_AUD||!await authorized(req,authEnv,ctx)))return response('Owner sign-in required',403);
   const f=new URLSearchParams(await mcpBounded(req,4000)),id=f.get('request');
   if(!pzTokenOk(id)||f.getAll('request').length!==1)return response('Invalid connection request. Restart authorization in ChatGPT.',400);
   const hash=await vaultSha('consent:'+id),row=await db.prepare('SELECT * FROM mcp_oauth_requests WHERE id=? AND expires_at>? AND used_at IS NULL AND code_hash IS NULL').bind(hash,now).first();
   if(!row)return response('Connection request expired',400);
   if(f.get('decision')==='deny'){
    const denied=await db.prepare('UPDATE mcp_oauth_requests SET used_at=? WHERE id=? AND used_at IS NULL AND code_hash IS NULL RETURNING id').bind(now,hash).first();
    return denied?mcpOAuthCallback(row,{error:'access_denied'}):response('Connection already handled',409);
   }
   const scopes=[...new Set(f.getAll('scope'))];
   if(f.get('decision')!=='allow'||f.get('confirm')!=='yes'||!scopes.length||scopes.some(s=>!Object.hasOwn(MCP_SCOPES,s)))return response('Select at least one permission and confirm.',400);
   const code=pzToken(),approved=await db.prepare('UPDATE mcp_oauth_requests SET code_hash=?,scopes=?,expires_at=? WHERE id=? AND expires_at>? AND code_hash IS NULL AND used_at IS NULL RETURNING id').bind(await vaultSha(code),JSON.stringify(scopes),now+120,hash,now).first();
   return approved?mcpOAuthCallback(row,{code}):response('Connection already handled',409);
  }
  if(path==='/oauth/token'&&req.method==='POST'){
   if(!req.headers.get('Content-Type')?.startsWith('application/x-www-form-urlencoded')||req.headers.has('Authorization'))return mcpOAuthError('invalid_request');
   const f=new URLSearchParams(await mcpBounded(req,10000));
   if(!mcpOAuthClean(f)||!mcpOAuthResource(f)||f.has('client_secret')||!mcpOAuthScopes(f.get('scope')||''))return mcpOAuthError('invalid_request');
   const client=await db.prepare('SELECT * FROM mcp_oauth_clients WHERE client_id=?').bind(f.get('client_id')||'').first();if(!client)return mcpOAuthError('invalid_client',401);
   const access=mcpToken('pzo_'),refresh=mcpToken('pzr_'),accessHash=await vaultSha(access),refreshHash=await vaultSha(refresh);
   if(f.get('grant_type')==='authorization_code'){
    const code=f.get('code'),verifier=f.get('code_verifier');
    if(!pzTokenOk(code)||!verifier||!/^[A-Za-z0-9._~-]{43,128}$/.test(verifier)||f.get('redirect_uri')!==client.redirect_uri)return mcpOAuthError('invalid_grant');
    const row=await db.prepare('UPDATE mcp_oauth_requests SET used_at=? WHERE code_hash=? AND client_id=? AND redirect_uri=? AND challenge=? AND expires_at>? AND used_at IS NULL RETURNING scopes').bind(now,await vaultSha(code),client.client_id,client.redirect_uri,await mcpOAuthChallenge(verifier),now).first();
    if(!row)return mcpOAuthError('invalid_grant');
    const connection=await mcpProvisionConnection(env,'ChatGPT','ChatGPT · OAuth',JSON.parse(row.scopes));
    if(connection instanceof Response)return mcpOAuthError('temporarily_unavailable',503);
    try{await db.prepare('INSERT INTO mcp_oauth_sessions(connection_id,client_id,access_hash,refresh_hash,access_expires) VALUES(?,?,?,?,?)').bind(connection.id,client.client_id,accessHash,refreshHash,now+3600).run()}catch{
     const failed=await db.prepare("UPDATE mcp_connections SET revoked_at=?,ciphertext='',iv='',scopes='[]' WHERE id=? RETURNING tracker_key_id").bind(new Date().toISOString(),connection.id).first();if(failed)await env.TRACKER.prepare('UPDATE tracker_api_keys SET revoked_at=? WHERE id=?').bind(new Date().toISOString(),failed.tracker_key_id).run();return mcpOAuthError('temporarily_unavailable',503)
    }
   }else if(f.get('grant_type')==='refresh_token'){
    const prev=f.get('refresh_token');if(!prev||!/^pzr_[0-9a-f]{64}$/.test(prev))return mcpOAuthError('invalid_grant');
    const updated=await db.prepare("UPDATE mcp_oauth_sessions SET access_hash=?,refresh_hash=?,access_expires=? WHERE refresh_hash=? AND client_id=? AND EXISTS(SELECT 1 FROM mcp_connections c WHERE c.id=mcp_oauth_sessions.connection_id AND c.revoked_at IS NULL AND c.expires_at>? AND c.scopes!='[]') RETURNING connection_id").bind(accessHash,refreshHash,now+3600,await vaultSha(prev),client.client_id,new Date().toISOString()).first();
    if(!updated)return mcpOAuthError('invalid_grant');
   }else return mcpOAuthError('unsupported_grant_type');
   return mcpOAuthJson({access_token:access,token_type:'Bearer',expires_in:3600,refresh_token:refresh,scope:'projectzero offline_access'});
  }
  return mcpOAuthError('invalid_request',405);
 }catch{return mcpOAuthError('temporarily_unavailable',503)}
}

